const HEXAGRAMS = [
  { no: 1,  name: '乾',   full: '乾为天',   upper: '乾', lower: '乾', gong: '金', shi: 6, tuan: '元，亨，利，贞。', xiang: '天行健，君子以自强不息。', read: '刚健中正，万事当奋发有为，宜进取不宜守成。',
    meaning: '乾卦是六十四卦之首，纯阳之卦，六爻皆九，讲的是一条龙从深渊到九天的完整生命轨迹。卦辞「元亨利贞」四字，是天道运行的四种德性：元=万物之始，亨=万物通达，利=万物各得其宜，贞=万物各正其性——春生、夏长、秋收、冬藏，天道的全部节奏都压缩在这四个字里。但乾卦真正要说的不是天，而是人——一个有大才大志的人，如何像龙一样知进退、识时务，从蛰伏走到巅峰，又在巅峰之后全身而退。六爻就是六个阶段：潜、现、惕、跃、飞、亢，画出一条先升后降的抛物线，告诉你天道的铁律——盈必有亏，满则招损。',
    gaoTuan: '「元亨利贞」者，乃天地之德也。元者，始也，万物之始；亨者，通也，万物之通；利者，宜也，万物之宜；贞者，正也，万物之正。此四字乃伏羲画卦之初，即已具之于乾卦，以明示天道之运行。乾为天，天为万物之祖，故乾卦居六十四卦之首。人能体此四德，则可以与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。',
    fortune: '目下正是鸿运当头之时，有威仪，有光耀，声名远播，上达之象，吉。',
    business: '买者卖者，一时云集，有货物旺销之象，大吉，宜进取。',
    career: '功名显达，有贵人提携，青云直上之兆。',
    warfare: '军威大振，战无不胜，攻无不克，然须慎终如始，方保无虞。',
    marriage: '阴阳一气，定必百年好合，吉。',
    illness: '是郁热心热之症，势颇危笃，宜速治，宜求良医。',
    lawsuit: '事必得直，判决明允，吉。',
    lost: '失物已被人藏匿，急索可得，迟则难寻。',
    pregnancy: '生男，且生贵子。',
    home: '家宅兴隆，人口平安，然须防火烛。',
    weather: '天气晴朗，阳光普照，宜出行。',
    traveler: '行人即日便归，且有佳音。',
    yaos: [
      { text: '潜龙，勿用。', xiang: '潜龙勿用，阳在下也。', meaning: '初九居最下位，是龙的第一个状态：「潜」。潜=藏在水底，完全不露头；龙=阳气之精、大才之象，但此刻它蜷缩在深渊之下，谁也看不见它。「勿用」不是「没有用」，而是「不要去用」——你有屠龙之才，但时机未到，不可轻举妄动。这就是姜太公在渭水垂钓的七十年：满腹经纶，却甘心做一个无名老翁，因为他知道自己的时代还没有来。潜龙的功夫在于「忍」——不是没有力量，而是把力量全部压在水面之下，等待属于自己的那一声雷响。' },
      { text: '见龙在田，利见大人。', xiang: '见龙在田，德施普也。', meaning: '九二已经从深渊升到地面，龙终于露出了真身。「见龙在田」就是君子出现在世间，开始施展才华。「利见大人」有两层含义：一是利于见到有德位的人，获得赏识和机会；二是自身要成为「大人」，以仁德普施于民。这是人生的第二个阶段：崭露头角，初露锋芒。就像诸葛亮走出隆中，辅佐刘备，开始了他波澜壮阔的一生。' },
      { text: '君子终日乾乾，夕惕若厉，无咎。', xiang: '终日乾乾，反复道也。', meaning: '九三处在下卦的最上位，上承天位，下接地位，是一个非常危险的位置。「终日乾乾」是白天要勤奋努力，自强不息；「夕惕若厉」是晚上也要保持警惕，如临深渊。这是人生最辛苦的阶段：成功在望，但还未到手，稍有不慎就会前功尽弃。就像周文王被囚禁在羑里，虽然胸怀大志，却必须小心翼翼，如履薄冰。' },
      { text: '或跃在渊，无咎。', xiang: '或跃在渊，进无咎也。', meaning: '九四已经进入上卦，是龙准备腾飞的关键时刻。「或跃在渊」是龙在深渊之上跃跃欲试，既可以选择继续潜伏，也可以选择一跃冲天。这是人生的十字路口：进则可能化龙飞天，退则可以保全自身。关键在于审时度势，量力而行。就像韩信在项羽和刘邦之间做出选择，最终选择了明主，成就了一番伟业。' },
      { text: '飞龙在天，利见大人。', xiang: '飞龙在天，大人造也。', meaning: '九五是乾卦的君位，也是整个六十四卦中最吉的爻位。「飞龙在天」是龙终于飞上了九天，成为万众瞩目的焦点。这是人生的巅峰时刻：功成名就，位极人臣。但「利见大人」在这里更重要的意义是：成为大人之后，要以德服人，造福天下。就像尧、舜、禹这样的圣王，虽然高居上位，却依然心系百姓，造福万民。' },
      { text: '亢龙，有悔。', xiang: '亢龙有悔，盈不可久也。', meaning: '上九是乾卦的最后一爻，龙飞到了最高处，再也无法上升。「亢龙有悔」是说处在极盛位置的龙，必然会有所悔恨。这是天道的铁律：物极必反，盛极必衰。就像秦始皇统一六国后，自以为功盖三皇五帝，于是焚书坑儒，大兴土木，最终导致秦朝二世而亡。亢龙的教训是：在巅峰时刻，要懂得收敛，功成身退，才是保全之道。' },
    ]
  },
  { no: 2,  name: '坤',   full: '坤为地',   upper: '坤', lower: '坤', gong: '土', shi: 6, tuan: '元亨，利牝马之贞。君子有攸往，先迷后得主，利。', xiang: '地势坤，君子以厚德载物。', read: '厚德载物，宜柔顺包容，顺势而为则安。',
    meaning: '坤卦是六十四卦的第二卦，纯阴之卦，六爻皆六，与乾卦相对应。如果说乾卦代表天、阳、刚、动，那么坤卦就代表地、阴、柔、静。坤卦的核心是「厚德载物」——大地包容万物，孕育万物，却从不争功，这就是坤德的精髓。卦辞中的「牝马之贞」用母马的柔顺比喻坤德：母马温顺而坚韧，虽然不争不抢，但始终坚守正道。「先迷后得主」告诉我们：在人生的道路上，如果一开始迷失了方向，不要慌张，只要坚持正道，最终会找到正确的归宿。',
    yaos: [
      { text: '履霜，坚冰至。', xiang: '履霜坚冰，阴始凝也。驯致其道，至坚冰也。', meaning: '初六是坤卦的开始，阴气刚刚凝结。「履霜」就是踩到了霜，这意味着冬天即将来临。这一爻告诉我们：任何大事的发生都有其征兆，要善于见微知著，防患于未然。当你看到第一片霜的时候，就要想到严寒的冬天就要来了，提前做好准备。' },
      { text: '直，方，大，不习无不利。', xiang: '六二之动，直以方也。不习无不利，地道光也。', meaning: '六二是坤卦的主爻，阴居阴位，得位得中。「直」是正直，「方」是方正，「大」是宽大。这是坤德的完美体现：内心正直，行为方正，胸怀宽大。「不习无不利」是说，具备了这样的品德，即使没有学习过具体的技巧，也不会有什么不利。因为品德是根本，技巧是末节。' },
      { text: '含章可贞。或从王事，无成有终。', xiang: '含章可贞，以时发也。或从王事，知光大也。', meaning: '六三内含文采，却不轻易显露。「含章」是内心有才华有品德，但不炫耀。「可贞」是可以守正。「或从王事，无成有终」是说，有时候会辅佐君王做事，但不居功，最终会有好的结果。这是一种谦虚谨慎、功成不居的态度。' },
      { text: '括囊，无咎无誉。', xiang: '括囊无咎，慎不害也。', meaning: '六四处在上下卦之间，是一个需要谨慎的位置。「括囊」是把口袋扎起来，比喻说话做事要谨慎，不要轻易发表意见。「无咎无誉」是说，这样做虽然不会得到赞誉，但也不会招来灾祸。在复杂的环境中，保持沉默有时候是最好的选择。' },
      { text: '黄裳，元吉。', xiang: '黄裳元吉，文在中也。', meaning: '六五是坤卦的君位，但阴居阳位，所以用「黄裳」来比喻。黄是中色，裳是下装，代表谦虚内敛。「黄裳元吉」是说，虽然处于尊贵的位置，但依然保持谦虚、内敛的态度，这是最大的吉祥。真正的尊贵不在于外在的炫耀，而在于内在的修养。' },
      { text: '龙战于野，其血玄黄。', xiang: '龙战于野，其道穷也。', meaning: '上六是坤卦的最后一爻，阴气达到了极点。「龙战于野」是说，阴与阳在野外交战，龙在这里代表阳气。当阴气太盛的时候，必然会引起阳气的反抗，导致两败俱伤。「其血玄黄」是说，交战双方都流下了血，玄是天色，黄是地色，象征天地都受到了伤害。这一爻告诉我们：物极必反，当阴柔达到极点时，必须有所收敛，否则会引发冲突。' },
    ],
    gaoTuan: '坤为地，地承天而载物，故曰厚德载物。牝马者，柔顺之象也，牝马之贞，即柔而正也。君子有攸往，先迷后得主者，盖坤道柔顺，初则迷于所往，然终能得其所主，此乃顺天应人之道。坤卦纯阴，与乾卦纯阳相对，阴阳相济，万物乃生。人能体坤德，则可以厚德载物，包容万物，而无所不载。'
  },
  { no: 3,  name: '屯',   full: '水雷屯',   upper: '坎', lower: '震', gong: '水', shi: 2, tuan: '元亨，利贞。勿用有攸往，利建侯。', xiang: '云雷屯，君子以经纶。', read: '万物始生，困难中蕴含生机，宜固本待时。',
    meaning: '屯卦象征万物初生时的艰难困苦，云雷郁结未雨，万物萌发却受阻。但困顿之中暗藏勃勃生机，正如创业之初百废待兴，此时不可冒进，应当稳固根基、广结贤能，待时而动方能化险为夷。屯者盈也，物始生而未通达，故须有人辅佐相济，方能济险而成。',
    gaoTuan: '屯者，物始生而未通达之象，云雷郁结，乾坤始交而难生，故曰「勿用有攸往」。然刚柔始交而生物，其中必有元亨之德，唯利建侯以辅之，方能成济屯之功。君子处屯，当经纶天下，慎守正道，缓以图之，乃可有成。',
    yaos: [
      { text: '磐桓，利居贞，利建侯。', xiang: '虽磐桓，志行正也。以贵下贱，大得民也。', meaning: '初九是屯卦之始，阳刚居下，如巨石磐桓不动。「利居贞」是说此时宜安守本分、守正不动，「利建侯」是说应当及早建立根基、广纳贤才。就像创业者起步之初，不宜急于扩张，而应先把团队和根据地打牢，以谦卑姿态赢得人心，方能大得民望。' },
      { text: '屯如邅如，乘马班如，匪寇婚媾，女子贞不字，十年乃字。', xiang: '六二之难，乘刚也。十年乃字，反常也。', meaning: '六二柔居阴位，却被初九所乘，进退两难如骑马徘徊不前。「匪寇婚媾」是说对方并非强寇而是来求婚的，但女子坚守贞节，十年才许嫁。比喻人在困境中不可草率许身，要耐得住寂寞，等待真正值得托付的时机。' },
      { text: '即鹿无虞，惟入于林中，君子几不如舍，往吝。', xiang: '即鹿无虞，以从禽也。君子舍之往吝，穷也。', meaning: '六三柔居刚位，盲目追猎，却没有向导引路，独自闯入林中。「君子几不如舍」是明智之人见机行事，宁可放弃也不冒险深入。这是告诫我们：没有充分准备和向导就贸然行动，必然陷入困窘，知难而退方为上策。' },
      { text: '乘马班如，求婚媾，往吉，无不利。', xiang: '求而往，明也。', meaning: '六四柔居柔位，下应初九，骑马徘徊后决定主动求婚，结果吉利无不利。这告诉我们：当找到真正志同道合的伙伴时，应当主动出击、果断行动，光明正大地追求合作，必有好的结果。' },
      { text: '屯其膏，小贞吉，大贞凶。', xiang: '屯其膏，施未光也。', meaning: '九五阳刚中正居尊位，却陷于坎险之中，恩泽难以广施。「屯其膏」是说膏泽囤积而不能下达，故小处守正则吉，大举行动则凶。这是说身处困境高位，宜小事可为、大事勿动，先固本培元，待时而发。' },
      { text: '乘马班如，泣血涟如。', xiang: '泣血涟如，何可长也。', meaning: '上六居屯卦之极，困顿至极，骑马徘徊，泪血交流。这是困境达到顶点仍找不到出路的惨状，但也意味着物极必反——既然已泣血涟如，便不能再长久持续下去，转机即将来临，关键是别在最后时刻放弃。' },
    ]
  },
  { no: 4,  name: '蒙',   full: '山水蒙',   upper: '艮', lower: '坎', gong: '土', shi: 4, tuan: '亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。', xiang: '山下出泉，蒙；君子以果行育德。', read: '蒙昧待启，宜虚心求教，循序渐进。',
    meaning: '蒙卦象征蒙昧未启，如山下泉水初出，清澈却未经疏导。启蒙之道贵在虚心求教，但教者须有耐心，求学者须有诚心，如同占卜初筮则告、再三则渎。教育之道在于循循善诱，培养品德与行动力，方能化蒙昧为明达。',
    gaoTuan: '蒙者，物之稚也，蒙昧而未明之象。山下出泉，泉之初出必有所蒙，然其清可鉴，是蒙之中固有亨道。匪我求童蒙，童蒙求我者，教之道必待其诚求而后告，初筮告再三渎，言诚意不可渎也。君子以果行育德，乃所以发蒙之功。',
    yaos: [
      { text: '发蒙，利用刑人，用说桎梏，以往吝。', xiang: '利用刑人，以正法也。', meaning: '初六处蒙之始，蒙昧最深，发蒙之初宜用法规约束人，解除其桎梏，但若一味向前必有遗憾。这是说教育之初需要立规矩、明法度，但严刑峻法只能解一时之困，过分依赖则适得其反，正如管教孩子时罚是手段而非目的。' },
      { text: '包蒙吉。纳妇吉，子克家。', xiang: '子克家，刚柔接也。', meaning: '九二刚中居下，能包容群蒙，故吉。娶妇亦吉，子能持家，因为刚柔相济。这是教育者的胸怀：以宽容之心接纳蒙昧之人，宽严相济，刚柔并施，方能成就家业、培育人才，如同严父慈母相辅相成。' },
      { text: '勿用取女，见金夫，不有躬，无攸利。', xiang: '勿用取女，行不顺也。', meaning: '六三阴柔不中，见利忘义，见到有钱的金夫便失了自身节操。这是告诫：不可娶这种见异思迁的女子，喻指做人不可因利忘义、朝三暮四。人生在世，操守比利益更重要，见钱眼开者终无所成。' },
      { text: '困蒙，吝。', xiang: '困蒙之吝，独远实也。', meaning: '六四阴柔失正，远离阳刚之实，困于蒙昧之中。这是说一个人若闭目塞听、远离贤师益友，便会困于愚昧而不能自拔。正如一个人不愿学习、拒绝指教，最终必然陷入孤立与窘迫。' },
      { text: '童蒙，吉。', xiang: '童蒙之吉，顺以巽也。', meaning: '六五柔顺居尊，有如赤子般纯真求教，故吉。这是说身居高位却保持谦逊好学的态度，顺从善言、虚心纳谏，方能得吉。正如英明的领导者从善如流，以童子之心待人接物，反而成就大业。' },
      { text: '击蒙，不利为寇，利御寇。', xiang: '利用御寇，上下顺也。', meaning: '上九阳居阴位之上，以刚猛击蒙，但不宜主动出击为寇，只宜防御外寇。这是说教育方式不可过猛：当蒙昧之极、不得已而击之，也只能用于抵御外患，不可用于主动攻击。过度的强硬反而招致反抗，宽猛相宜方为正道。' },
    ]
  },
  { no: 5,  name: '需',   full: '水天需',   upper: '坎', lower: '乾', gong: '水', shi: 4, tuan: '有孚，光亨，贞吉。利涉大川。', xiang: '云上于天，需；君子以饮食宴乐。', read: '等待时机，前有险阻，宜耐心蓄力。',
    meaning: '需卦象征等待之道，云升于天而未雨，需要耐心等待时机成熟。等待并非消极懈怠，而是在险前从容蓄力、饮食宴乐，时机一到便可涉险济难。真正的智慧是知道何时该进、何时该等，急则失之，缓则得之。',
    gaoTuan: '需者，须也，事之当须而不可遽进也。坎在前，乾健欲进而陷阻之，故有孚乃光亨。涉险之道，贵在信实以待时，急则失之，缓则得之，斯需之德也。君子以饮食宴乐，养其力以待时，乃能有济。',
    yaos: [
      { text: '需于郊，利用恒，无咎。', xiang: '需于郊，不犯难行也。利用恒无咎，未失常也。', meaning: '初九远离坎险，需于郊外旷野之地，从容等待而不冒险前行。这是说在危险尚未迫近时，应保持平常心，远离是非之地，持之以恒地守正不动，自然无咎，正如办事留有余地方能立于不败。' },
      { text: '需于沙，小有言，终吉。', xiang: '需于沙，衍在中也。虽小有言，以吉终也。', meaning: '九二渐近于险，需于沙滩之地，会招致一些口舌议论，但终得吉利。这是说逐渐接近险境时，难免遭人非议，但只要内心宽裕、坚持正道，最终自有善果，正如做事不怕闲言碎语，关键在内心的定力。' },
      { text: '需于泥，致寇至。', xiang: '需于泥，灾在外也。自我致寇，敬慎不败也。', meaning: '九三逼近坎险，需于泥泞之地，自招贼寇。这是告诫：已临近危险却仍贪进，灾祸便会自招而来。但只要心怀敬畏、谨慎戒备，仍可保身不败，正如身处险地要时刻警觉，方能化险为夷。' },
      { text: '需于血，出自穴。', xiang: '需于血，顺以听也。', meaning: '六四已入坎险之中，需于流血之地，却能从穴中逃出。这是说身陷险境时，唯有顺时听命、柔顺以对，方能从死地中脱身而出。正如人在绝境中不可强争，要审时度势、顺势而为，方能化险为夷。' },
      { text: '需于酒食，贞吉。', xiang: '酒食贞吉，以中正也。', meaning: '九五中正居尊，以饮食宴乐待时，得正而吉。这是需卦之主，说身处正位之时，宜从容饮食、涵养身心，不必急于有所作为，正所谓养精蓄锐方能成大事，正如人在巅峰时反而要懂得沉淀与享受。' },
      { text: '入于穴，有不速之客三人来，敬之终吉。', xiang: '不速之客来，敬之终吉也。虽不当位，未大失也。', meaning: '上六处需之极，退入穴中，却有三位不速之客来访，恭敬相待终得吉利。这是说在最需要谨慎的时刻，即使出现意外变故，只要以礼敬之心应对，便不会有大失。人生总有突如其来的变数，关键是处变不惊、以敬待之。' },
    ]
  },
  { no: 6,  name: '讼',   full: '天水讼',   upper: '乾', lower: '坎', gong: '金', shi: 4, tuan: '有孚，窒。惕中吉。终凶。利见大人，不利涉大川。', xiang: '天与水违行，讼；君子以作事谋始。', read: '争讼之象，宜止争求和，慎防口舌。',
    meaning: '讼卦象征争讼纷扰，天西行水东流，二者背道而驰，故有争讼之象。处讼之道在于适可而止，切勿争到底，惕中则吉、终凶则祸。能止争求和、寻求大人裁断，方为明智；若一味逞强，纵得一时之利，终会失去更多。',
    gaoTuan: '讼者，争也，天水违行而相背，故有争讼之象。窒而惕中，乃吉；终而不已，则凶。盖讼不可长，宜止于中，见大人以求直，不可涉险以自困也。君子作事谋始，乃所以绝讼之源。',
    yaos: [
      { text: '不永所事，小有言，终吉。', xiang: '不永所事，讼不可长也。虽小有言，其辩明也。', meaning: '初六柔弱居下，不能持久争讼，虽有口舌之争，但能见好就收，终得吉利。这是告诫：小事上被人议论几句不必较真，争讼不可久长，适可而止才是智慧。正如邻里小摩擦，互让一步海阔天空。' },
      { text: '不克讼，归而逋，其邑人三百户无眚。', xiang: '不克讼，归逋窜也。自下讼上，患至掇也。', meaning: '九二与九五争讼不胜，退归逃窜，但其三百户邑人得以保全无灾。这是说以下讼上、以弱争强，必然自取其祸，及时退避反而是上策。正如职场中与上司硬顶，不如退一步保全大局。' },
      { text: '食旧德，贞厉，终吉。或从王事，无成。', xiang: '食旧德，从上吉也。', meaning: '六三依凭祖上旧德为生，虽处危厉之境，终得吉利。若从王事，则功成不居。这是说身处争讼之时，宜安分守己、依附先人遗德，不可锋芒太露，正如承继家业者不可冒进，安守祖德方能善终。' },
      { text: '不克讼，复即命，渝，安贞吉。', xiang: '复即命渝，安贞不失也。', meaning: '九四争讼不胜，回头复归本分，改变态度、安守正道而得吉。这是说争讼失败后，能幡然悔悟、回头是岸，重新安守本分，反得吉祥。正如诉讼败诉后接受裁决、改过自新，反而走上正道。' },
      { text: '讼，元吉。', xiang: '讼元吉，以中正也。', meaning: '九五中正居尊，讼而得直，大吉。这是说讼卦之中，唯有得中正之大人主持公道，才能讼而得吉。正如英明的法官审断公允，使善恶各得其所，方能化解纷争、定分止争。' },
      { text: '或锡之鞶带，终朝三褫之。', xiang: '以讼受服，亦不足敬也。', meaning: '上九凭争讼获胜而获赐鞶带，但一日之间竟三次被剥夺。这是说靠争讼得来的名利，纵然一时荣显，也不受人尊敬，最终必将失去。正如靠打官司发家者，纵得一时之财，终难长久，争讼之荣不可恃。' },
    ]
  },
  { no: 7,  name: '师',   full: '地水师',   upper: '坤', lower: '坎', gong: '土', shi: 3, tuan: '贞，丈人，吉无咎。', xiang: '地中有水，师；君子以容民畜众。', read: '兵众之象，宜纪律严明，任用贤能。',
    meaning: '师卦象征兵师众聚，地中有水，水聚于地中如兵藏于民中。兴师之道贵在贞正、任用贤能长者，纪律严明方能吉而无咎。师者众也，凡统众做事，皆须以正道为本、以贤将为先，无律则凶，此用众之道亦牧民之道。',
    gaoTuan: '师者，众也，地中有水，兵藏于民之象。兴师贵正，必以丈人为主，则吉而无咎。盖师出以律，无律则凶，此用众之道，亦牧民之道也。君子容民畜众，正所以畜师之本。',
    yaos: [
      { text: '师出以律，否臧凶。', xiang: '师出以律，失律凶也。', meaning: '初六处师之始，强调出师必须以严明军律为本，若纪律失当，则凶。这是统军的第一要义：无规矩不成方圆。正如企业团队、组织管理，纪律是行动的保障，没有纪律的队伍必然溃败。' },
      { text: '在师中，吉无咎，王三锡命。', xiang: '在师中吉，承天宠也。王三锡命，怀万邦也。', meaning: '九二刚中为师之主，居中统军，吉而无咎，受君王三次嘉奖。这是说统帅必须刚毅中正，居中调度，方能得上宠信、军功卓著。正如贤将得君信任、将士用命，方能成就安邦定国的大业。' },
      { text: '师或舆尸，凶。', xiang: '师或舆尸，大无功也。', meaning: '六三阴柔失位，妄进而败，以至车载尸体而归，大凶。这是说将帅若任用不当、轻举妄动，必然兵败将亡、大败而归。正如用人失察、决策失误，会使整个团队陷入灾难，所谓将失一令，军破千里。' },
      { text: '师左次，无咎。', xiang: '左次无咎，未失常也。', meaning: '六四柔顺得正，知难而退，率军左次驻扎，无咎。这是说在不利时机下，能审时度势、知进退之机，主动撤退以保全实力，反而无咎。正如将帅审时度势、不逞强冒进，方能保全军队、待机再起。' },
      { text: '田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。', xiang: '长子帅师，以中行也。弟子舆尸，使不当也。', meaning: '六五居尊为君，田中有禽宜捉拿，任用长子为帅则无咎，若使少子舆尸则凶。这是说君主兴师须名正言顺，更要任人得当：用老成持重者为将则胜，用年轻妄为之将则败。正如用人须量才授职，不可任人唯亲。' },
      { text: '大君有命，开国承家，小人勿用。', xiang: '大君有命，以正功也。小人勿用，必乱邦也。', meaning: '上六处师之终，大君论功行赏，开国承家，但告诫小人不可任用。这是说战功既成、论功行赏之时，可以封侯建国，但绝不可让小人掌权，否则必乱邦国。正如企业功成之后，须以正道用人，切莫让德不配位者掌权。' },
    ]
  },
  { no: 8,  name: '比',   full: '水地比',   upper: '坎', lower: '坤', gong: '土', shi: 3, tuan: '吉。原筮，元永贞，无咎。不宁方来，后夫凶。', xiang: '地上有水，比；先王以建万国，亲诸侯。', read: '亲比辅助，宜择善而从，团结得安。',
    meaning: '比卦象征亲比辅佐，地上有水，水润大地、亲密无间。比之道在于以诚信亲比于人，择善而从、团结亲附，但比之有道，须比之正人、不可比之匪人。亲附要主动及时，迟疑者必凶，此乃得众之道，亦王道之基。',
    gaoTuan: '比者，亲也，地上有水，水润地而相亲之象。比必以诚，故原筮以元永贞，则无咎。亲比之道，先者吉而后者凶，此乃得众之道，亦王道之基也。先王建万国亲诸侯，正所以尽比之道。',
    yaos: [
      { text: '有孚比之，无咎。有孚盈缶，终来有它，吉。', xiang: '比之初六，有它吉也。', meaning: '初六处比之始，以诚信亲比于人，无咎。诚信如满溢的瓦缶，质朴无华，终能引来意外之吉。这是说与人亲附，贵在诚信为本，纵然质朴无华，亦能赢得人心，正如待人真诚者终有善报。' },
      { text: '比之自内，贞吉。', xiang: '比之自内，不自失也。', meaning: '六二柔中得正，发自内心亲比于贤，守正而吉。这是说亲附要从内心出发，真诚相待，不可失去自我。正如交朋友要真心实意，不卑不亢，方能长久亲附而不失其本。' },
      { text: '比之匪人。', xiang: '比之匪人，不亦伤乎。', meaning: '六三阴柔失正，所比者皆非其人。这是告诫：亲附错人会招致伤害，交友不慎、亲近小人，必受其害。正如俗语所说「近朱者赤，近墨者黑」，择友须慎，亲比必择其正。' },
      { text: '外比之，贞吉。', xiang: '外比于贤，以从上也。', meaning: '六四柔顺得正，亲比于外之贤者，守正而吉。这是说在亲附之时，能择贤而从、辅佐明君，是明智之举。正如臣子择明主而事，辅佐有德之君，方能成就一番事业。' },
      { text: '显比，王用三驱，失前禽。邑人不诫，吉。', xiang: '显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。', meaning: '九五中正居尊，显明亲比，如天子三面围猎，舍去迎面而来的，只取顺势逃去的，邑人不惊惧而吉。这是说大公无私、来者不拒、去者不追，方能得天下之心。正如明君以德服人，不威压、不强求，百姓自然亲附。' },
      { text: '比之无首，凶。', xiang: '比之无首，无所终也。', meaning: '上六处比之极，亲比而无首领，凶。这是说亲附之道须有始有终、有主心骨，若没有首领引领、犹豫迟疑，必无所成。正如团队没有核心领导，必成一盘散沙；做事没有主见，终将一事无成。' },
    ]
  },
  { no: 9,  name: '小畜', full: '风天小畜', upper: '巽', lower: '乾', gong: '木', shi: 1, tuan: '亨。密云不雨，自我西郊。', xiang: '风行天上，小畜；君子以懿文德。', read: '小有蓄积，力量未足，宜养德待时。',
    meaning: '小畜卦象征以小畜大、以柔蓄刚，风行天上，密云未雨。蓄养之道在于以柔克刚、积小成大，力量尚未充盈，宜修养文德、待时而动。凡事不可急于求成，养德蓄势方能有成，斯乃小畜之道。',
    gaoTuan: '小畜者，以小畜大也，风行天上，密云不雨之象。柔得位而上下应之，故能畜乾之刚。然所畜者小，未能大施，唯懿文德以待时，斯乃小畜之道也。君子观此象，以懿文德，养其力以须时。',
    yaos: [
      { text: '复自道，何其咎，吉。', xiang: '复自道，其义吉也。', meaning: '初九阳刚居下，复归自身正道，何咎之有，故吉。这是说在畜养之初，能坚守本分、复归正道，自然无咎而吉。正如做人做事，先要回归本心、守正不移，方能有所作为。' },
      { text: '牵复，吉。', xiang: '牵复在中，亦不自失也。', meaning: '九二刚中得正，与初九相牵复归正道，吉。这是说能与人携手同归正道，彼此相辅相成，亦不失其本。正如同道之人结伴而行，相互提携，方能共成大业而不迷失方向。' },
      { text: '舆说辐，夫妻反目。', xiang: '夫妻反目，不能正室也。', meaning: '九三刚亢不中，与六四相敌，如车脱辐不能行，夫妻反目失和。这是说刚愎自用、不能容人，必致关系破裂、事业受挫。正如夫妻失和、团队内斗，必使整体瘫痪，所谓和气致祥、戾气致殃。' },
      { text: '有孚，血去惕出，无咎。', xiang: '有孚惕出，上合志也。', meaning: '六四柔顺得正，以诚信待上，能脱离血险、出离忧惧，无咎。这是说以诚敬之心事上，能化解危机、化险为夷。正如臣子以忠诚事君、部属以诚信待人，纵处险境亦能逢凶化吉。' },
      { text: '有孚挛如，富以其邻。', xiang: '有孚挛如，不独富也。', meaning: '九五中正居尊，诚信相系如丝相牵，能与邻人共享富贵。这是说身居高位者，诚信固结人心，不独富而能富及邻人。正如成功者能与伙伴共享成果，方能聚拢人心、长保富贵。' },
      { text: '既雨既处，尚德载，妇贞厉。月几望，君子征凶。', xiang: '既雨既处，德积载也。君子征凶，有所疑也。', meaning: '上九处畜之极，雨已下、事已成，宜尚德积载，妇人守贞则厉。月近圆时，君子出征则凶。这是说蓄养之功已成，宜守成养德，不可再贪进。正如事业达一阶段，宜守不宜攻，贪进必生疑败。' },
    ]
  },
  { no: 10, name: '履',   full: '天泽履',   upper: '乾', lower: '兑', gong: '金', shi: 5, tuan: '履虎尾，不咥人，亨。', xiang: '上天下泽，履；君子以辨上下，定民志。', read: '履危而安，谨慎行事可免祸。',
    meaning: '履卦象征以柔履刚、谨慎行事，如踩虎尾而不被咬，履危而得安。履之道在于以礼待人、辨明上下之分、定立人伦之志。身处险境而能守正柔和，方能行而无咎，此乃履虎尾而不咥人之妙。',
    gaoTuan: '履者，礼也，柔履刚也。履虎尾而不咥人，以柔顺履刚健之后，故亨。盖上下有别、尊卑有分，君子辨之以定民志，此乃履之道也。柔能制刚，谦能受益，此履之所以亨也。',
    yaos: [
      { text: '素履，往无咎。', xiang: '素履之往，独行愿也。', meaning: '初九阳刚居下，朴素无华地行走，前往无咎。这是说处世之初，宜以本分朴素之道行事，不计虚华、不慕名利，凭本心去做，自然无咎。正如做人最贵朴实本分，不为外物所惑。' },
      { text: '履道坦坦，幽人贞吉。', xiang: '幽人贞吉，中不自乱也。', meaning: '九二刚中得正，履道宽广平坦，幽居守正之人得吉。这是说走在正道上心境坦荡，如幽居之人不慕荣利、守正不阿，自然得吉。正如君子坦荡荡，不为外物所扰，安于本分则吉。' },
      { text: '眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。', xiang: '眇能视，不足以有明也。跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。', meaning: '六三柔居刚位，如眇者强视、跛者强行，履虎尾而被咬，凶。武人妄图篡位为君。这是说才弱志强、不自量力，强做超出能力之事，必招凶祸。正如才不配位却硬要去争高位，必招灾殃。' },
      { text: '履虎尾，愬愬，终吉。', xiang: '愬愬终吉，志行也。', meaning: '九四近君履危，踩到虎尾却心存恐惧戒慎，终得吉利。这是说身处险境或近君侧，心怀敬畏、谨慎戒惧，方能化险为夷。正如伴君如伴虎，唯有战战兢兢、如履薄冰，方能保全自身。' },
      { text: '夬履，贞厉。', xiang: '夬履贞厉，位正当也。', meaning: '九五刚中居尊，刚决果行，虽得正亦有危厉。这是说身居高位者，行事过于刚决专断，纵使正当亦会有危险。正如领导者不可独断专行，刚愎自用虽正亦危，宜刚柔相济。' },
      { text: '视履考祥，其旋元吉。', xiang: '元吉在上，大有庆也。', meaning: '上九处履之终，回顾所履之道考察吉凶，能周旋返归正道，则大吉。这是说行事之终，要善于反思总结、回视所行，有错能改、归于正道，方有大庆。正如人生行至高处，能自省返观、有始有终，方能圆满吉祥。' },
    ]
  },
  { no: 11, name: '泰',   full: '地天泰',   upper: '坤', lower: '乾', gong: '坤', shi: 3, tuan: '小往大来，吉亨。', xiang: '天地交，泰；后以财成天地之道，辅相天地之宜，以左右民。', read: '天地交泰，诸事通顺，宜把握良机。',
    meaning: '泰卦象征天地交泰、上下相通，坤在上乾在下，天气下降、地气上升，故万物通泰。泰之道在于上下交感、内外相通，君臣同心、上下和合，则万事亨通。然泰极必否，宜在盛时守持中道，居安思危方能长保太平。',
    gaoTuan: '泰者，通也，天地交而万物通也。乾下坤上，天气下降、地气上升，故小往大来而吉亨。此乃君臣相得、上下相通之象，盛世之泰也。然泰极则否，君子当持盈保泰，乃能久安。',
    yaos: [
      { text: '拔茅茹，以其汇，征吉。', xiang: '拔茅征吉，志在外也。', meaning: '初九阳刚居下，拔茅连根带类而起，征进则吉。这是说贤者出仕，能引类同行、连根拔起，志在向外进取，必有所成。正如团队同心协力、相互提携，共同前行方能吉祥。' },
      { text: '包荒，用冯河，不遐遗，朋亡，得尚于中行。', xiang: '包荒，得尚于中行，以光大也。', meaning: '九二刚中居下，有包容荒秽之量，敢徒步涉河，不遗遐远，不结朋党，合于中道而行。这是说治世之臣，要有包容万物之量、勇决果敢之胆，又不偏私、不阿党，方能光大道业。正如贤臣辅政，宜大公无私、广纳兼听。' },
      { text: '无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。', xiang: '无往不复，天地际也。', meaning: '九三处泰之极，将转为否，故平地终将变陂、往者必将复返，惟艰守正道方无咎。诚信相孚，则有福禄之享。这是说物极必反，泰极则否，安不可忘危，须时刻保持敬畏之心。正如盛时要居安思危，方能长保太平。' },
      { text: '翩翩不富，以其邻，不戒以孚。', xiang: '翩翩不富，皆失实也。不戒以孚，中心愿也。', meaning: '六四柔顺居上，翩然下从，不以富实自恃，与邻人同心相孚，不待戒告而诚信相待。这是说上下相交之时，居上位者能谦恭下士、以诚待人，则自然上下同心。正如领导者放下身段、以诚待下，团队自然和合。' },
      { text: '帝乙归妹，以祉元吉。', xiang: '以祉元吉，中以行愿也。', meaning: '六五柔中居尊，如帝乙嫁女，以礼下嫁贤者，得福而大吉。这是说居尊位者，能谦恭下交、礼贤下士，以美德行其所愿，得大吉祥。正如明君以谦德下士、择贤而任，方能成就治世。' },
      { text: '城复于隍，勿用师，自邑告命，贞吝。', xiang: '城复于隍，其命乱也。', meaning: '上六处泰之极，城池倾覆于隍中，泰极而否，勿用兵师，宜自邑告命、守正防吝。这是说盛世之末，秩序将乱，不可妄动兴师，宜自守正道以渡难关。正如太平之末必有乱，宜内修政事、不可外用兵戈。' },
    ]
  },
  { no: 12, name: '否',   full: '天地否',   upper: '乾', lower: '坤', gong: '金', shi: 3, tuan: '否之匪人，不利君子贞，大往小来。', xiang: '天地不交，否；君子以俭德辟难，不可荣以禄。', read: '闭塞不通，宜内敛守正，待时而变。',
    meaning: '否卦象征天地不交、闭塞不通，乾上坤下，天气上升不降、地气下沉不升，故万物不通。否之时，君子宜俭德避难、隐晦守正，不可贪图荣禄。然否极必泰，要在坚守正道、待时而变，方能否极泰来。',
    gaoTuan: '否者，闭也，天地不交而万物不通也。乾上坤下，天气不降、地气不升，故大往小来而否。君子当俭德辟难，不可荣以禄，盖否之时，宜晦而守正，以待泰来也。否终则倾，此天道之常也。',
    yaos: [
      { text: '拔茅茹，以其汇，贞吉，亨。', xiang: '拔茅贞吉，志在君也。', meaning: '初六柔居否之始，拔茅连根同类而起，守正则吉而亨通。这是说在否闭之时，贤者宜同心同德、坚守正道，志在匡君济世，方能得吉。正如乱世之中，志士仁人须同心守正，以待时变。' },
      { text: '包承，小人吉，大人否，亨。', xiang: '大人否亨，不乱群也。', meaning: '六二柔中居正，能包容承顺，小人得吉，大人则否而亨通。这是说在否之时，大人不与小人同流，虽处否而能亨。正如君子处乱世，不随波逐流、不同流合污，方能保身而亨。' },
      { text: '包羞。', xiang: '包羞，位不当也。', meaning: '六三阴柔失正，包藏羞辱。这是说小人在否之时得势，包藏祸心、不知羞耻，终必招辱。正如阿谀奉承之徒得志于乱世，看似风光，实已埋下祸根。' },
      { text: '有命无咎，畴离祉。', xiang: '有命无咎，志行也。', meaning: '九四阳刚近君，奉君命而行则无咎，同类皆得福祉。这是说在否将转泰之时，能奉天命、行正道，则志得行、众得福。正如贤臣奉命革除弊政，则同类皆受其福、否道将倾。' },
      { text: '休否，大人吉。其亡其亡，系于苞桑。', xiang: '大人之吉，位正当也。', meaning: '九五中正居尊，能休止否闭，大人得吉。常存「其亡其亡」之戒惧，则如系于苞桑之坚固而无忧。这是说身处高位，能休止乱局、常怀危惧，方能转否为泰。正如明君居安思危、常存亡国之惧，反能保国长存。' },
      { text: '倾否，先否后喜。', xiang: '否终则倾，何可长也。', meaning: '上九处否之极，否道倾覆，先有否而后有喜。这是说否极必反、物极必反，否道终将倾覆，喜乐随之而来。正如困境达到顶点，转机便在眼前，坚持守正、不放弃，终能迎来否极泰来的欢喜。' },
    ]
  },
  { no: 13, name: '同人', full: '天火同人', upper: '乾', lower: '离', gong: '离', shi: 3, tuan: '同人于野，亨。利涉大川，利君子贞。', xiang: '天与火，同人；君子以类族辨物。', read: '和同于人，宜广结同心，协力有成。',
    meaning: '同人卦象征与人和同、广结同心，天在上火在下，火性炎上与天同向，故为同人之象。同人之道在于大公无私、于旷野之中与人和同，方能协力涉险、共成大业。然同人有道，须同心于正、不可结党营私，利君子之贞方能得众。',
    gaoTuan: '同人者，与人和同也，天与火，火炎上而从天，故为同人之象。柔得位得中而应乎乾，故能通天下之志。同人于野而后亨，盖无私乃能得众，君子以类族辨物，正所以辨同异、合天下之公也。',
    yaos: [
      { text: '同人于门，无咎。', xiang: '出门同人，又谁咎也。', meaning: '初九刚正居下，刚出门即与人和同，无咎。这是说与人交往要敞开心扉、主动亲和，走出自己的小圈子去结交同道，自然无咎。正如「远亲不如近邻」，与邻为善、与人为善，乃处世之始。' },
      { text: '同人于宗，吝。', xiang: '同人于宗，吝道也。', meaning: '六二柔中得正，与九五相应，却只与同宗之人亲和，则有吝惜。这是说若只亲近自己宗族小圈子、不能广结天下，是有所偏狭的。正如做人若只顾自家、结党营私，必失人心。' },
      { text: '伏戎于莽，升其高陵，三岁不兴。', xiang: '伏戎于莽，敌刚也。三岁不兴，安行也。', meaning: '九三刚而不中，欲与六二同人却被九四所阻，故埋伏兵于草莽、登高窥伺，三年不能兴起。这是说争同不得，强争必败，宜知难而退。正如争夺志同道合之人不可强求，强取反生祸患。' },
      { text: '乘其墉，弗克攻，吉。', xiang: '乘其墉，义弗克也。其吉，则困而反则也。', meaning: '九四刚而不中，欲攻六二而乘其城墉，知义不可攻而止，则吉。这是说争同之时能知止知退，守义不攻，反得吉祥。正如为人能克制贪争之心、知错能改，方化险为吉。' },
      { text: '同人，先号啕而后笑。大师克相遇。', xiang: '同人之先，以中直也。大师相遇，言相克也。', meaning: '九五中正居尊，与六二本应却被三四相阻，先哭后笑，兴师克敌方能相遇。这是说同心之路多有曲折阻隔，须历经艰难方能得偿所愿。正如真知己难得，须冲破重重障碍方能同心相得。' },
      { text: '同人于郊，无悔。', xiang: '同人于郊，志未得也。', meaning: '上九处同人之极，居郊外无人之处与人同，未得志而无悔。这是说身处偏远冷落之地，虽未得天下之同，亦能洁身自好而无悔。正如隐者身处江湖之远，未遇知己亦不勉强，安然自处。' },
    ]
  },
  { no: 14, name: '大有', full: '火天大有', upper: '离', lower: '乾', gong: '乾', shi: 3, tuan: '元亨。', xiang: '火在天上，大有；君子以遏恶扬善，顺天休命。', read: '大有所获，宜谦守富贵，惠及于人。',
    meaning: '大有卦象征大有所获、富庶丰盛，火在天上，光明普照天下，万物丰盛皆可见。大有之道在于以德守富、遏恶扬善，富而不骄、贵而不傲，顺天命而行方能长保。盛时要谦守富贵、惠及于人，乃保泰之道。',
    gaoTuan: '大有者，所有大也，火在天上，无所不照，万物丰盛之象。柔得尊位大中而上下应之，故能大有。然大有必以德守之，遏恶扬善、顺天休命，乃能保其大有而不失也。',
    yaos: [
      { text: '无交害，匪咎，艰则无咎。', xiang: '大有初九，无交害也。', meaning: '初九阳刚居下，无交涉则无害，纵有咎亦非其咎，惟艰守则无咎。这是说富庶之初，宜谨慎自处、不与人争利交涉，居安思艰方无咎。正如创业之初，宜勤勉节制、不炫富招祸。' },
      { text: '大车以载，有攸往，无咎。', xiang: '大车以载，积中不败也。', meaning: '九二刚中得正，有才能可担重任，如大车载重前行而无咎。这是说身有才能德行，能堪大任、任重道远，前往必无咎。正如贤才堪当大用，厚德方能载物，担当大事而无咎。' },
      { text: '公用亨于天子，小人弗克。', xiang: '公用亨于天子，小人害也。', meaning: '九三刚正居下卦之极，如公侯朝亨于天子，小人不能胜任。这是说富有之时，惟有德君子方能将财富奉献天子、合于正道，小人则贪吝为害。正如富而能仁、达而能济，方为君子；若贪得无厌则招祸。' },
      { text: '匪其彭，无咎。', xiang: '匪其彭，无咎，明辨晳也。', meaning: '九四近君居盛，能不自恃其盛、明辨进退，则无咎。这是说身居近君之位、富有权势，能不自满张扬、明智谦退，方无咎害。正如功高不震主、富而不骄，方能保全自身。' },
      { text: '厥孚交如，威如，吉。', xiang: '厥孚交如，信以发志也。威如之吉，易而无备也。', meaning: '六五柔中居尊，以诚信交结天下，威而不猛，吉。这是说居尊位者，以诚信待人、上下交孚，自然威信自生而吉。正如明君以诚服人，不威而自威，天下归心。' },
      { text: '自天佑之，吉无不利。', xiang: '大有上吉，自天佑也。', meaning: '上九处大有之极，居高思谦，得天之佑，吉无不利。这是说富极而不忘谦德，顺天合道，则天佑之、吉无不利。正如盛极能谦、富而好德，乃得天保佑之至道。' },
    ]
  },
  { no: 15, name: '谦',   full: '地山谦',   upper: '坤', lower: '艮', gong: '坤', shi: 5, tuan: '亨，君子有终。', xiang: '地中有山，谦；君子以裒多益寡，称物平施。', read: '谦尊而光，满招损谦受益，守谦则吉。',
    meaning: '谦卦象征谦虚自处，山本高峻却隐于地中，是内高而外卑之象。谦之道在于裒多益寡、称物平施，谦尊而光、卑而不可逾，满招损而谦受益，守谦者必有终。谦乃君子之至德，持之则亨。',
    gaoTuan: '谦者，卑退也，地中有山，内高而外卑之象。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。',
    yaos: [
      { text: '谦谦君子，用涉大川，吉。', xiang: '谦谦君子，卑以自牧也。', meaning: '初六柔弱居下，谦而又谦，如君子以谦卑自养，涉大川亦吉。这是说身处卑位之初，宜以谦卑自修其德，谦而又谦，则无险不济、无往不利。正如做人初学，宜放低姿态、虚心自牧，方能涉险渡难。' },
      { text: '鸣谦，贞吉。', xiang: '鸣谦贞吉，中心得也。', meaning: '六二柔中得正，谦德积于中而形于外，守正而吉。这是说谦德发自内心，自然流露于言行，得人响应，守正则吉。正如真诚谦逊之人，言谈间自然流露谦德，得人敬重。' },
      { text: '劳谦君子，有终，吉。', xiang: '劳谦君子，万民服也。', meaning: '九三刚正居下卦之上，劳而能谦，君子有终而吉。这是说有功劳却不自伐，反能谦让，必得万民敬服、善终有吉。正如功成不居、劳而能谦，乃真君子之风，能服众人之心。' },
      { text: '无不利，撝谦。', xiang: '无不利，撝谦，不违则也。', meaning: '六四柔顺得正，无所不利，发挥谦德而不违法则。这是说谦之道贵在得其宜，于近君之位仍能谦退自处，不违常道。正如身处高位仍谦恭有礼、发挥谦德，则无往不利。' },
      { text: '不富以其邻，利用侵伐，无不利。', xiang: '利用侵伐，征不服也。', meaning: '六五柔中居尊，不恃富而能使其邻，宜用兵征伐不服，无不利。这是说居尊者以谦德服人，不恃富而能率众，对于不服者可征伐之，无不顺利。正如谦德虽柔，必要时亦有威严，可征伐不义。' },
      { text: '鸣谦，利用行师，征邑国。', xiang: '鸣谦，志未得也。可用行师，征邑国也。', meaning: '上六处谦之极，谦名远扬却志未得伸，可用兵征讨邑国之不服。这是说谦极而德未行，宜以谦德之师征讨不服、伸张正义。正如德高望重者，必要时可以正义之师平定叛乱、伸张公道。' },
    ]
  },
  { no: 16, name: '豫',   full: '雷地豫',   upper: '震', lower: '坤', gong: '震', shi: 1, tuan: '利建侯行师。', xiang: '雷出地奋，豫；先王以作乐崇德，殷荐之上帝，以配祖考。', read: '安逸和乐，宜未雨绸缪，戒骄戒怠。',
    meaning: '豫卦象征和乐安逸，雷出地奋，万物振奋欢跃。豫之道在于顺时而动、作乐崇德，安居乐业之时不忘敬畏上帝、配享祖考。然豫不可纵，宜未雨绸缪、戒骄戒怠，方能建侯行师、有所作为。',
    gaoTuan: '豫者，和乐也，雷出地奋，万物振奋之象。刚应而志行，顺以动，故天地如之。先王作乐崇德，殷荐之上帝以配祖考，盖豫必以德为本，不可溺于逸乐也。',
    yaos: [
      { text: '鸣豫，凶。', xiang: '初六鸣豫，志穷凶也。', meaning: '初六柔居初位，与九四正应而纵乐，自鸣得意，凶。这是说居于和乐之初，若贪图逸乐、自鸣得意，则志气消磨、必招凶祸。正如人初有所成就贪乐自满，必致败亡。' },
      { text: '介于石，不终日，贞吉。', xiang: '不终日贞吉，以中正也。', meaning: '六二柔中得正，坚介如石，知几察微，不待终日而断然去恶从善，贞吉。这是说身处安逸却能坚守节操、不为外物所动，洞察几微而果决，则吉。正如君子处安而不忘危，坚介其操、明察事机，方能保全。' },
      { text: '盱豫悔。迟有悔。', xiang: '盱豫有悔，位不当也。', meaning: '六三阴居阳位失正，媚上求乐，迟疑则有悔。这是说以谄媚奉迎求取安逸，必招悔恨，迟疑不觉则悔更深。正如阿谀奉承、攀附权贵以求乐者，终必自悔。' },
      { text: '由豫，大有得。勿疑。朋盍簪。', xiang: '由豫，大有得，志大行也。', meaning: '九四刚健不中，为众阴所归，由之而得豫，大有收获，勿疑，朋友如簪之聚。这是说为人信赖、为众望所归，能使人皆得安逸，则志大行，宜自信不疑。正如贤者得众人之心，能造福众人，故不必疑虑。' },
      { text: '贞疾，恒不死。', xiang: '六五贞疾，乘刚也。恒不死，中未亡也。', meaning: '六五柔居尊位，乘九四之刚，居安而疾，恒久而不死。这是说居安逸之尊位却染疾患，因守中道故未亡。正如安逸之中暗藏危机，若能守正不失根本，纵有困厄亦能保全。' },
      { text: '冥豫，成有渝，无咎。', xiang: '冥豫在上，何可长也。', meaning: '上六处豫之极，昏冥于乐，若能变改则无咎。这是说纵乐至极、昏冥无知，若能及时醒悟改过，则无咎。正如人沉溺享乐至极，能幡然悔悟、改弦更张，方能免祸。' },
    ]
  },
  { no: 17, name: '随',   full: '泽雷随',   upper: '兑', lower: '震', gong: '震', shi: 3, tuan: '元亨利贞，无咎。', xiang: '泽中有雷，随；君子以向晦入宴息。', read: '随顺时机，宜从善而动，不可逆势。',
    meaning: '随卦象征随顺、相随，泽中有雷，雷藏泽中，动而能悦、悦而能从。随之道在于择善而从、随时而动，不违天时、不逆人情。君子观此象，向晦入宴息，作息有时，乃随顺之正。',
    gaoTuan: '随者，从也，泽中有雷，动而悦之象。刚来而下柔，动而悦，故天下随时。随时之义大矣哉，君子向晦入宴息，作息有时，此随之道也。',
    yaos: [
      { text: '官有渝，贞吉。出门交有功。', xiang: '官有渝，从正吉也。出门交有功，不失也。', meaning: '初九刚正居下，官职有所变易，守正则吉，出门交结有功。这是说职位变动之时，宜守正不阿、广交贤友，则不失其道而有功。正如事业变动，宜正心诚意、广结善缘，方能有所成就。' },
      { text: '系小子，失丈夫。', xiang: '系小子，弗兼与也。', meaning: '六二柔中得正，却贪近失远，系于小子则失丈夫。这是说取舍之时，若贪图近利小利，必失远大之利。正如做人做事不可因小失大，目光短浅者必失大好前程。' },
      { text: '系丈夫，失小子。随有求得，利居贞。', xiang: '系丈夫，志舍下也。', meaning: '六三柔居阳位，舍小子而从丈夫，随而有所求必得，宜居守正道。这是说择善而从、舍小取大，所求必得，宜守正不阿。正如择贤而从、跟对明主，必有所成，但仍须守正方吉。' },
      { text: '随有获，贞凶。有孚在道，以明，何咎。', xiang: '随有获，其义凶也。有孚在道，明功也。', meaning: '九四近君，随而有获，纵正亦凶，惟诚信守道、明其功业，方无咎。这是说臣下随君而多有收获，纵使正当亦招猜疑，惟诚信守道、明哲保身，方能无咎。正如功臣伴君，宜谦退诚信、明哲自持，方免祸殃。' },
      { text: '孚于嘉，吉。', xiang: '孚于嘉吉，位正中也。', meaning: '九五刚中居尊，诚信于善人，吉。这是说居尊者以诚信待贤善之人，得正中之道，则吉。正如明君以诚待贤臣，君臣相孚、上下同心，国家自然大治。' },
      { text: '拘系之，乃从维之。王用亨于西山。', xiang: '拘系之，上穷也。', meaning: '上六处随之极，被人拘系维缚，王者用以亨祭西山。这是说随顺至极反被约束，惟以诚敬祭祀则可化险为吉。正如人极尽随顺反失自主，宜以诚敬自守、合于正道，方能脱困。' },
    ]
  },
  { no: 18, name: '蛊',   full: '山风蛊',   upper: '艮', lower: '巽', gong: '巽', shi: 3, tuan: '元亨，利涉大川。先甲三日，后甲三日。', xiang: '山下有风，蛊；君子以振民育德。', read: '积弊待治，宜整饬革新，拨乱反正。',
    meaning: '蛊卦象征积弊待治，山下有风，风遇山而回，万物败坏成蛊。蛊之道在于振民育德、整饬革新，前事之弊当以善后救之，故利涉大川、先甲后甲。治蛊须慎始慎终，拨乱反正方能元亨。',
    gaoTuan: '蛊者，坏也，山下有风，风遇山而回，败坏之象。蛊非一日之积，乃前人之弊也。治之之道，利涉大川，先甲三日、后甲三日，慎始慎终，乃能元亨而拨乱反正也。',
    yaos: [
      { text: '干父之蛊，有子，考无咎，厉终吉。', xiang: '干父之蛊，意承考也。', meaning: '初六柔居初位，承父之业而治其弊，有子如此，父考无咎，虽危终吉。这是说继承前人事业而能整饬其弊，方为孝子，纵有艰难终得吉利。正如后辈承继家业，能革故鼎新、补偏救弊，方为真孝。' },
      { text: '干母之蛊，不可贞。', xiang: '干母之蛊，得中道也。', meaning: '九二刚中得正，匡正母之弊，宜委婉不可过正。这是说纠正尊长过失，宜温和中道，不可过于刚直。正如规劝长辈，须委婉得宜，过刚则伤感情。' },
      { text: '干父之蛊，小有悔，无大咎。', xiang: '干父之蛊，终无咎也。', meaning: '九三刚正不中，匡正父弊稍过，小有悔而无大咎。这是说整饬前弊虽稍显过激、招小悔，但终无大咎。正如改革弊政，虽一时招怨，但出于正道，终无大患。' },
      { text: '裕父之蛊，往见吝。', xiang: '裕父之蛊，往未得也。', meaning: '六四柔弱失正，宽容前人之弊而不治，前往必见吝惜。这是说面对积弊若优柔不治、姑息养奸，必致后悔。正如管理者对弊端视而不见、宽容放任，终必酿成大患。' },
      { text: '干父之蛊，用誉。', xiang: '干父用誉，承以德也。', meaning: '六五柔中居尊，承父业而治其弊，以德承之，得美誉。这是说居尊位者能革故鼎新、以德服人，必得天下赞誉。正如贤君改革弊政，以德为本、顺乎民心，必留美名。' },
      { text: '不事王侯，高尚其事。', xiang: '不事王侯，志可则也。', meaning: '上九处蛊之极，不事王侯，高尚其志。这是说治蛊功成，能洁身自好、不慕名利，高尚其志。正如功成身退、不图爵禄，乃君子高风亮节，可为世法。' },
    ]
  },
  { no: 19, name: '临',   full: '地泽临',   upper: '坤', lower: '兑', gong: '坤', shi: 2, tuan: '元，亨，利，贞。至于八月有凶。', xiang: '泽上有地，临；君子以教思无穷，容保民无疆。', read: '临下亲民，阳气渐长，宜施恩布德。',
    meaning: '临卦象征以大临小、居高临下，泽上有地，地高泽低，相临相亲。临之道在于教思无穷、容保民无疆，阳气渐长、生机日盛，宜施恩布德。然临极必消，八月有凶，宜居盛思衰。',
    gaoTuan: '临者，大也，泽上有地，地临泽之象。阳刚浸长，故元亨利贞。然至于八月有凶，盖临极则消，物盛必衰，君子当持盈保泰，乃能久临。',
    yaos: [
      { text: '咸临，贞吉。', xiang: '咸临贞吉，志行正也。', meaning: '初九刚正居下，以咸感之道临人，守正而吉。这是说以真诚感应之临，居下位而能动上，守正则吉。正如以诚待人、以德服人，纵处卑位亦能感召他人。' },
      { text: '咸临，吉无不利。', xiang: '咸临，吉无不利，未顺命也。', meaning: '九二刚中得正，以咸感之道临人，吉无不利。这是说居下卦之中，以诚感临，无所不利。正如贤臣以诚辅君，君臣相得，则凡事顺利。' },
      { text: '甘临，无攸利。既忧之，无咎。', xiang: '甘临，位不当也。既忧之，咎不长也。', meaning: '六三柔居阳位失正，以巧言甘语临人，无所利，若能忧惧改过则无咎。这是说以花言巧语谄媚临下，必无所得，若能悔惧改过则免祸。正如巧言令色者终难得人心，知过能改方免咎殃。' },
      { text: '至临，无咎。', xiang: '至临无咎，位当也。', meaning: '六四柔顺得正，以至诚亲近临下，无咎。这是说以诚挚之心亲自临下、亲贤下士，方无咎。正如居上位者亲贤下士、礼贤下士，自然无过。' },
      { text: '知临，大君之宜，吉。', xiang: '大君之宜，行中之谓也。', meaning: '六五柔中居尊，以智知人、知临天下，是大君之宜，吉。这是说居尊者能任人唯贤、知人善任，行中道而治，是大君之正道。正如明君知人善任、不亲自操劳，方为治世之至道。' },
      { text: '敦临，吉无咎。', xiang: '敦临之吉，志在内也。', meaning: '上六处临之极，以敦厚之道临人，吉无咎。这是说居高临下至极，能以敦厚存心、不忘根本，则吉无咎。正如身居高位者，不忘敦厚本心、念及苍生，方能长保吉祥。' },
    ]
  },
  { no: 20, name: '观',   full: '风地观',   upper: '巽', lower: '坤', gong: '乾', shi: 4, tuan: '盥而不荐，有孚颙若。', xiang: '风行地上，观；先王以省方观民设教。', read: '观察省视，宜静观其变，反身自省。',
    meaning: '观卦象征观察、省视，风行地上，无所不周，故为观之象。观之道在于省方观民设教，君主以中正示天下，使民观感而化。观有上下之分，下观上为仰观，上观下为省察，皆贵以诚敬为本。',
    gaoTuan: '观者，观望也，风行地上，无所不周之象。盥而不荐，有孚颙若，下观而化也。先王省方观民设教，以中正示天下，神道设教而天下服矣。',
    yaos: [
      { text: '童观，小人无咎，君子吝。', xiang: '初六童观，小人道也。', meaning: '初六柔弱居下，如童稚之观，浅陋无识，小人则无咎，君子则有吝。这是说观察事物若如孩童般浅陋，平民无妨，君子上流则可羞。正如做人见识浅陋、不明事理，对身居上位者是大忌。' },
      { text: '窥观，利女贞。', xiang: '窥观女贞，亦可丑也。', meaning: '六二柔中得正，如女子窥视，所见者狭，利于女子守贞。这是说观察片面狭隘，于女子则正，于男子则可羞。正如见识偏狭、一孔之见，纵合于妇道，于君子则不足取。' },
      { text: '观我生，进退。', xiang: '观我生进退，未失道也。', meaning: '六三柔居阳位，能自观己之生以定进退，未失其道。这是说处观之时，能反观自身、审视己德，以定行止进退。正如做人能自省其德、量力而行，进退不失其道。' },
      { text: '观国之光，利用宾于王。', xiang: '观国之光，尚宾也。', meaning: '六四柔顺得正，近君观国之光华，宜为王者之宾。这是说能观国家之盛德光辉，宜为君王宾客、辅佐朝政。正如贤才观明君之德，宜出仕辅政、为时所用。' },
      { text: '观我生，君子无咎。', xiang: '观我生，观民也。', meaning: '九五中正居尊，自观其德，君子则无咎。这是说居尊位者，能反观己德、审视民风，君子守正则无咎。正如明君以省察自身、观民风得失为务，方为有德之君。' },
      { text: '观其生，君子无咎。', xiang: '观其生，志未平也。', meaning: '上九处观之极，观天下之民风，君子则无咎。这是说身处高位而退，能观天下民生、心怀天下，君子则无咎。正如退位之君子，仍以天下为念、观民风得失，方无过咎。' },
    ]
  },
  { no: 21, name: '噬嗑', full: '火雷噬嗑', upper: '离', lower: '震', gong: '巽', shi: 5, tuan: '亨。利用狱。', xiang: '雷电，噬嗑；先王以明罚敕法。', read: '咬合去梗，宜明断是非，罚当其罪。',
    meaning: '噬嗑卦象征咬合去梗、明断是非，雷电合章，明罚敕法。噬嗑之道在于利用狱、明断刑狱，去其间梗、合而为一。治国之道贵在明断公正，罚当其罪，方能政通人和。',
    gaoTuan: '噬嗑者，啮也，颐中有物曰噬嗑，雷电合而章之象。噬而嗑之，则亨通矣。先王明罚敕法，去其间梗，乃能合天下之治也。',
    yaos: [
      { text: '屦校灭趾，无咎。', xiang: '屦校灭趾，不行也。', meaning: '初九刚正居下，罪小罚轻，如戴脚铐伤趾，禁止其行则无咎。这是说小罪宜轻罚，惩之于初、禁其再犯，则无大咎。正如教育惩戒宜及时适度，防微杜渐，方能使人改过。' },
      { text: '噬肤灭鼻，无咎。', xiang: '噬肤灭鼻，乘刚也。', meaning: '六二柔中得正，噬咬嫩肤至灭鼻，刑罚稍过，因乘刚故无咎。这是说刑罪犯人之嫩弱处，虽稍有过，但因乘刚不得不严，故无咎。正如治顽恶之徒，须严刑峻法，虽过无害。' },
      { text: '噬腊肉，遇毒。小吝，无咎。', xiang: '遇毒，位不当也。', meaning: '六三柔居阳位失正，噬咬腊肉遇毒，小有吝惜而无咎。这是说治事遇棘手难题、陈年积弊，虽有小难但终无大咎。正如处理复杂积弊，难免遇阻受困，但坚守终能渡过。' },
      { text: '噬干胏，得金矢。利艰贞，吉。', xiang: '利艰贞吉，未光也。', meaning: '九四刚健不中，噬咬带骨干肉得金矢，宜艰守正道则吉。这是说治大案、断难狱，虽有艰难阻险，但坚守正道必有所得。正如治大案要案，须刚直不阿、艰守正道，方能吉。' },
      { text: '噬干肉，得黄金。贞厉，无咎。', xiang: '贞厉无咎，得当也。', meaning: '六五柔中居尊，噬干肉得黄金，守正防厉则无咎。这是说居尊位断狱，以中道行之，虽处危厉而得正，故无咎。正如明君治狱，须刚柔相济、守正防危，方能得当无咎。' },
      { text: '何校灭耳，凶。', xiang: '何校灭耳，聪不明也。', meaning: '上九处噬嗑之极，罪大罚重，戴枷锁伤耳，凶。这是说积恶不改、罪大恶极，终受重刑，凶。正如作恶多端、不听规劝者，必受严惩，此乃罪大之凶。' },
    ]
  },
  { no: 22, name: '贲',   full: '山火贲',   upper: '艮', lower: '离', gong: '艮', shi: 1, tuan: '亨。小利有攸往。', xiang: '山下有火，贲；君子以明庶政，无敢折狱。', read: '文饰之美，宜重内涵轻浮华。',
    meaning: '贲卦象征文饰之美，山下有火，火光照山，文彩斑斓。贲之道在于明庶政、无敢折狱，重文饰而不废实务。贲贵得宜，文质相称，过饰则浮，故小利有攸往，宜重内涵而轻浮华。',
    gaoTuan: '贲者，饰也，山下有火，火照山而文彩之象。柔来而文刚，故亨。然贲贵文质相称，过饰则浮，故小利有攸往。君子明庶政，无敢折狱，重实务而不专尚文也。',
    yaos: [
      { text: '贲其趾，舍车而徒。', xiang: '贲其趾，义弗乘也。', meaning: '初九刚正居下，文饰其足，舍车徒步而行。这是说处贲之初，宜安于本分、舍华从实，宁徒步而舍车乘。正如做人宜守本分、不慕虚荣，宁可朴素徒步，不为外物所累。' },
      { text: '贲其须。', xiang: '贲其须，与上兴也。', meaning: '六二柔中得正，文饰其须，随上而动。这是说文饰须随所附之物，依附强者而兴起。正如辅佐他人，宜随其所辅、文饰其德，方能相得益彰。' },
      { text: '贲如濡如，永贞吉。', xiang: '永贞之吉，终莫之陵也。', meaning: '九三刚正居下卦之上，文饰润泽，永守正道则吉。这是说文饰至润泽华美，宜永守正道，方能无人能陵。正如文采风流，须以正道为本，方能长保吉祥。' },
      { text: '贲如皤如，白马翰如。匪寇，婚媾。', xiang: '六四，当位疑也。匪寇婚媾，终无尤也。', meaning: '六四柔顺得正，文饰素白如白马奔腾，疑为寇盗，实乃求婚。这是说文饰返于素朴，初疑为寇，终得正配。正如事物本质之美胜于浮华，初有疑虑，终得善果。' },
      { text: '贲于丘园，束帛戋戋。吝，终吉。', xiang: '六五之吉，有喜也。', meaning: '六五柔中居尊，文饰丘园，束帛微薄，似吝而终吉。这是说居尊者崇尚质朴、礼贤丘园，虽礼薄似吝，但终得吉庆。正如明君重实质、轻虚文，礼虽简而诚，终有喜庆。' },
      { text: '白贲，无咎。', xiang: '白贲无咎，上得志也。', meaning: '上九处贲之极，返于素白无饰，无咎。这是说文饰至极返于素朴，无华而真，方得无咎。正如人生修养至极，返璞归真、去华存实，乃最高境界。' },
    ]
  },
  { no: 23, name: '剥',   full: '山地剥',   upper: '艮', lower: '坤', gong: '乾', shi: 5, tuan: '不利有攸往。', xiang: '山附于地，剥；上以厚下安宅。', read: '阴盛剥阳，宜蛰伏自守，勿妄动。',
    meaning: '剥卦象征剥落，山附于地，高山侵蚀崩落之象。五阴剥一阳，小人势盛，君子道消，宜顺时止息、厚下安宅。剥之道不可轻动，宜静守待变，待阳复来。',
    gaoTuan: '剥者，落也。山附于地，高山颓落之象。五阴盛而剥一阳，小人众而君子孤，故不利有攸往。然剥极必复，天道循环，君子当厚下安宅，静守以待阳复。',
    yaos: [
      { text: '剥床以足，蔑贞凶。', xiang: '剥床以足，以灭下也。', meaning: '初六处剥之初，剥落自床足始，灭正则凶。这是说祸患从根基而起，宜早察觉、守正防凶。正如事业危机常从底层萌发，宜及时固本，勿使小患成大祸。' },
      { text: '剥床以辨，蔑贞凶。', xiang: '剥床以辨，未有与也。', meaning: '六二剥落渐及床干，愈进愈上，灭正则凶。这是说剥蚀之势渐深，孤立无援则危。正如危局加剧，宜守正待援，不可冒进。' },
      { text: '剥之，无咎。', xiang: '剥之无咎，失上下也。', meaning: '六三处众阴之中，独应上阳，虽在剥而能去党从正，故无咎。这是说身处浊流而能独善其身、弃暗投明，则可免祸。正如小人之中能守正不阿，终得善果。' },
      { text: '剥床以肤，凶。', xiang: '剥床以肤，切近灾也。', meaning: '六四剥蚀及于床面肌肤，灾祸切身，凶。这是说祸患已迫近自身，无可回避。正如危局已至核心，宜速谋退避，迟则受害。' },
      { text: '贯鱼，以宫人宠，无不利。', xiang: '以宫人宠，终无尤也。', meaning: '六五柔中居尊，率众阴如贯鱼顺承一阳，以宫人受宠之序，无不利。这是说居尊者善处剥极，率众归正、以柔畜刚，则转危为安。正如领导善于疏导、化阴为阳，终得吉祥。' },
      { text: '硕果不食，君子得舆，小人剥庐。', xiang: '君子得舆，民所载也。小人剥庐，终不可用也。', meaning: '上九处剥之极，独阳存而不食，君子得民所载则吉，小人剥庐则无所容。这是说剥极将复，君子守正得民则兴，小人贪剥终自毁。正如乱世之末，守道者得众、妄作者自败。' },
    ]
  },
  { no: 24, name: '复',   full: '地雷复',   upper: '坤', lower: '震', gong: '坤', shi: 1, tuan: '亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。', xiang: '雷在地中，复；先王以至日闭关，商旅不行，后不省方。', read: '一阳来复，生机回归，宜修身待发。',
    meaning: '复卦象征回复、回归，雷在地中，一阳生于下，生机萌动之象。剥极而复，阴极阳生，是天道循环的转机。复之道在于顺其自然、修身待发，宜静养勿躁，待时而动。',
    gaoTuan: '复者，返也，归也。雷在地中，阳气复生于下，剥极而复之象也。七日来复，天道之常；先王以至日闭关，安静养阳，不欲妄动。反复其道，乃天行之自然也。',
    yaos: [
      { text: '不远复，无祗悔，元吉。', xiang: '不远之复，以修身也。', meaning: '初九处复之初，去而未远即能复归，无大悔而元吉。这是说人有过失能及早察觉、速归正道，乃修身之要。正如行事稍有偏差即能回头，方为君子之道。' },
      { text: '休复，吉。', xiang: '休复之吉，以下仁也。', meaning: '六二柔中得正，休然而复，下亲于仁，吉。这是说能安然而归于善、亲近仁德之人，自然吉祥。正如近朱者赤，亲贤修德则吉。' },
      { text: '频复，厉无咎。', xiang: '频复之厉，义无咎也。', meaning: '六三处下卦之上，频复频失，屡蹙屡归，虽厉而无咎。这是说过而能改、屡蹶屡起，虽险终免于祸。正如人生屡败屡试，只要能复归正道，终无大咎。' },
      { text: '中行独复。', xiang: '中行独复，以从道也。', meaning: '六四处群阴之中，独能应初阳而复，行于中道而从正。这是说身处众流之中能独守正道、不随波逐流。正如浊世之中独善其身，择善而从，方显君子之节。' },
      { text: '敦复，无悔。', xiang: '敦复无悔，中以自考也。', meaning: '六五柔中居尊，敦厚而复，从容自考，无悔。这是说以敦厚之心归于正道、内省自察，则无悔。正如修身以厚德为本，常自反省，方能无悔。' },
      { text: '迷复，凶，有灾眚。用行师，终有大败，以其国君，凶；至于十年，不克征。', xiang: '迷复之凶，反君道也。', meaning: '上六处复之极，迷而不复，凶有灾眚，行师大败，国君凶，十年不克征。这是说执迷不悟、不知返正，则大凶。正如人行邪道、迷途不知返，终致倾败。' },
    ]
  },
  { no: 25, name: '无妄', full: '天雷无妄', upper: '乾', lower: '震', gong: '巽', shi: 4, tuan: '元，亨，利，贞。其匪正有眚，不利有攸往。', xiang: '天下雷行，物与无妄；先王以茂对时育万物。', read: '不妄为，守正自然，妄动则灾。',
    meaning: '无妄卦象征不妄为，天下雷行，万物顺应自然之象。无妄即不妄动、守正道，元亨利贞四德俱全。然守正则吉，妄动则灾，宜顺其自然、不造作。',
    gaoTuan: '无妄者，不妄也。天下雷行，万物各正其命，无妄之象也。元亨利贞，天之正道，守之则吉；其匪正有眚，妄动则灾。君子茂对时育万物，顺天而不妄为。',
    yaos: [
      { text: '无妄，往吉。', xiang: '无妄之往，得志也。', meaning: '初九刚正居下，无妄而往，得遂其志则吉。这是说守正不妄、顺势而往，自然吉祥。正如行事合道而进，必得遂志。' },
      { text: '不耕获，不菑畲，则利有攸往。', xiang: '不耕获，未富也。', meaning: '六二柔中得正，不耕而获、不菑而畲，顺应自然、不谋功利，则利有攸往。这是说行事不求速成、不妄图功，顺其自然则吉。正如做人不存功利之念，反得善果。' },
      { text: '无妄之灾，或系之牛，行人之得，邑人之灾。', xiang: '行人得牛，邑人灾也。', meaning: '六三处无妄之时，遭无妄之灾，如系牛被行人得而邑人受殃。这是说无意之中横遭灾祸，非己之过。正如世事无常，有时无辜受累，宜安之若命。' },
      { text: '可贞，无咎。', xiang: '可贞无咎，固有之也。', meaning: '九四刚而不中，能守正固守，则无咎。这是说守正不移、固有其德，则免于祸。正如持身以正、不随物迁，终无咎患。' },
      { text: '无妄之疾，勿药有喜。', xiang: '无妄之药，不可试也。', meaning: '九五刚中居尊，无妄而遭疾，勿药自愈有喜。这是说守正之人偶有微恙，不妄服药、顺其自然则愈。正如处变不惊、不轻举妄动，则祸患自消。' },
      { text: '无妄，行有眚，无攸利。', xiang: '无妄之行，穷之灾也。', meaning: '上九处无妄之极，时穷而动，则有眚无攸利。这是说时已至极，虽无妄而行亦招灾。正如时运已尽，强动必祸，宜止乃吉。' },
    ]
  },
  { no: 26, name: '大畜', full: '山天大畜', upper: '艮', lower: '乾', gong: '艮', shi: 2, tuan: '利贞，不家食吉，利涉大川。', xiang: '天在山中，大畜；君子以多识前言往行，以畜其德。', read: '厚积成德，宜蓄才养志，待用而行。',
    meaning: '大畜卦象征大有积蓄，天在山中，蓄聚至大之象。大畜之道在于多识前言往行，以畜其德，宜厚积养志、待时而动。畜极必发，宜涉大川、行大事。',
    gaoTuan: '大畜者，所畜至大也。天在山中，畜之大者也。君子多识前言往行，以畜其德，畜而后能用，故利涉大川。不家食吉，养贤而大用也。',
    yaos: [
      { text: '有厉利已。', xiang: '有厉利已，不犯灾也。', meaning: '初九刚正居下，有危厉则利于止，不犯灾祸。这是说畜养之初宜知止慎行，勿轻进犯险。正如才德未充，宜止而自畜，待时而动。' },
      { text: '舆说輹。', xiang: '舆说輹，中无尤也。', meaning: '九二刚中得正，如车脱輹而止，居中无尤。这是说畜养之时宜自止不行，量力而进。正如时机未到，宜止而畜德，不躁进则无悔。' },
      { text: '良马逐，利艰贞。曰闲舆卫，利有攸往。', xiang: '利有攸往，上合志也。', meaning: '九三刚正不中，良马驰逐，利于艰贞，习车舆防卫，利有攸往。这是说畜养既久可以进取，然须备艰险、习防卫。正如才德既充，可济大川，宜慎备而行。' },
      { text: '童牛之牿，元吉。', xiang: '六四元吉，有喜也。', meaning: '六四柔正得位，如童牛加牿，止恶于未萌，元吉。这是说防患于未然、止邪于初动，最为吉祥。正如教育宜早、防微杜渐，乃大善之道。' },
      { text: '豮豕之牙，吉。', xiang: '六五之吉，有庆也。', meaning: '六五柔中居尊，如豮豕去其牙，化暴为顺，吉而有庆。这是说以柔化刚、去其锐气，则得吉庆。正如治人宜攻心化暴，不以力胜，方为上策。' },
      { text: '何天之衢，亨。', xiang: '何天之衢，道大行也。', meaning: '上九处大畜之极，畜极而通，如肩负天之大道，亨通无阻。这是说畜德既成、大道盛行，则亨通无碍。正如才德充备、时机已至，则无所不通。' },
    ]
  },
  { no: 27, name: '颐',   full: '山雷颐',   upper: '艮', lower: '震', gong: '巽', shi: 4, tuan: '贞吉。观颐，自求口实。', xiang: '山下有雷，颐；君子以慎言语，节饮食。', read: '颐养之道，慎言语节饮食，养正为吉。',
    meaning: '颐卦象征颐养，山下有雷，养人之象。颐之道在于慎言语、节饮食，养正则吉。养人养己，养德养身，皆以正为本。',
    gaoTuan: '颐者，养也。山下有雷，养之象也。观颐，观其所养；自求口实，观其自养。养正则吉，慎言语、节饮食，君子养德之道也。',
    yaos: [
      { text: '舍尔灵龟，观我朵颐，凶。', xiang: '观我朵颐，亦不足贵也。', meaning: '初九处颐之初，舍自养之灵龟，而观人嚼食，凶。这是说舍己之长而慕人外物，自失其养。正如人有宝而不知自守，徒羡人欲，终招凶患。' },
      { text: '颠颐，拂经于丘颐，征凶。', xiang: '六二征凶，行失类也。', meaning: '六二柔中失正，颠倒求养于下，违经而求于上丘，征则凶。这是说求养失其正道、颠倒本末，则行凶。正如求养宜以正，妄求于外则失其类。' },
      { text: '拂颐，贞凶，十年勿用，无攸利。', xiang: '十年勿用，道大悖也。', meaning: '六三不中不正，拂逆颐道，虽贞亦凶，十年不能用，无攸利。这是说违逆养道、行邪求养，终无所成。正如养身养德失正，则久困无功。' },
      { text: '颠颐，吉。虎视眈眈，其欲逐逐，无咎。', xiang: '颠颐之吉，上施光也。', meaning: '六四柔正得位，颠倒求养于下则吉，如虎视眈眈、欲望逐逐，无咎。这是说居上位而下求贤以养民，虽欲切而能正，则吉。正如求贤若渴、养民以正，方为上德。' },
      { text: '拂经，居贞吉，不可涉大川。', xiang: '居贞之吉，顺以从上也。', meaning: '六五柔中失正，拂逆常经，居守正道则吉，不可涉大川。这是说居位失正，宜守顺从上、安居正道，不可冒险。正如才弱宜守、顺从有道，方得吉安。' },
      { text: '由颐，厉吉，利涉大川。', xiang: '由颐厉吉，大有庆也。', meaning: '上九处颐之极，天下赖之以养，虽厉而吉，利涉大川。这是说养道大成、天下赖养，虽任重有厉，终得吉庆。正如担养民重任，虽危而吉，可济大难。' },
    ]
  },
  { no: 28, name: '大过', full: '泽风大过', upper: '兑', lower: '巽', gong: '巽', shi: 4, tuan: '栋桡，利有攸往，亨。', xiang: '泽灭木，大过；君子以独立不惧，遁世无闷。', read: '非常之时，宜独立不惧，担非常之任。',
    meaning: '大过卦象征过分、非常之象，泽灭木，水没过木，非常之象。大过之时，宜独立不惧、遁世无闷，担非常之任。然过极则败，宜慎重自处。',
    gaoTuan: '大过者，大者过也。泽灭木，大过之象也。栋桡者，本末弱也。非常之时，必有非常之才，君子独立不惧，遁世无闷，乃能济大过之难。',
    yaos: [
      { text: '借用白茅，无咎。', xiang: '借用白茅，柔在下也。', meaning: '初六柔居下，借物以白茅垫之，谨慎至极，无咎。这是说过人之初，宜以恭敬谨慎自处，慎之又慎。正如处事非常，宜格外谨慎，方可免咎。' },
      { text: '枯杨生稊，老夫得其女妻，无不利。', xiang: '老夫女妻，过以相与也。', meaning: '九二刚中失正，如枯杨生新芽、老夫得少妻，过而相济，无不利。这是说处大过之时，以刚济柔、非常相配，反得其宜。正如非常之时，非常之合，反成其功。' },
      { text: '栋桡，凶。', xiang: '栋桡之凶，不可以有辅也。', meaning: '九三刚过不中，如栋梁弯曲，本末弱而凶。这是说过刚则折、不能辅成，反招凶祸。正如才过于刚而失中，孤立无辅，终致败坏。' },
      { text: '栋隆，吉，有它吝。', xiang: '栋隆之吉，不桡乎下也。', meaning: '九四刚而不中，如栋梁隆起承重，吉，然有他吝。这是说能担大过之任则吉，然过于自高则生吝。正如担非常之任宜适度，过则有悔。' },
      { text: '枯杨生华，老妇得其士夫，无咎无誉。', xiang: '枯杨生华，何可久也。无咎无誉，位不当也。', meaning: '九五刚中居尊，如枯杨开花、老妇得少夫，无咎亦无誉。这是说过分之合，虽可苟合，终难长久。正如非常之配，华而不实，不足称誉。' },
      { text: '过涉灭顶，凶，无咎。', xiang: '过涉之凶，不可咎也。', meaning: '上六处大过之极，如涉水灭顶，凶，然不可咎。这是说过极而凶，乃时势使然，非己之过。正如非常之难，虽奋身以赴，终不可咎。' },
    ]
  },
  { no: 29, name: '坎',   full: '坎为水',   upper: '坎', lower: '坎', gong: '水', shi: 6, tuan: '习坎，有孚，维心亨，行有尚。', xiang: '水洊至，习坎；君子以常德行，习教事。', read: '重重险陷，宜守心诚信，稳步脱困。',
    meaning: '坎卦象征重重险陷，水洊至，险中有险之象。习坎之道在于以诚心通险、以常德行脱困。处险不惊，守心诚信，稳步前行则可脱险。',
    gaoTuan: '坎者，险也，陷也。水洊至，习坎之象，险之又险也。维心亨，乃以刚中也；行有尚，往有功也。君子以常德行，习教事，处险而不失其常也。',
    yaos: [
      { text: '习坎，入于坎窞，凶。', xiang: '习坎入坎，失道凶也。', meaning: '初六柔居重险之下，入于坎中之坎，失道则凶。这是说初陷险中又入深陷，愈陷愈深。正如人入困境又行失道，则愈陷愈凶。' },
      { text: '坎有险，求小得。', xiang: '求小得，未出中也。', meaning: '九二刚中处险，险中求小得，虽未出险。这是说处险之中，宜求小成、稳步脱困，不求大功。正如困中宜务实，渐求小善，方有出险之机。' },
      { text: '来之坎坎，险且枕，入于坎窞，勿用。', xiang: '来之坎坎，终无功也。', meaning: '六三不中不正，前后皆险，入于坎窞，无所用。这是说进退皆险、动则益凶，宜静守勿用。正如身陷绝境，宜止不宜行，方免愈陷。' },
      { text: '樽酒簋贰，用缶，纳约自牖，终无咎。', xiang: '樽酒簋贰，刚柔际也。', meaning: '六四柔正得位，以薄礼真诚自献，自牖通诚，终无咎。这是说处险之时，宜以诚朴通之于上，不以文胜。正如患难之中，贵在真诚，质朴自通则免咎。' },
      { text: '坎不盈，祗既平，无咎。', xiang: '坎不盈，中未大也。', meaning: '九五刚中居尊，险未盈而将平，守中则无咎。这是说处险既久将平，宜守中不自满，方得无咎。正如脱险将成，宜持重守中，未可大意。' },
      { text: '系用徽纆，置于丛棘，三岁不得，凶。', xiang: '上六失道，凶三岁也。', meaning: '上六处险之极，如以绳系囚、置于丛棘，三年不得出，凶。这是说陷险至极、积恶失道，久困不能脱。正如罪重积深，久困莫救，终致大凶。' },
    ]
  },
  { no: 30, name: '离',   full: '离为火',   upper: '离', lower: '离', gong: '火', shi: 6, tuan: '利贞，亨。畜牝牛，吉。', xiang: '明两作，离；大人以继明照于四方。', read: '附丽光明，宜守正得所附，明照四方。',
    meaning: '离卦象征附丽、光明，明两作，光明相继之象。离之道在于附丽正道、继明照于四方。宜畜牝牛之柔，守正得所附，则光明亨通。',
    gaoTuan: '离者，丽也，明也。明两作，离之象也。日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。畜牝牛吉，柔畜于刚，乃得其正也。',
    yaos: [
      { text: '履错然，敬之，无咎。', xiang: '履错之敬，以辟咎也。', meaning: '初九刚正居下，履错然纷杂，以敬慎处之，则无咎。这是说处离之初，事虽纷杂，宜敬慎自处。正如行事之初，宜敬畏谨慎，方可辟咎。' },
      { text: '黄离，元吉。', xiang: '黄离元吉，得中道也。', meaning: '六二柔中得正，黄中文明，得中道而元吉。这是说以中正之德附丽于明，最为吉祥。正如守中正之道、文明以养，乃大吉之至。' },
      { text: '日昃之离，不鼓缶而歌，则大耋之嗟，凶。', xiang: '日昃之离，何可久也。', meaning: '九三刚而不中，如日昃之暮光，不鼓缶高歌，则老大悲嗟，凶。这是说明将暮、盛将衰，宜达观乐天。正如人到暮年，宜旷达自适，否则徒悲无益。' },
      { text: '突如其来如，焚如，死如，弃如。', xiang: '突如其来如，无所容也。', meaning: '九四刚而不中，突如其来如火焚，终至死弃，无所容。这是说躁进妄动、强求附丽，必致焚身灭弃。正如人贪进失道、强求不得，反招祸患。' },
      { text: '出涕沱若，戚嗟若，吉。', xiang: '六五之吉，离王公也。', meaning: '六五柔中居尊，忧危出涕悲嗟，以忧惧得吉，附丽王公。这是说居尊而能忧惧自省，反得吉祥。正如高位之人，常怀忧惧、敬畏自守，方保其吉。' },
      { text: '王用出征，有嘉折首，获匪其丑，无咎。', xiang: '王用出征，以正邦也。', meaning: '上九处离之极，王用以出征，斩敌首恶，不滥及胁从，无咎。这是说以明断用兵、诛恶止暴，正邦无咎。正如行事明断、罚当其罪，乃能正邦。' },
    ]
  },
  { no: 31, name: '咸',   full: '泽山咸',   upper: '兑', lower: '艮', gong: '兑', shi: 3, tuan: '亨，利贞，取女吉。', xiang: '山上有泽，咸；君子以虚受人。', read: '感应相交，宜以虚受人，情感相通。',
    meaning: '咸卦象征感应、相交，山上有泽，气感相通之象。咸之道在于以虚受人、情感相交。少男少女相感而正，则亨通利贞。',
    gaoTuan: '咸者，感也。山上有泽，咸之象也。柔上而刚下，二气感应以相与，故亨。取女吉，以正感也；君子以虚受人，虚中无我，乃能感物。',
    yaos: [
      { text: '咸其拇。', xiang: '咸其拇，志在外也。', meaning: '初六处咸之初，感于足拇，志欲外行而未动。这是说感应初起，微动于末，宜慎其始。正如情意初萌，宜审慎其所感，勿妄动。' },
      { text: '咸其腓，凶，居吉。', xiang: '虽凶居吉，顺不害也。', meaning: '六二柔中得正，感于腿腓，躁动则凶，安居则吉。这是说感未当行，宜止不宜动。正如情意欲动，宜安居守正，顺则免害。' },
      { text: '咸其股，执其随，往吝。', xiang: '咸其股，亦不处也。志在随人，所执下也。', meaning: '九三刚而不中，感于大腿，执意随人而行，往则吝。这是说随人而动、所执卑下，则招羞吝。正如无主见而盲从于人，终失其身。' },
      { text: '贞吉悔亡，憧憧往来，朋从尔思。', xiang: '贞吉悔亡，未感害也。憧憧往来，未光大也。', meaning: '九四刚而不中，心神感应之位，守正则吉悔亡，然往来憧憧未光大。这是说心之感宜正，正则吉；若私情往来，则未光大。正如交心宜以正，去私存公，方为大感。' },
      { text: '咸其脢，无悔。', xiang: '咸其脢，志末也。', meaning: '九五刚中居尊，感于背脊，无动于衷，无悔。这是说感于背、不为外物所动，虽无悔而志未大。正如处尊而超然物外，虽无悔而所感未广。' },
      { text: '咸其辅颊舌。', xiang: '咸其辅颊舌，滕口说也。', meaning: '上六处咸之极，感于口舌，徒腾口说而无实。这是说感于言语、口惠而实不至，乃感之末。正如徒逞口舌之辩，无诚心实意，则感不通。' },
    ]
  },
  { no: 32, name: '恒',   full: '雷风恒',   upper: '震', lower: '巽', gong: '震', shi: 3, tuan: '亨，无咎，利贞，利有攸往。', xiang: '雷风，恒；君子以立不易方。', read: '恒久之道，宜立不易方，持恒有成。',
    meaning: '恒卦象征恒久，雷风相与，常久不息之象。恒之道在于立不易方、持守正道。亨通无咎，利贞利往，久于正道则有所成。',
    gaoTuan: '恒者，久也。雷风相与，恒之象也。刚上而柔下，雷风相与，巽而动，刚柔皆应，故恒亨。君子立不易方，守正不移，乃能久于其道。',
    yaos: [
      { text: '浚恒，贞凶，无攸利。', xiang: '浚恒之凶，始求深也。', meaning: '初六柔居下，浚恒深求，始即求深，贞亦凶，无攸利。这是说恒久之道忌始而求深、急功近利。正如相处之初，宜渐进不宜强求，否则虽正亦凶。' },
      { text: '悔亡。', xiang: '九二悔亡，能久中也。', meaning: '九二刚中失正，能久守中道，悔亡。这是说恒久守中、不偏不倚，则悔恨消失。正如做事能持久中正，则前悔自消。' },
      { text: '不恒其德，或承之羞，贞吝。', xiang: '不恒其德，无所容也。', meaning: '九三刚而不中，不能恒其德，或受羞辱，虽贞亦吝。这是说德不持久、反复无常，则招羞辱。正如人无恒德、朝三暮四，终为人所轻。' },
      { text: '田无禽。', xiang: '久非其位，安得禽也。', meaning: '九四刚而不中，久非其位，田猎无获。这是说所处非正、久而无功，徒劳无得。正如所守非道，虽久持亦无所成。' },
      { text: '恒其德，贞，妇人吉，夫子凶。', xiang: '妇人贞吉，从一而终也。夫子制义，从妇凶也。', meaning: '六五柔中居尊，恒其德而贞，妇人从一而终则吉，夫子制义从妇则凶。这是说恒德因人而异，妇人宜守贞从一，丈夫宜因时制义。正如男女之道不同，妇人守贞为吉，男子则不可一味从人。' },
      { text: '振恒，凶。', xiang: '振恒在上，大无功也。', meaning: '上六处恒之极，振动无常，不能恒守，凶而无功。这是说恒极而动、躁动不守，则大无功。正如守恒之道贵在沉静，躁动无常则败。' },
    ]
  },
  { no: 33, name: '遯',   full: '天山遯',   upper: '乾', lower: '艮', gong: '乾', shi: 2, tuan: '亨，小利贞。', xiang: '天下有山，遯；君子以远小人，不恶而严。', read: '退避隐遁，宜远小避害，及时抽身。',
    meaning: '遯卦象征退避隐遁，天下有山，山高而天退之象。当小人渐盛、君子道消之时，宜及时抽身退避，远小人不恶而严。遯之道在于知机识时，非消极逃避，而是保全自身以图后举，故亨而小利于贞。',
    gaoTuan: '遯者，退也，避也。天下有山，山止于下而天高于上，遯之象也。二阴浸长而阳当位以应，与时偕行，是以遯而能亨。君子观此象，以远小人，不恶而严，盖去之不露其迹，避之不绝其辞，乃遯之善者也。',
    yaos: [
      { text: '遯尾，厉，勿用有攸往。', xiang: '遯尾之厉，不往何灾也。', meaning: '初六处遯之末，已落于退避之后，欲往则危，故不可有所往。这是说退避宜早不宜迟，落于人后则反受其害。正如避险宜先机而动，迟疑落后反陷险地，宜止不宜行。' },
      { text: '执之用黄牛之革，莫之胜说。', xiang: '执用黄牛，固志也。', meaning: '六二柔中得正，以黄牛之革固结其志，坚不可拔。这是说守志不移、固守中道，则不为外物所动。正如身处遯时，宜固守其志、不随波逐流，坚贞自守。' },
      { text: '系遯，有疾厉，畜臣妾吉。', xiang: '系遯之厉，有疾惫也。畜臣妾吉，不可大事也。', meaning: '九三系累于下不能果断退避，如负重病而疲惫，唯畜养臣妾则吉。这是说心有所系、当断不断，则受其累。正如退避之际，宜断然舍弃，若心存系念，则反招其害。' },
      { text: '好遯，君子吉，小人否。', xiang: '君子好遯，小人否也。', meaning: '九四刚健能好遯，君子以退为吉，小人则不能。这是说君子能知进退、以退为乐，故吉；小人贪恋不舍，则否。正如当退则退，君子豁达于怀而全身，小人恋栈不舍而受困。' },
      { text: '嘉遯，贞吉。', xiang: '嘉遯贞吉，以正志也。', meaning: '九五刚中居尊，嘉美其遯，守正而吉。这是说高位之人以退为美、正志而行，最为吉祥。正如身居尊位而能从容引退、守正不阿，乃遯之至善。' },
      { text: '肥遯，无不利。', xiang: '肥遯无不利，无所疑也。', meaning: '上九处遯之极，超然物外，肥遯而去，无所不利。这是说退避之极，无所系累、无所疑虑，则进退自如。正如功成身退、超脱于外，则无往而不利。' },
    ]
  },
  { no: 34, name: '大壮', full: '雷天大壮', upper: '震', lower: '乾', gong: '坤', shi: 4, tuan: '利贞。', xiang: '雷在天上，大壮；君子以非礼弗履。', read: '阳刚壮盛，宜非礼弗履，戒躁进。',
    meaning: '大壮卦象征阳刚壮盛，雷在天上，声威大震之象。当阳气盛极之时，最忌恃强躁进，宜以礼自守，非礼弗履。壮之道在于守正用柔，不以壮而逞强，方能保其壮而不伤。',
    gaoTuan: '大壮者，大者壮也。雷在天上，威震于上，大壮之象也。四阳浸长，刚以动，故为大壮。然壮易于过，过则凶，故利贞，戒之以礼也。君子非礼弗履，养其大者也。',
    yaos: [
      { text: '壮于趾，征凶，有孚。', xiang: '壮于趾，其孚穷也。', meaning: '初九刚居下位，壮于足趾，妄行则凶，虽有孚亦穷。这是说壮始于末、躁动于行，则凶。正如年少气盛、恃强而前，必致穷困，宜慎其始。' },
      { text: '贞吉。', xiang: '九二贞吉，以中也。', meaning: '九二刚中得正，守中而行，贞正则吉。这是说壮而能中、守正不偏，则吉。正如身壮之时，宜持中守正，不偏不倚，方保其吉。' },
      { text: '小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。', xiang: '小人用壮，君子罔也。', meaning: '九三刚而过壮，小人逞其壮，君子则以网罟待之，贞而亦厉；如羝羊触藩，角被缠羸。这是说恃壮妄动、横冲直撞，必自困其角。正如人恃强好胜、不知收敛，反陷困厄。' },
      { text: '贞吉悔亡，藩决不羸，壮于大舆之輹。', xiang: '藩决不羸，尚往也。', meaning: '九四刚而能柔，贞正则吉悔亡，藩决而角不羸，壮如大车之輹。这是说壮而得正、刚柔相济，则前程无阻。正如力量既足又得其道，则可尚往而前、所向无碍。' },
      { text: '丧羊于易，无悔。', xiang: '丧羊于易，位不当也。', meaning: '六五柔居尊位，丧其壮羊于田畔，虽位不当而无忧。这是说居壮之时而能丧其壮、以柔守之，则无悔。正如处盛而能用柔、不强壮自恃，反得保全。' },
      { text: '羝羊触藩，不能退，不能遂，无攸利，艰则吉。', xiang: '不能退，不能遂，不详也。艰则吉，咎不长也。', meaning: '上六处壮之极，如羝羊触藩，进退两难，无所利；惟艰贞自守则吉。这是说壮极而困、进退维谷，宜以艰贞处之。正如物极必反，处困能守正艰忍，则咎不长而终吉。' },
    ]
  },
  { no: 35, name: '晋',   full: '火地晋',   upper: '离', lower: '坤', gong: '乾', shi: 4, tuan: '康侯用锡马蕃庶，昼日三接。', xiang: '明出地上，晋；君子以自昭明德。', read: '旭日升天，宜进德修业，光明上进。',
    meaning: '晋卦象征上进，明出地上，旭日东升之象。如康侯受天子厚赐、一日三接，君子当自昭明德，进德修业。晋之道在于柔顺而上行，以德而进，光明正大。',
    gaoTuan: '晋者，进也。明出地上，晋之象也。柔进而上行，康侯用锡马蕃庶，昼日三接，柔进而大明也。君子观此象，以自昭明德，进以正道，则可以受大宠而显于世。',
    yaos: [
      { text: '晋如，摧如，贞吉。罔孚，裕无咎。', xiang: '晋如摧如，独行正也。裕无咎，未受命也。', meaning: '初六处晋之初，欲进而见摧折，守正则吉；未孚于众，从容则无咎。这是说进之初多见阻挫，宜守正从容以待时。正如初入仕途，遭遇挫折，宜持正宽裕，未受命则不必急进。' },
      { text: '晋如，愁如，贞吉。受兹介福，于其王母。', xiang: '受兹介福，以中正也。', meaning: '六二柔中得正，欲进而愁忧，守正则吉，必受王母之大福。这是说进道虽忧，中正则必受福。正如居中守正、忧勤于事，终获上级大福。' },
      { text: '众允，悔亡。', xiang: '众允之志，上行也。', meaning: '六三柔而不中，得众之允信，则悔亡。这是说进道须得众信，众允则上行无悔。正如行事得众人信服拥护，则其志得行、悔恨消亡。' },
      { text: '晋如鼫鼠，贞厉。', xiang: '鼫鼠贞厉，位不当也。', meaning: '九四刚而不中，贪而进如鼫鼠，贞亦厉。这是说贪进无厌、处位不当，则危厉。正如贪求进取、无德以配，虽正亦危，宜戒其贪。' },
      { text: '悔亡，失得勿恤，往吉无不利。', xiang: '失得勿恤，往有庆也。', meaning: '六五柔中居尊，悔亡，得失皆勿忧，往则吉无不利。这是说居尊明进，不计得失，往则有庆。正如处高位而能旷达，不忧得失，则进无不吉。' },
      { text: '晋其角，维用伐邑，厉吉无咎，贞吝。', xiang: '维用伐邑，道未光也。', meaning: '上九处晋之极，进至角尖，惟用征伐邑国，厉而吉无咎，贞则吝。这是说进极而刚、用武于内，虽吉而道未光大。正如进取过极，反需自省其内，守正则吝，宜知止。' },
    ]
  },
  { no: 36, name: '明夷', full: '地火明夷', upper: '坤', lower: '离', gong: '坎', shi: 4, tuan: '利艰贞。', xiang: '明入地中，明夷；君子以莅众，用晦而明。', read: '光明受损，宜内敛用晦，韬光养晦。',
    meaning: '明夷卦象征光明受伤，明入地中，光明隐没之象。当乱世昏君在位、贤者受厄之时，宜内敛用晦、韬光养晦，以晦而保明。明夷之道在于外晦内明，守正待时，不轻易显露其才。',
    gaoTuan: '明夷者，明入地中，明夷之象也。日入地中，明夷之时也。君子当此，以莅众用晦而明，盖明不可息，晦乃所以保其明也。利艰贞者，处艰难而守正，乃明夷之道。',
    yaos: [
      { text: '明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言。', xiang: '君子于行，义不食也。', meaning: '初九见几而远去，如鸟垂翼而飞，君子于行三日不食，有所往则主人有言。这是说明夷之始，宜见机速去、不食而远行。正如见微知著、及早引退，虽衣食不继亦义不容留。' },
      { text: '明夷，夷于左股，用拯马壮，吉。', xiang: '六二之吉，顺以则也。', meaning: '六二柔中得正，伤于左股，借壮马以救之，吉。这是说身受微伤，得助以救，柔顺则吉。正如遭时之厄而能得助、柔顺自救，则化险为吉。' },
      { text: '明夷于南狩，得其大首，不可疾贞。', xiang: '南狩之志，乃大得也。', meaning: '九三刚明居下，南狩而得大首，不可疾于贞。这是说处明夷之时，以刚明而除大恶，宜缓不宜急。正如暗中除害、得其魁首，宜徐图而不宜急切。' },
      { text: '入于左腹，获明夷之心，于出门庭。', xiang: '入于左腹，获心意也。', meaning: '六四柔而得正，入于左腹，获明夷之心，而出门庭。这是说深得乱君之心腹，而知机引退而出。正如洞察昏主之心，知其不可为，及时引退以远害。' },
      { text: '箕子之明夷，利贞。', xiang: '箕子之贞，明不可息也。', meaning: '六五居尊而处明夷，如箕子之佯狂受辱，守贞不改，利贞。这是说至暗之时，外佯狂而内守明，贞而不渝。正如箕子身处乱世、佯狂为奴，而其明不息、其贞不改。' },
      { text: '不明晦，初登于天，后入于地。', xiang: '初登于天，照四国也。后入于地，失则也。', meaning: '上六处明夷之极，昏暗至极，初登于天，后入于地。这是说昏君初即位亦曾光照四海，终以失道而坠亡。正如昏暴之君，虽有初登之盛，终因失道而亡其国。' },
    ]
  },
  { no: 37, name: '家人', full: '风火家人', upper: '巽', lower: '离', gong: '巽', shi: 2, tuan: '利女贞。', xiang: '风自火出，家人；君子以言有物，而行有恒。', read: '家道之正，宜正位于内，言有物行有恒。',
    meaning: '家人卦象征家道，风自火出，火燃而风生之象。家道之正在于内外有别、各守其位，君子以言有物而行有恒。家人之道始于夫妇之正，而终于一家之相亲相爱。',
    gaoTuan: '家人者，一家之人也。风自火出，家人之象也。家人之道，利于女贞，盖正家之本在于女。君子以言有物而行有恒，言必有实，行必有常，乃能正其家而化于国。',
    yaos: [
      { text: '闲有家，悔亡。', xiang: '闲有家，志未变也。', meaning: '初九刚正居下，早立家规以闲防之，悔亡。这是说治家之初，宜立防闲、明其家规。正如治家贵在防患于始，未变之时先立其防，则无悔。' },
      { text: '无攸遂，在中馈，贞吉。', xiang: '六二之吉，顺以巽也。', meaning: '六二柔中得正，无所自遂，唯主中馈，贞正则吉。这是说妇人之道，柔顺中正、主持内事，则吉。正如家中女主以柔顺为本，专主中馈不擅外事，则家道吉。' },
      { text: '家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。', xiang: '家人嗃嗃，未失也。妇子嘻嘻，失家节也。', meaning: '九三刚而不中，治家严酷嗃嗃，虽悔厉而终吉；若妇子嘻嘻失节，则终吝。这是说治家宜严不宜纵，严虽招悔而终吉，纵则失节而终吝。正如教家贵严，过严虽厉而保其正，过宽则家道败。' },
      { text: '富家，大吉。', xiang: '富家大吉，顺在位也。', meaning: '六四柔而得正，能富其家，大吉。这是说柔顺得正、守位而能富家，最为吉祥。正如家主柔顺守正、勤俭持家，则家道丰裕大吉。' },
      { text: '王假有家，勿恤吉。', xiang: '王假有家，交相爱也。', meaning: '九五刚中居尊，王者至于其家，勿忧而吉。这是说家道至正，则王亦感化而至，交相爱护。正如家齐而后国治，一家相爱相感，则上下皆吉。' },
      { text: '有孚威如，终吉。', xiang: '威如之吉，反身之谓也。', meaning: '上九处家之极，以信立威，威而有信，终吉。这是说治家之道，必有孚信而后有威，威信相济则吉。正如家长以身作则、反身修德，则威信自立、家道终吉。' },
    ]
  },
  { no: 38, name: '睽',   full: '火泽睽',   upper: '离', lower: '兑', gong: '离', shi: 4, tuan: '小事吉。', xiang: '上火下泽，睽；君子以同而异。', read: '乖离背反，宜求同存异，小事可成。',
    meaning: '睽卦象征乖离背反，上火下泽，二性相违之象。当乖离之时，大事不可为，唯小事可吉，宜求同存异，以同而异。睽之道在于异中有同，于乖违中求相通，柔进上行则小事吉。',
    gaoTuan: '睽者，乖也，违也。上火下泽，睽之象也。二女同居，其志不同行，故睽。小事吉者，柔进而上行，得中而应乎刚，故小事犹吉，大事则未可也。君子以同而异，于乖违之中存大同之道。',
    yaos: [
      { text: '悔亡，丧马勿逐，自复。见恶人无咎。', xiang: '见恶人，以辟咎也。', meaning: '初九处睽之初，悔亡，丧马勿逐自复，见恶人亦无咎。这是说乖离之时，物失而自复，恶人亦当见之以免咎。正如乖违之际，宜宽和以待、不拒恶人，则反得无咎。' },
      { text: '遇主于巷，无咎。', xiang: '遇主于巷，未失道也。', meaning: '九二刚中得正，于巷中遇其主，无咎。这是说乖离之时，邂逅得遇其主，未失其道。正如乖违之际，宜以诚相求，纵非正途而得遇其主，亦无咎。' },
      { text: '见舆曳，其牛掣，其人天且劓，无初有终。', xiang: '见舆曳，位不当也。无初有终，遇刚也。', meaning: '六三柔不当中，见车被曳、牛被掣、人受刑，无初而有终。这是说乖违之时，身受其困，然终得合。正如乖离之际，初虽多艰、备受困辱，终得相合而有终。' },
      { text: '睽孤，遇元夫，交孚，厉无咎。', xiang: '交孚无咎，志行也。', meaning: '九四刚而不中，睽而孤立，遇元夫交孚，虽厉无咎。这是说乖离孤独之时，得遇善人、以诚相交，则无咎。正如孤身于乖违之世，遇志同道合者以诚相孚，则危厉可免。' },
      { text: '悔亡，厥宗噬肤，往何咎。', xiang: '厥宗噬肤，往有庆也。', meaning: '六五柔中居尊，悔亡，宗族相亲，往则何咎。这是说乖违之时，宗族和合相噬，往则有庆。正如居尊而能与宗亲相合，往则无咎而有庆。' },
      { text: '睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。', xiang: '遇雨之吉，群疑亡也。', meaning: '上九处睽之极，孤疑满腹，见豕见鬼，先张弧后说弧，匪寇乃婚媾，往遇雨则吉。这是说睽极生疑，疑心生鬼怪，悟其非寇乃婚，则疑亡而吉。正如乖违至极则群疑并生，一旦释疑悟真，则合而得吉。' },
    ]
  },
  { no: 39, name: '蹇',   full: '水山蹇',   upper: '坎', lower: '艮', gong: '兑', shi: 4, tuan: '利西南，不利东北。利见大人，贞吉。', xiang: '山上有水，蹇；君子以反身修德。', read: '行路艰难，宜反身修德，止而思进。',
    meaning: '蹇卦象征行路艰难，山上有水，水阻于山前之象。当险难在前之时，宜止而不进，反身修德，往则不利。蹇之道在于见险而止，反求诸己，修德以待时，利见大人则可济。',
    gaoTuan: '蹇者，难也，险也。山上有水，蹇之象也。险在前，见险而能止，知矣哉。利西南，往而有功也；不利东北，其道穷也。利见大人，往有功也。君子以反身修德，盖德修则难自解。',
    yaos: [
      { text: '往蹇，来誉。', xiang: '往蹇来誉，宜待也。', meaning: '初六柔居下，往则险难，来则有誉。这是说蹇难之时，宜止不宜往，来以待时则得誉。正如险难之际，宜退守待时，不宜躁进，则名位可保。' },
      { text: '王臣蹇蹇，匪躬之故。', xiang: '王臣蹇蹇，终无尤也。', meaning: '六二柔中得正，为王臣而蹇蹇匪躬，非为己身。这是说臣子之蹇，乃为国君而非为己，终无尤。正如忠臣为国、历险匪躬，虽多艰难而终无过咎。' },
      { text: '往蹇来反。', xiang: '往蹇来反，内喜之也。', meaning: '九三刚而不中，往则蹇难，来则反其本。这是说蹇时往则险，来则反守其内，内人喜之。正如险难在前，宜反守其本、安抚于内，则内得其安。' },
      { text: '往蹇来连。', xiang: '往蹇来连，当位实也。', meaning: '六四柔而得正，往则蹇难，来则与下相连。这是说蹇时往则险，来则合众以济，当位而实。正如处蹇之际，宜联合众力、合志共济，则可济险。' },
      { text: '大蹇朋来。', xiang: '大蹇朋来，以中节也。', meaning: '九五刚中居尊，大蹇之时，朋友来助。这是说处大蹇之中，以中正之节而得众助。正如高位处险，守正不阿，则志士来助、共济大难。' },
      { text: '往蹇来硕，吉，利见大人。', xiang: '往蹇来硕，志在内也。利见大人，以从贵也。', meaning: '上六处蹇之极，往则蹇，来则硕大而吉，利见大人。这是说蹇极将解，来则有大功，宜见大人以济之。正如险难将尽，宜归而就大、见大人而相从，则终吉。' },
    ]
  },
  { no: 40, name: '解',   full: '雷水解',   upper: '震', lower: '坎', gong: '震', shi: 2, tuan: '利西南，无所往，其来复吉。有攸往，夙吉。', xiang: '雷雨作，解；君子以赦过宥罪。', read: '险难消解，宜赦过宥罪，及时舒解。',
    meaning: '解卦象征险难消解，雷雨作，万物苏解之象。当险难初解之时，宜宽大赦宥，赦过宥罪，与民更始。解之道在于及时舒解，无所往则宜静守其复，有所往则宜夙疾而行。',
    gaoTuan: '解者，解也，险以动，动而免乎险，解之象也。雷雨作，天地之郁解而万物苏，故解。利西南，往得众也。君子以赦过宥罪，盖解之时宜宽，宽则众心服而难解。',
    yaos: [
      { text: '无咎。', xiang: '刚柔之际，义无咎也。', meaning: '初六柔居下，处解之初，刚柔相济，义无咎。这是说解难之初，柔顺自处、刚柔相得，则无咎。正如险难初解，宜柔静以待、与人和协，则免于咎。' },
      { text: '田获三狐，得黄矢，贞吉。', xiang: '九二贞吉，得中道也。', meaning: '九二刚中得正，田猎获三狐，得黄矢，贞正则吉。这是说解难之时，除邪去惑，得中道而吉。正如除小人之邪、去惑乱之患，守中正之道，则吉。' },
      { text: '负且乘，致寇至，贞吝。', xiang: '负且乘，亦可丑也。自我致戎，又谁咎也。', meaning: '六三柔而不中，负重而乘，致寇至，贞亦吝。这是说德薄而居高位、自招寇患。正如无德而居大位、名不副实，则自招祸患，虽正亦吝。' },
      { text: '解而拇，朋至斯孚。', xiang: '解而拇，未当位也。', meaning: '九四刚而不中，解其拇指，朋至而信之。这是说解去小人、然后众朋至而相孚。正如欲解群难，宜先去其下之小人，则众朋来助。' },
      { text: '君子维有解，吉。有孚于小人。', xiang: '君子有解，小人退也。', meaning: '六五柔中居尊，君子能解其难，吉；信孚于小人，小人退。这是说居尊而解难，以孚信待小人，则小人退而吉。正如高位解难，宜以信待下、宽宥小人，则小人退而难解。' },
      { text: '公用射隼，于高墉之上，获之，无不利。', xiang: '公用射隼，以解悖也。', meaning: '上六处解之极，公射隼于高墉之上而获之，无不利。这是说解极之时，除掉悖逆之恶鸟，则无不利。正如除恶务尽、擒其魁首，则悖乱解而无不利。' },
    ]
  },
  { no: 41, name: '损',   full: '山泽损',   upper: '艮', lower: '兑', gong: '艮', shi: 3, tuan: '有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享。', xiang: '山下有泽，损；君子以惩忿窒欲。', read: '损下益上，宜惩忿窒欲，损中有得。',
    meaning: '损卦象征损下益上，山下有泽，泽自损以润山之象。损之道在于有孚诚信，损己之忿欲以益德，惩忿窒欲，则元吉无咎。损之妙在损所当损，虽损而实有益，二簋之薄亦可享神。',
    gaoTuan: '损者，损下益上也。山下有泽，损之象也。损下而益上，损己而益人，损之道贵乎有孚，有孚则元吉无咎。惩忿窒欲，损之至善者也。二簋可用享，以诚不以物也。',
    yaos: [
      { text: '已事遄往，无咎，酌损之。', xiang: '已事遄往，尚合志也。', meaning: '初九刚正居下，事毕而速往助上，无咎，宜酌量而损之。这是说损下益上，宜速往以应、酌情而损。正如辅上之急，宜速应其求，量力而损，则合志无咎。' },
      { text: '利贞，征凶，弗损益之。', xiang: '九二利贞，中以为志也。', meaning: '九二刚中得正，利于守贞，妄征则凶，弗损而益之。这是说守正不妄行，不可损而强益之。正如处中守正，宜固守其志、不妄进损益，则吉。' },
      { text: '三人行，则损一人；一人行，则得其友。', xiang: '一人行，三则疑也。', meaning: '六三柔而不中，三人行则损一人，一人行则得其友。这是说损必有益，专一而行则得其友。正如同道不宜过多，专一相求则得其友，三则相疑而损一。' },
      { text: '损其疾，使遄有喜，无咎。', xiang: '损其疾，亦可喜也。', meaning: '六四柔而得正，损其疾病，速则有喜，无咎。这是说损己之过恶，宜速改之，则有喜。正如改正过错、去除弊病，宜速不宜迟，则无咎有喜。' },
      { text: '或益之十朋之龟弗克违，元吉。', xiang: '六五元吉，自上佑也。', meaning: '六五柔中居尊，人或益以十朋之大龟，不可却，元吉。这是说居尊而虚己，则天下自来益之，大吉。正如高位而谦虚自守，则众自归益，元吉而有天佑。' },
      { text: '弗损益之，无咎，贞吉，利有攸往，得臣无家。', xiang: '弗损益之，大得志也。', meaning: '上九处损之极，弗损而益之，无咎贞吉，利有所往，得臣而无家。这是说损极反益，不损于人而益之，则大得志。正如损极必反，居上而能益下，则得人心、大得志。' },
    ]
  },
  { no: 42, name: '益',   full: '风雷益',   upper: '巽', lower: '震', gong: '巽', shi: 3, tuan: '利有攸往，利涉大川。', xiang: '风雷，益；君子以见善则迁，有过则改。', read: '损上益下，宜见善则迁，迁善有益。',
    meaning: '益卦象征损上益下，风雷相益，雷动风烈之象。益之道在于损上以益下，君惠民而民悦，君子以见善则迁、有过则改。益之时利有攸往、利涉大川，下受益而上亦受益，上下相益则道大行。',
    gaoTuan: '益者，损上益下也。风雷，益之象也。雷动风烈，万物皆益。损上益下，民悦无疆，自上下下，其道大光。利有攸往，中正有庆也；利涉大川，木道乃行也。',
    yaos: [
      { text: '利用为大作，元吉，无咎。', xiang: '元吉无咎，下不厚事也。', meaning: '初九刚正居下，宜为大作，元吉则无咎。这是说居下受上之益，宜大有作为，元吉则无咎。正如受上之恩、宜有所建树，必大善而后可无咎。' },
      { text: '或益之十朋之龟弗克违，永贞吉。王用享于帝，吉。', xiang: '或益之，自外来也。', meaning: '六二柔中得正，或益以十朋之龟不可却，永贞则吉，王用以享帝而吉。这是说居中守正，则外来之益不可却。正如柔顺中正、不自求益，而益自外来，永贞则吉。' },
      { text: '益之用凶事，无咎。有孚中行，告公用圭。', xiang: '益用凶事，固有之也。', meaning: '六三柔而不中，以凶事受益，无咎，有孚中行，告公用圭。这是说处非常之时，以凶事而受益，宜有孚中行。正如遭凶事而受助，宜诚信守中、秉圭以告公，则无咎。' },
      { text: '中行，告公从。利用为依迁国。', xiang: '告公从，以益志也。', meaning: '六四柔而得正，中行而告公从，宜依之以迁国。这是说居近君之位，宜中行告公而见从，可依以迁国。正如居位行中、以告于公而见从，则可任大事、迁国而立。' },
      { text: '有孚惠心，勿问元吉。有孚惠我德。', xiang: '有孚惠心，勿问之矣。惠我德，大得志也。', meaning: '九五刚中居尊，有孚惠下之心，不问而元吉，下亦有孚信其德。这是说居尊以诚信惠民，则下信其德，大得志。正如君以诚心惠民，民亦以诚信感之，上下相孚则大吉。' },
      { text: '莫益之，或击之，立心勿恒，凶。', xiang: '莫益之，偏辞也。或击之，自外来也。', meaning: '上九处益之极，莫有益之，或击之，立心不恒则凶。这是说求益过极，反为人击，立心不恒则凶。正如贪求无厌、立心不恒，则众莫之益、反招攻击，凶。' },
    ]
  },
  { no: 43, name: '夬',   full: '泽天夬',   upper: '兑', lower: '乾', gong: '兑', shi: 5, tuan: '扬于王庭，孚号有厉。告自邑，不利即戎，利有攸往。', xiang: '泽上于天，夬；君子以施禄及下，居德则忌。', read: '决而能和，宜果决去奸，慎防刚过。',
    meaning: '夬卦五阳在下、一阴在上，象征众君子决去一小人，正义力量已占绝对优势，正是清除奸邪、决断是非之时。但卦辞警示「孚号有厉」「不利即戎」——纵然势在必行，也须光明正大地昭告天下，不可恃强用兵，否则刚过必折。这启示我们：除弊去奸要果决，但更要谨慎，守住正道与人心，方能决而能和、善始善终。',
    gaoTuan: '夬者，决也，五阳决一阴，去小人之象也。然阳虽盛而不可忽，故曰「扬于王庭，孚号有厉」，明告众人以危惧之心处之。「不利即戎」者，刚不可恃，暴不可用也。君子去小人，当以正而去之，非以力而胜之，故施禄及下，以收人心，居德则忌，以戒自满，乃可决而能和。',
    yaos: [
      { text: '壮于前趾，往不胜为咎。', xiang: '不胜而往，咎也。', meaning: '初九处夬卦之始，阳刚在下而急于前行。「壮于前趾」是说力量仅表现在脚趾上，看似勇壮实则不足。「往不胜为咎」警示：若不自量力、贸然前去决除小人，必因实力不足而招致灾祸。这提醒我们在力量未充、时机未到时，不可凭一时意气轻举妄动。' },
      { text: '惕号，莫夜有戎，勿恤。', xiang: '有戎勿恤，得中道也。', meaning: '九二居下卦之中，以刚居柔，能保持警惕。「惕号」是时刻警惕呼号，「莫夜有戎」是说即使深夜发生变故，也因早有戒备而安然无恙。「勿恤」即不必忧虑。这告诉我们：面对潜在危机，只要事先戒备、居中守正，纵有突发事变也能从容应对。' },
      { text: '壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。', xiang: '君子夬夬，终无咎也。', meaning: '九三刚亢外露，「壮于頄」是把刚壮之气显露在脸上，锋芒毕露故有凶险。但君子能决而又决，独自前行去对付小人，虽遇雨沾身、遭人误解而有愠色，终究因心志坚正而无咎。这启示我们：去恶务尽但不可逞强外露，要忍辱独行、不避嫌疑，方能成就决断之功。' },
      { text: '臀无肤，其行次且。牵羊悔亡，闻言不信。', xiang: '其行次且，位不当也。闻言不信，聪不明也。', meaning: '九四以阳居阴，位不当，进退两难。「臀无肤，其行次且」是说臀部没了皮肤，行走迟疑难前，比喻处境窘迫、犹豫不决。「牵羊悔亡」是说若能像牵羊一样顺其性而行则可无悔，可惜「闻言不信」——听不进忠告。这告诫我们：处于困境中要善于听取良言、顺势而为，切不可固执己见。' },
      { text: '苋陆夬夬，中行无咎。', xiang: '中行无咎，中未光也。', meaning: '九五居君位，是决除小人的主导者。「苋陆」是马齿苋一类柔脆的草木，比喻所决之阴柔小人也如苋陆般容易断除。但即使如此，仍须「中行」——不偏不倚、行于中道方能无咎。象传说「中未光也」，说明中道之行尚未光大，不可掉以轻心。这告诉我们：除奸去恶虽势在必成，仍要居中守正，不可稍存骄怠。' },
      { text: '无号，终有凶。', xiang: '无号之凶，终不可长也。', meaning: '上六是夬卦唯一的小人，居于众阳之上、将决未决之时。「无号」是说无人再为他呼号求情，孤立无援，终有凶险。象传「终不可长也」表明：小人虽一时在上，但其道不可长久，终将被决去。这启示我们：邪恶势力无论盘踞多高，违逆大势终将覆亡；而世人也不可心存侥幸、妄图倚恃奸邪。' },
    ]
  },
  { no: 44, name: '姤',   full: '天风姤',   upper: '乾', lower: '巽', gong: '乾', shi: 1, tuan: '女壮，勿用取女。', xiang: '天下有风，姤；后以施命诰四方。', read: '不期而遇，阴长侵阳，宜防微杜渐。',
    meaning: '姤卦一阴生于五阳之下，象征不期而遇、阴气始生而将浸长。卦辞「女壮，勿用取女」警示：此女表面柔顺实则刚壮，若娶之则阴气日盛、终将凌阳。这启示我们：事物的祸患往往起于微小，初生之阴虽弱却不可不防，要善于见微知著、防微杜渐，及时遏止不良势头的蔓延。',
    gaoTuan: '姤者，遇也，一阴生于五阳之下，柔遇刚也。然此阴虽微，其势甚壮，故曰「女壮，勿用取女」，戒人勿以小善为无伤而忽之也。盖阴之始生，犹涓涓之水，不塞将成江河；犹星星之火，不灭将燎原野。君子察其几于未萌，防其渐于方生，斯可以保其阳而不为阴所侵。',
    yaos: [
      { text: '系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。', xiang: '系于金柅，柔道牵也。', meaning: '初六是姤卦唯一之阴，居于最下，是阴气始生之时。「系于金柅」是说用金属的刹车木把车系住，比喻用刚正之道制止阴邪之初生，守正则吉；若放任其前往则见凶。「羸豕孚蹢躅」是说瘦弱的猪虽看似无力，却已在躁动不安，警示阴邪虽微而野心已露。这告诉我们：去恶要在萌芽之时，及早牵制则吉，纵容必成大患。' },
      { text: '包有鱼，无咎，不利宾。', xiang: '包有鱼，义不及宾也。', meaning: '九二以刚中包纳初六之阴，使其不能为害于众。「包有鱼」是说包藏住这条鱼（初六阴），「无咎」是因此无灾。「不利宾」是说此阴邪只可自己包制，不宜让它流到宾客（众人）中去。这启示我们：对潜在的危害要就地掌控、不让其扩散蔓延，方能保众人平安。' },
      { text: '臀无肤，其行次且，厉，无大咎。', xiang: '其行次且，行未牵也。', meaning: '九三与初六不能相应，欲往而不得，故「臀无肤，其行次且」——坐立不安、行走迟疑，处境危险但无大咎。象传「行未牵也」是说其行进未与阴邪相牵涉。这比喻人在面对诱惑时虽心有躁动，却因客观阻隔而未能付诸行动，虽有危厉却不致大咎，警示我们要守身如玉、不为外物所牵。' },
      { text: '包无鱼，起凶。', xiang: '无鱼之凶，远民也。', meaning: '九四以阳居阴，本应包纳初六，却因位置疏远而「包无鱼」——未能掌控住初六之阴，致使阴邪流散于下。「起凶」是说由此而兴起凶端。象传「远民也」是说疏远了在下之民（阴），失于防微。这告诫我们：居上位者若不能贴近下情、及时掌握细微变化，祸患便会从远处兴起。' },
      { text: '以杞包瓜，含章，有陨自天。', xiang: '九五含章，中正也。有陨自天，志不舍命也。', meaning: '九五居中正之位，「以杞包瓜」是用杞柳编成容器包藏住瓜（初六之阴），「含章」是内含美德的文采而不显露，「有陨自天」是说美好的际遇犹如天降。象传「志不舍命也」是说九五心志坚定，不忘天命。这启示我们：君子以中正之德包容万物、内怀章美，自然能得天助，化险为夷。' },
      { text: '姤其角，吝，无咎。', xiang: '姤其角，上穷吝也。', meaning: '上九处姤卦之极，高亢无应。「姤其角」是说像兽角一样刚硬地相触，遇而不合，故有「吝」——遗憾、不足。但因上九无所作为、不与阴邪相牵，故「无咎」。这比喻人在际遇中若过于刚硬高亢，便会错失相合之机而留遗憾；但若能守住本分不涉险地，也不致有真正灾祸。' },
    ]
  },
  { no: 45, name: '萃',   full: '泽地萃',   upper: '兑', lower: '坤', gong: '兑', shi: 2, tuan: '亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。', xiang: '泽上于地，萃；君子以除戎器，戒不虞。', read: '荟萃聚集，宜聚以正，修德聚人。',
    meaning: '萃卦泽上地上，水润大地、万物群聚之象，象征人才、众心荟萃一堂。卦辞讲聚以正道：王至宗庙以诚聚神，见大人以正聚人，用大牲以厚聚礼，皆取「聚而能正」之意。象传特提「除戎器，戒不虞」，提醒众聚之时易生变故，须居安思危、备防不测。这启示我们：聚人聚财要守正以诚，同时居安思危，方能聚而不散、长治久安。',
    gaoTuan: '萃者，聚也，泽上于地，润泽万物而群聚之象也。卦辞言「王假有庙」者，聚人心必先聚其神，以诚敬格祖考也。「利见大人」者，聚众必赖正人以主之。「用大牲吉」者，聚不可以薄，当厚其礼以示诚。然聚则易生变，故象曰「除戎器，戒不虞」，居安思危，乃能保其聚而不散也。',
    yaos: [
      { text: '有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎。', xiang: '乃乱乃萃，其志乱也。', meaning: '初六处萃之始，本欲有孚于四，却不能始终如一，心思纷乱而妄聚，故「乃乱乃萃」。但若能诚心呼号求正，便能「一握为笑」——握手言欢、转忧为喜，不必忧虑，前往无咎。这比喻人在初聚时易心志不专、随波逐流，但只要及时回归诚正，仍可化解乱局、得人所聚。' },
      { text: '引吉，无咎，孚乃利用禴。', xiang: '引吉无咎，中未变也。', meaning: '六二柔中正与九五相应，「引吉」是说被九五引而相聚，故吉而无咎。「孚乃利用禴」是说只要有诚心，即使像禴祭那样简薄的祭祀也能感动神明。象传「中未变也」是说六二守中不变。这启示我们：相聚贵在以诚相引、心志相合，不必拘泥于外在的隆重，真诚之心胜过繁文缛节。' },
      { text: '萃如嗟如，无攸利。往无咎，小吝。', xiang: '往无咎，上巽也。', meaning: '六三不中不正，上无应与，欲聚而无所得，故「萃如嗟如」——相聚不得反生叹息，无所利。但若能前往依从九四，则「往无咎，小吝」——虽有小遗憾但无大灾。象传「上巽也」是说顺从于上则可免咎。这告诫我们：身处孤立无援之境时，要善于择善而从，纵非最佳选择也能转危为安。' },
      { text: '大吉，无咎。', xiang: '大吉无咎，位不当也。', meaning: '九四以阳居阴、位不当，又近君而握聚众之权，本应有咎。但因九四能尽诚聚下、辅佐九五，致「大吉」方得「无咎」。象传「位不当也」点明其处境之险。这启示我们：身处名不正、位不当之时，唯有以大功大善来弥补，方能转咎为安，切不可居功自恃。' },
      { text: '萃有位，无咎。匪孚，元永贞，悔亡。', xiang: '萃有位，志未光也。', meaning: '九五居君位而聚天下，「萃有位」是说因君位而能聚众，故「无咎」。但「匪孚」——尚未完全取得天下之信，须「元永贞」——长久坚守元善正道，方能使悔恨消亡。象传「志未光也」是说聚人之志尚未光大。这告诫我们：居上位者纵已得位聚众，仍不可自满，要持续以正道立信，方能大光其志。' },
      { text: '赍咨涕洟，无咎。', xiang: '赍咨涕洟，未安上也。', meaning: '上六处萃卦之极，柔居无位，欲聚而不能下，孤高无依，故「赍咨涕洟」——叹息流泪、悲伤不安。但因上六能知危而惧、痛自反省，故「无咎」。象传「未安上也」是说其不安于居上之极。这启示我们：处穷极无应之地，能知惧自省、悲叹求正，亦能免于灾祸，正所谓「哀莫大于心死，而悔可以免咎」。' },
    ]
  },
  { no: 46, name: '升',   full: '地风升',   upper: '坤', lower: '巽', gong: '震', shi: 4, tuan: '元亨，用见大人，勿恤，南征吉。', xiang: '地中生木，升；君子以顺德，积小以高大。', read: '积小成高，宜顺德渐进，步步高升。',
    meaning: '升卦地中生木，木自地下缓缓长出地面，象征循序渐进、积小成大的上升之势。卦辞「元亨」预示上升之路通达，「用见大人」是说宜借助贤者之力，「南征吉」指出向光明方向进取则吉。象传「积小以高大」点明升进之道：靠的是顺德日积月累，而非一蹴而就。这启示我们：真正的提升源于日常的点滴积累，要顺其自然、稳步前行，方能由小至大、由低至高。',
    gaoTuan: '升者，上也，地中生木，自下而上之象也。木之生也，不见其长而日有所长，故君子法之，以顺德积小以高大。卦辞曰「用见大人，勿恤」者，升进必赖贤者之引，「南征吉」者，向明而行则吉。盖升之道在于顺，不在急；在于渐，不在骤，积之久而自成其高，斯乃天道之自然也。',
    yaos: [
      { text: '允升，大吉。', xiang: '允升大吉，上合志也。', meaning: '初六以阴居升卦之始，柔顺而上承二阳，「允升」是顺应众力、安然上升之意，故「大吉」。象传「上合志也」是说与在上者心志相合。这比喻人在事业起步时，若能谦逊柔顺、与上同心，借助众人之力顺势而上，便会大吉大利、稳步升进。' },
      { text: '孚乃利用禴，无咎。', xiang: '九二之孚，有喜也。', meaning: '九二刚中而有诚信，「孚乃利用禴」是说心诚则即使薄祭如禴亦能感神，故「无咎」。象传「有喜也」预示诚信必致喜庆。这启示我们：升进之时最可贵的是诚信，以诚心待人接物，纵然条件简朴，也能喜上加喜、稳步攀升。' },
      { text: '升虚邑。', xiang: '升虚邑，无所疑也。', meaning: '九三以刚健之质上升，前临虚邑（六四柔位空虚）、「升虚邑」是说如入无人之境般畅达无阻。象传「无所疑也」表明升进中毫无疑虑。这比喻人在升进途中，遇顺境畅通无阻时，当把握时机、勇毅前行，不必瞻前顾后、坐失良机。' },
      { text: '王用亨于岐山，吉，无咎。', xiang: '王用亨于岐山，顺事也。', meaning: '六四近君，「王用亨于岐山」是说君王（文王）在岐山祭天享神，以顺德行事而吉无咎。象传「顺事也」点明其事顺天而为。这比喻人在辅佐大事、上升之际，要像文王祭岐山那样，以顺天应人之德行事，方能吉而无咎。' },
      { text: '贞吉，升阶。', xiang: '贞吉升阶，大得志也。', meaning: '六五居君位而能守正，「贞吉」是守正则吉，「升阶」是说如登阶般一级一级稳步上升。象传「大得志也」表明升进而大遂其志。这启示我们：升进之道贵在守正不躁，要像拾级而上那样一步一个脚印，方能大遂其志、登峰造极。' },
      { text: '冥升，利于不息之贞。', xiang: '冥升在上，消不富也。', meaning: '上六处升卦之极，「冥升」是昏冥不止地贪求上升，已至穷极。「利于不息之贞」是说此时唯有坚守不息的正道才能得利。象传「消不富也」警示其升而不息反致消损。这告诫我们：升进到极点时不可贪求不已，要及时收敛、转而守正，否则贪进反消，适得其反。' },
    ]
  },
  { no: 47, name: '困',   full: '泽水困',   upper: '兑', lower: '坎', gong: '兑', shi: 1, tuan: '亨，贞，大人吉，无咎。有言不信。', xiang: '泽无水，困；君子以致命遂志。', read: '穷困之道，宜致命遂志，守正待通。',
    meaning: '困卦泽在水上，水本应润泽却渗漏于下，泽中干涸无水，象征君子困穷之境。卦辞「亨，贞，大人吉」指出：处困之时唯有守正才能亨通，且唯大人能济困而不为困所困。「有言不信」是说困顿时说话无人信从，不如少言多行。象传「致命遂志」更点明：身处穷困要豁出性命去成就志向。这启示我们：困境不是终点，而是磨砺心志、坚守正道的契机，守正致命方能转困为通。',
    gaoTuan: '困者，穷也，泽无水而涸，君子困穷之象也。然困而能亨，唯贞乃通，唯大人乃吉，何也？盖小人困则滥，大人困则志益坚，故曰「致命遂志」。处困之时，「有言不信」，盖人微言轻，说之无益，不如缄口修德，致命以遂其志，斯乃处困之道也。',
    yaos: [
      { text: '臀困于株木，入于幽谷，三岁不觌。', xiang: '入于幽谷，幽不明也。', meaning: '初六处困之始，柔弱居下，困于株木之上不得安坐，又陷入幽谷不见天日，三年不能自脱。象传「幽不明也」是说身处昏暗不明之境。这比喻人困穷之极、孤立无援，若自身柔弱无力又无贤者引援，便会长期困顿难脱，警示我们要及时修德求援，方能走出困境。' },
      { text: '困于酒食，朱绂方来，利用享祀，征凶，无咎。', xiang: '困于酒食，中有庆也。', meaning: '九二以刚中之德处困，虽「困于酒食」——为饮食之奉所困，但「朱绂方来」——朱色祭服所象征的荣禄将至。「利用享祀，征凶，无咎」是说宜以享祀守诚，不可妄动征行则凶而终无咎。象传「中有庆也」表明守中必有喜庆。这启示我们：处困而能守中持诚，纵暂时受困，荣禄喜庆终会到来。' },
      { text: '困于石，据于蒺藜，入于其宫，不见其妻，凶。', xiang: '据于蒺藜，乘刚也。入于其宫，不见其妻，不祥也。', meaning: '六三不中不正，前困于石、后据蒺藜，进退两难；入宫又不见妻子，孤立无亲，故「凶」。象传「乘刚也」「不祥也」点明其乘凌刚贤、致家室离散之不祥。这比喻人若名位不当、行为不端，便会前困于险、后据于棘、众叛亲离，处境凶险至极。' },
      { text: '来徐徐，困于金车，吝，有终。', xiang: '来徐徐，志在下也。虽不当位，有与也。', meaning: '九四以阳居阴、位不当，欲应初六而「来徐徐」——行动迟缓，又被「金车」所阻困，故有「吝」。但因其志在济下、有所应与，终能「有终」。象传「有与也」表明有相助之力。这告诉我们：处困境中虽有迟疑阻碍，但只要心志端正、有所作为，终能渡过难关、得善其终。' },
      { text: '劓刖，困于赤绂，乃徐有说，利用祭祀。', xiang: '劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。', meaning: '九五居君位而处困，受「劓刖」之刑伤、为「赤绂」之荣禄所困，「志未得也」是心志未伸。但因其「中直」——中正刚直，故「乃徐有说」——困终能徐徐解脱，「利用祭祀」则受福。这启示我们：纵然高位者亦难免困厄，只要守中正之德、以诚祭祀，终能缓缓脱困、转危为福。' },
      { text: '困于葛藟，于臲卼，曰动悔。有悔，征吉。', xiang: '困于葛藟，未当也。动悔有悔，吉行也。', meaning: '上六处困之极，被葛藟缠绕、动辄臲卼不安，故曰「动悔」——动则生悔。但「有悔，征吉」是说能悔悟前非、奋行改过则吉。象传「吉行也」点明悔过而行则吉。这启示我们：困境到极点时，与其困守缠扰，不如痛悔前非、果断前行，化悔为吉，方能脱困重生。' },
    ]
  },
  { no: 48, name: '井',   full: '水风井',   upper: '坎', lower: '巽', gong: '震', shi: 5, tuan: '改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。', xiang: '木上有水，井；君子以劳民劝相。', read: '养而不穷，宜修德惠民，源源不竭。',
    meaning: '井卦木上有水，水自木中源源涌出，象征井以养人、用之不竭的德泽。卦辞「改邑不改井」点出井德恒久——邑可迁移而井常在、养育之功不增不减；「羸其瓶，凶」警示：功成垂成若瓶破则凶，须善始善终。象传「劳民劝相」要求君子效井养之道，慰劳百姓、劝勉互助。这启示我们：要像井那样修德惠民、恒久不竭，且做事贵在有始有终。',
    gaoTuan: '井者，养也，木上有水，汲之以养人，源源而不竭也。「改邑不改井」者，井有常居，不以邑改而易其养，喻君子之德恒而不变。「羸其瓶，凶」者，功成几成而败之，可惜也。君子法井之德，劳民劝相，养而不穷，斯可以配天地下济之功矣。',
    yaos: [
      { text: '井泥不食，旧井无禽。', xiang: '井泥不食，下也。旧井无禽，时舍也。', meaning: '初六处井卦之底，井底淤泥沉积、浑浊不可食用，连飞禽都不来栖息。象传「下也」「时舍也」是说其居下位卑、为时所弃。这比喻人若不修养品德、积污成泥，便会被人所弃、无人亲近，警示我们要勤修德行、清污去浊，方能为人所用。' },
      { text: '井谷射鲋，瓮敝漏。', xiang: '井谷射鲋，无与也。', meaning: '九二处井之中却失其养人之用，井水下漏到谷中，只够小鱼穿梭；汲水的瓮又破漏，盛不住水。象传「无与也」是说无人相助、孤立无援。这比喻人有才德却无所施用、又无贤者引援，便会才能埋没、徒劳无功，警示我们要择善而处、寻求知遇之机。' },
      { text: '井渫不食，为我心恻，可用汲。王明，并受其福。', xiang: '井渫不食，行恻也。求王明，受福也。', meaning: '九三刚正而不中，井已疏浚洁净却仍不被食用，故「为我心恻」——令人心痛惋惜。但「可用汲」表明其终可用，所盼只待「王明」——明君识贤，则众人同受其福。象传「求王明，受福也」点明待明君而用则福。这比喻人有才德而不得其用、徒怀遗憾，但只要守德待时，终会遇明主而大用济世。' },
      { text: '井甃，无咎。', xiang: '井甃无咎，修井也。', meaning: '六四以柔居柔，正位而修井，「井甃」是用砖石砌修井壁，使之坚固洁净，故「无咎」。象传「修井也」点明其修德自固之功。这启示我们：处静修之时当如修井甃壁那样，勤修自身、补弊固漏，方能积蓄德泽、待时而用。' },
      { text: '井冽，寒泉食。', xiang: '寒泉之食，中正也。', meaning: '九五中正居尊，井水清冽甘美如寒泉可供人食用。象传「中正也」点明其德之中正。这是井德的极致：清冽甘洁、养人不穷。这比喻君子德行圆满、中正无私，自然如寒泉般清冽惠民，是修德济世的最高境界。' },
      { text: '井收勿幕，有孚元吉。', xiang: '元吉在上，大成也。', meaning: '上六处井卦之极，井已修成，「井收勿幕」是说汲水之后不盖上井口，让众人共用；「有孚元吉」是说有诚信而大吉。象传「大成也」表明井养之功至此大成。这启示我们：德成而能公之于众、惠及万民，方为大成，正是修德济世的圆满归宿。' },
    ]
  },
  { no: 49, name: '革',   full: '泽火革',   upper: '兑', lower: '离', gong: '坎', shi: 4, tuan: '巳日乃孚，元亨利贞，悔亡。', xiang: '泽中有火，革；君子以治历明时。', read: '顺天应人，宜除旧布新，变革以时。',
    meaning: '革卦泽中有火，水火相息而变革之象，象征顺天应人、除旧布新的大变革。卦辞「巳日乃孚」点明变革须待时机成熟方能取信于人，「元亨利贞」预示变革合乎正道则大通。象传「治历明时」要求君子效法天地变革之理，明辨时令、把握时机。这启示我们：变革不可贸然，须顺天时、得人心、守正道，方能除旧布新、悔亡而通。',
    gaoTuan: '革者，变也，泽中有火，水火相息而变革之象也。「巳日乃孚」者，变革必待其时，时至而民心信之也。「元亨利贞，悔亡」者，革而当则大通，正则无悔也。君子法之，治历以明时，盖历者天时之变，时变则革，革而合天，斯可以顺天应人，成其大功矣。',
    yaos: [
      { text: '巩用黄牛之革。', xiang: '巩用黄牛，不可以有为也。', meaning: '初九处革之始，以阳居下，时机未到，故「巩用黄牛之革」——用黄牛皮绳牢牢捆缚，比喻固守本分、不可妄动。象传「不可以有为也」明确此时不可有为。这告诉我们：变革之初时机尚未成熟，要像黄牛之革那样固守现状、积蓄力量，切不可贸然行事。' },
      { text: '己日乃革之，征吉，无咎。', xiang: '己日革之，行有嘉也。', meaning: '六二柔中得正，时机已至，「己日乃革之」是说在已日（变革时机成熟之日）开始推行变革，则「征吉，无咎」。象传「行有嘉也」预示行动必有嘉赏。这启示我们：变革当把握天时，时机一到便果断推行，则征进必吉、有所嘉成。' },
      { text: '征凶，贞厉。革言三就，有孚。', xiang: '革言三就，又何之矣。', meaning: '九三过刚不中，「征凶，贞厉」是说轻率征进则凶、守正亦危。但「革言三就，有孚」——变革之议须经再三斟酌成礼，方能取信于人。象传「又何之矣」是说除此别无他途。这告诉我们：变革不可操之过急，须反复审慎、谋定后动，以诚信服众方能成事。' },
      { text: '悔亡，有孚改命，吉。', xiang: '改命之吉，信志也。', meaning: '九四以阳居阴、近君，是变革的主导者。「悔亡，有孚改命，吉」是说悔恨消亡，以诚信改易旧命则吉。象传「信志也」点明其志在得信于民。这启示我们：变革要害在于以诚取信、改易旧制，唯有诚心为民、决心改命，方能大吉无悔。' },
      { text: '大人虎变，未占有孚。', xiang: '大人虎变，其文炳也。', meaning: '九五居君位而主持变革，「大人虎变」是说大人之变革如虎之换毛般焕然一新、文采炳焕。「未占有孚」是不必占卜已知其诚信可信。象传「其文炳也」赞其德辉炳焕。这比喻大人物的变革光明磊落、德泽彰显，自然深得人心、毋庸置疑。' },
      { text: '君子豹变，小人革面，征凶，居贞吉。', xiang: '君子豹变，其文蔚也。小人革面，顺以从君也。', meaning: '上六处革之极，「君子豹变」是说君子变革如豹之换毛般文采蔚然，「小人革面」是说小人只是改换面目、表面顺从。「征凶，居贞吉」警示此时不可再进，宜安居守正则吉。象传「顺以从君也」点明小人只是顺从。这告诉我们：变革已大成，君子当守其蔚然之德，不宜再事征伐，安贞守成方吉。' },
    ]
  },
  { no: 50, name: '鼎',   full: '火风鼎',   upper: '离', lower: '巽', gong: '离', shi: 2, tuan: '元吉，亨。', xiang: '木上有火，鼎；君子以正位凝命。', read: '鼎新取象，宜正位凝命，稳重图新。',
    meaning: '鼎卦木上有火，以火烹木、鼎烹熟食之象，象征鼎新养人、定鼎安邦的恢宏气象。卦辞「元吉，亨」预示鼎养之道大吉而通达。象传「正位凝命」要求君子端正其位、凝聚天命，如鼎之稳重以承载大任。这启示我们：成就一番鼎新大业，要稳守其位、调和鼎鼐、养贤育才，方能成就大吉亨通之局。',
    gaoTuan: '鼎者，器也，烹饪以养人，又为国家重器，象征定鼎安邦之象。「元吉，亨」者，鼎养之功，大吉而通也。君子法鼎之象，正位以凝命，盖鼎之体端正则实不倾，君子之位正则命可凝。调和鼎鼐，养贤育才，斯可以成其元吉之业矣。',
    yaos: [
      { text: '鼎颠趾，利出否，得妾以其子，无咎。', xiang: '鼎颠趾，未悖也。利出否，以从贵也。', meaning: '初六处鼎之底，颠倒鼎足，「利出否」是说利于倾倒出污秽之物；「得妾以其子」是贱妾因生子而得贵。象传「未悖也」「以从贵也」表明此举虽反常却非悖理、乃从贵之举。这告诉我们：破旧立新之初，要敢于倾倒积弊污秽，纵使方式看似反常，但只要能去浊从贵、推陈出新，便能无咎。' },
      { text: '鼎有实，我仇有疾，不我能即，吉。', xiang: '鼎有实，慎所之也。我仇有疾，终无尤也。', meaning: '九二以刚中居下，「鼎有实」是说鼎中已盛满食物（贤才充实），「我仇有疾，不我能即」是说虽仇家有疾不能近身相害。象传「慎所之也」「终无尤也」点明慎守则终无患。这启示我们：自身充实有德，纵有外患亦不能侵，要慎守其道、充实内涵，方能吉而无尤。' },
      { text: '鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。', xiang: '鼎耳革，失其义也。', meaning: '九三处鼎之中，「鼎耳革，其行塞」是说鼎耳变形、移动受阻，「雉膏不食」是美味雉膏不得食用，喻贤才不得其用。但「方雨亏悔，终吉」是说若逢阴阳和合之雨则悔损终吉。象传「失其义也」点明失用之憾。这比喻贤才暂时被阻不用，但终遇时机而得展其才，化悔为吉。' },
      { text: '鼎折足，覆公餗，其形渥，凶。', xiang: '覆公餗，信如何也。', meaning: '九四以阳居阴、力小任重，「鼎折足」是鼎足折断、「覆公餗」是倾覆了所盛的美食，「其形渥」是渥刑沾身，故「凶」。象传「信如何也」质问其德何以服众。这比喻才能不足以胜任重责者，便会如鼎折足般败事辱身，警示我们用人任事要量才而使，不可小材大用。' },
      { text: '鼎黄耳金铉，利贞。', xiang: '鼎黄耳，中以为实也。', meaning: '六五柔中居尊，「鼎黄耳金铉」是说鼎配有黄色鼎耳和金属鼎杠，华贵而便于举移。「利贞」是宜守正。象传「中以为实也」点明以中德为实。这比喻居上位者以中正之德调和鼎鼐、举重若轻，宜坚守正道方能成鼎养之功。' },
      { text: '鼎玉铉，大吉，无不利。', xiang: '玉铉在上，刚柔节也。', meaning: '上九处鼎之极，以阳居阴、刚柔相济，「鼎玉铉」是鼎杠以美玉装饰，「大吉，无不利」预示大吉而无往不利。象传「刚柔节也」点明刚柔有节之德。这比喻鼎养之功大成，玉铉温润华美象征德行圆满、刚柔得宜，自然大吉大利、无所不宜。' },
    ]
  },
  { no: 51, name: '震',   full: '震为雷',   upper: '震', lower: '震', gong: '木', shi: 6, tuan: '亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。', xiang: '洊雷，震；君子以恐惧修省。', read: '震动惊惧，宜恐惧修省，临危不乱。',
    meaning: '震卦上下皆震，雷声相续而震动之象，象征猝然临之的惊惧与变故。卦辞「震来虩虩，笑言哑哑」指出：面对惊雷先惧后笑，能恐惧修省者终能泰然。「震惊百里，不丧匕鬯」盛赞主祭者临危不乱、不失其守。象传「恐惧修省」点明处震之道：因恐惧而内省修身。这启示我们：人生难免猝然的震变，唯有平时戒惧修德、临危不乱，方能化险为夷、转危为安。',
    gaoTuan: '震者，动也，洊雷相继，震动天下之象也。「震来虩虩」者，恐惧之至也；「笑言哑哑」者，因惧而慎，遂能安也。「震惊百里，不丧匕鬯」者，临大变而不失其常守也。君子法之，恐惧以修省，盖能惧则能省，能省则能安，此乃处震之道也。',
    yaos: [
      { text: '震来虩虩，后笑言哑哑，吉。', xiang: '震来虩虩，恐致福也。笑言哑哑，后有则也。', meaning: '初九处震之始，先因震雷而恐惧战栗，后因能修省而笑语和乐，故吉。象传「恐致福也」「后有则也」点明：因恐惧而修省能致福，惧而后有法则。这告诉我们：面对突如其来的变故，先惧而后省、知惧而慎，便能转祸为福、得吉致安。' },
      { text: '震来厉，亿丧贝，跻于九陵，勿逐，七日得。', xiang: '震来厉，乘刚也。', meaning: '六二以柔乘刚，「震来厉」是雷震来而危险，「亿丧贝」是说将损失大量财货。「跻于九陵，勿逐，七日得」是说登避于九重之陵，不必追寻，七日自可复得。象传「乘刚也」点明其危因柔乘刚。这启示我们：遇难时不可贪恋财物而冒进，应暂避高处、静待其变，时过境迁自会失而复得。' },
      { text: '震苏苏，震行无眚。', xiang: '震苏苏，位不当也。', meaning: '六三不中不正，「震苏苏」是说因震雷而苏苏不安、惊惶失措。但若能因震而前行修省，则「震行无眚」——前行可免灾眚。象传「位不当也」点明其不安之因。这告诉我们：处境不当而心生惶惧时，正可借震动之机前行改图，便能转危为安、免于灾眚。' },
      { text: '震遂泥。', xiang: '震遂泥，未光也。', meaning: '九四以阳居阴、不中不正，「震遂泥」是说雷震之时陷入泥淖、不能自拔。象传「未光也」点明其德未光、无力自振。这比喻人若平时无德行根基、处位不当，遇震动之时便会陷入泥淖、进退两难，警示我们要居安修德、固本培元，方能临危不陷。' },
      { text: '震往来厉，亿无丧，有事。', xiang: '震往来厉，危行也。其事在中，大无丧也。', meaning: '六五居尊而柔，「震往来厉」是说往来皆有震动危险，但因「有事」——能守中执事，故「亿无丧」——纵有大震也无大损失。象传「危行也」「其事在中，大无丧也」点明其危行而能守中、故无大丧。这启示我们：居上位者面对往来震动之危，只要守中秉公、勤于其事，便能保大不失、转危为安。' },
      { text: '震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。', xiang: '震索索，中未得也。虽凶无咎，畏邻戒也。', meaning: '上六处震之极，「震索索，视矍矍」是说恐惧得瑟瑟发抖、目光惊惶，此时征进则凶。但「震不于其躬，于其邻」——震未及己身而先及邻里，能因邻之震而预戒，故「无咎」。「婚媾有言」是说虽无咎却有口舌之议。象传「畏邻戒也」点明因畏邻戒而免咎。这告诉我们：见邻人有变而预先戒备、自省防患，纵处险境也能免咎。' },
    ]
  },
  { no: 52, name: '艮',   full: '艮为山',   upper: '艮', lower: '艮', gong: '土', shi: 6, tuan: '艮其背，不获其身，行其庭，不见其人，无咎。', xiang: '兼山，艮；君子以思不出其位。', read: '止其所止，宜思不出位，动静有时。',
    meaning: '艮卦上下皆艮，两山相叠而静止不动之象，象征止于其所、知止不妄的智慧。卦辞「艮其背，不获其身，行其庭，不见其人」以背为喻：止于背则不见其身、行于庭亦不见其人，心境止于无欲之境，故「无咎」。象传「思不出其位」点明艮止之道：思虑不越其本分。这启示我们：当止则止、知止而止，动静各得其时，方能心安无咎。',
    gaoTuan: '艮者，止也，兼山相叠，静止不动之象也。「艮其背」者，止于所当止，不见其身，无私无我之境也。「行其庭，不见其人」者，外虽动而内不动，物来顺应而心不系也。君子法之，思不出其位，盖位有定分，思有定止，止于至善，斯可以无咎矣。',
    yaos: [
      { text: '艮其趾，无咎，利永贞。', xiang: '艮其趾，未失正也。', meaning: '初六处艮之始，从最下的脚趾止起，「艮其趾」是动之于未萌、止之于初始。象传「未失正也」点明其未失正道。「利永贞」是说宜长久守正。这告诉我们：止动当在萌芽之初，及早收敛妄念、长久持正，方能无咎而保全。' },
      { text: '艮其腓，不拯其随，其心不快。', xiang: '不拯其随，未退听也。', meaning: '六二居下中，「艮其腓」是止住小腿，但小腿随动而进、「不拯其随」是说不能挽救其随人而动之失，故「其心不快」。象传「未退听也」是说其未能退而听从。这比喻人被外物牵动、欲止不能，心中不快，警示我们当止之时要果断退听，不可随波逐流。' },
      { text: '艮其限，列其夤，厉熏心。', xiang: '艮其限，危熏心也。', meaning: '九三以刚居刚、不中，「艮其限」是止于腰部，「列其夤」是说上下分裂、脊肉分开，阴阳不相接，「厉熏心」是危险如熏心之火。象传「危熏心也」点明其危。这比喻强行割裂上下、强止一处而不能通达，必致心危如焚，警示我们止要适中、上下相通，不可偏执一端。' },
      { text: '艮其身，无咎。', xiang: '艮其身，止诸躬也。', meaning: '六四以柔居柔、得正，「艮其身」是止住整个身躯、安守本位，故「无咎」。象传「止诸躬也」点明其能自止其身。这启示我们：能止住自身、不为外物所动，安守本分、内省修身，便能无咎而安。' },
      { text: '艮其辅，言有序，悔亡。', xiang: '艮其辅，以中正也。', meaning: '六五居尊而柔中，「艮其辅」是止住颊辅（口舌），「言有序」是说话有条理、得当而不妄言，故「悔亡」。象传「以中正也」点明其守中正之德。这启示我们：言语当止则止、当言则有序，谨言慎行而守中正，便能悔恨消亡。' },
      { text: '敦艮，吉。', xiang: '敦艮之吉，以厚终也。', meaning: '上九处艮之极，以阳居阴，「敦艮」是敦厚而止、止于至善，故「吉」。象传「以厚终也」点明其以敦厚成终。这是艮止的最高境界：止得敦厚、终始如一。这启示我们：知止而能敦厚持守、至善以终，方能成就圆满吉祥。' },
    ]
  },
  { no: 53, name: '渐',   full: '风山渐',   upper: '巽', lower: '艮', gong: '艮', shi: 3, tuan: '女归吉，利贞。', xiang: '山上有木，渐；君子以居贤德，善俗。', read: '循序渐进，宜稳步积进，女归则吉。',
    meaning: '渐卦讲的是循序渐进之理。山下有木，树木生长缓慢却坚定，正合「渐」之意。卦辞以「女归吉」为喻——女子出嫁须循六礼，一步一步来才能吉祥。这启示我们：凡事不可急于求成，无论学业、事业还是感情，都要像树木生长一样，扎下深根、逐层累积，最终必有所成。',
    gaoTuan: '渐者，渐进也。山上有木，木之生也，以渐而成。卦辞曰「女归吉，利贞」，盖女子之嫁，必待六礼之备，循序渐进，乃得其吉。君子观此象，知凡事之成，皆有其序，不可以急求，亦不可以怠废，惟渐进守正，则吉无不利。',
    yaos: [
      { text: '鸿渐于干，小子厉，有言，无咎。', xiang: '小子之厉，义无咎也。', meaning: '初六居渐之始，鸿雁飞到水边，尚未登岸。「小子厉」是年少无知者贸然前进会有危险，「有言」是会招来非议，但因其位卑力弱、渐进不躁，故「无咎」。这是说起步之初根基未稳，难免被人议论，但只要不冒进便无大碍。就像初入职场的新人，做事会被挑剔，但虚心学习、稳扎稳打，终能立足。' },
      { text: '鸿渐于磐，饮食衎衎，吉。', xiang: '饮食衎衎，不素饱也。', meaning: '六二柔中得正，鸿雁飞到大磐石上，安稳立足。「饮食衎衎」是吃得和乐安泰，「不素饱」是并非白吃饭而是有所作为。这是渐卦中得位安养的吉象：找到稳固的根基后，便能安心积累、和乐前行。就像创业者找到了稳定的盈利模式，可以安心发展。' },
      { text: '鸿渐于陆，夫征不复，妇孕不育，凶；利御寇。', xiang: '夫征不复，离群丑也。妇孕不育，失其道也。利用御寇，顺相保也。', meaning: '九三过刚不中，鸿雁飞到高平之地却失其所宜。「夫征不复」是丈夫出征不归，「妇孕不育」是妻子怀孕却不能生育——比喻冒进脱离本分，必有凶险。但「利御寇」表示若能守正防患，仍可自保。这警示我们：急于求成、不顾本分会两头落空，唯有安守本分、防患未然才能保全。' },
      { text: '鸿渐于木，或得其桷，无咎。', xiang: '或得其桷，顺以巽也。', meaning: '六四柔正居上位，鸿雁飞到树上本非所宜（鸿雁爪蹼不便于栖树），但「或得其桷」——恰巧找到平正的椽木可以落脚，故「无咎」。象传「顺以巽也」点明其以柔顺谦逊自处。这告诉我们：身处不习惯的境地，能柔顺谦逊、随遇而安，便能化险为夷。' },
      { text: '鸿渐于陵，妇三岁不孕；终莫之胜，吉。', xiang: '终莫之胜，吉；得所愿也。', meaning: '九五中正居尊，鸿雁飞到高陵之上。「妇三岁不孕」是过程漫长艰难、似有阻滞；但「终莫之胜」——终究没有什么能胜过它，得遂其愿而吉。这是说：正道之事虽历久方成，但守正不移终能如愿。就像多年的努力终于开花结果，关键在于坚持。' },
      { text: '鸿渐于陆，其羽可用为仪，吉。', xiang: '其羽可用为仪，吉；不可乱也。', meaning: '上九居渐之极，鸿雁飞到极高之地，其羽毛可作为仪饰，吉。「不可乱也」是说不失其序、进退有度。这是渐卦的最高境界：渐进至极而能守仪度，进退有序、举止可为世人法式。这启示我们：登顶之后更要持守风范，进退有据方为圆满。' },
    ]
  },
  { no: 54, name: '归妹', full: '雷泽归妹', upper: '震', lower: '兑', gong: '兑', shi: 3, tuan: '征凶，无攸利。', xiang: '泽上有雷，归妹；君子以永终知敝。', read: '婚嫁之象，宜守正防偏，过求则失。',
    meaning: '归妹卦讲的是女子出嫁之道，引申为行事不可违背常理正分。卦辞「征凶，无攸利」直言冒进则凶、无所利——因为「归妹」之名本含「以妾为妻、越分而动」之意。这警示我们：凡事要名正言顺，若贪图近利、违背本分必招凶险；唯有守正待时方能善终。',
    gaoTuan: '归妹者，女子之归也。雷动于泽上，女从男之象。卦辞曰「征凶，无攸利」，盖谓女子之嫁，当循礼以待时，不可强求；苟越分而动，则必凶也。君子观此象，知凡事之动，必正其名分，不可以情乱礼，以欲害义。',
    yaos: [
      { text: '归妹以娣，跛能履，征吉。', xiang: '归妹以娣，以恒也。跛能履吉，相承也。', meaning: '初九以娣（侧室）身份出嫁，虽如跛足之人却能行走——地位虽低，却安于本分，故征而吉。「以恒也」「相承也」点明其恒守常分、辅佐正室。这告诉我们：身处低位不怨不躁，安分守己、勤勉辅佐，终能有所成就。' },
      { text: '眇能视，利幽人之贞。', xiang: '利幽人之贞，未变常也。', meaning: '九二阳刚居阴位，如眇目之人却能视物——才能不为所用，故「利幽人之贞」，宜守静如隐士。「未变常也」是不改其操守。这是说怀才不遇时，要像隐士一样守正不阿，不因外境改变本心。' },
      { text: '归妹以须，反归以娣。', xiang: '归妹以须，未当也。', meaning: '六三不中不正，本欲以正室出嫁，却因失德，反被降为娣妾侧室。「未当也」点明其位不当、德不配。这警示我们：贪求高位而德不称，终会跌落，反不如安守本分。' },
      { text: '归妹愆期，迟归有时。', xiang: '愆期之志，有待而行也。', meaning: '九四刚居阴位，出嫁之期推迟，「迟归有时」是说虽迟却终有归时。「有待而行也」是有所等待、择时而动。这是说：宁可迟婚也要等待正配，不可草率将就。守得初心，终得良缘。' },
      { text: '帝乙归妹，其君之袂，不如其娣之袂良；月几望，吉。', xiang: '帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。', meaning: '六五居尊位，以帝乙嫁女为喻。正室的衣饰反不如侧室华美——因其德贵在内而不在饰。「月几望」是月近圆满之象，故吉。这启示我们：真正的高贵在于内德，而非外饰；居尊而能谦俭，方为大吉。' },
      { text: '女承筐无实，士刲羊无血，无攸利。', xiang: '上六无实，承虚筐也。', meaning: '上六居归妹之极，女子捧筐却无实物，男子宰羊却不见血——婚姻之礼徒有其表而无实质。「承虚筐也」点明其有名无实。这是说：婚姻或合作若只重形式而无真情实质，必无所利。提醒我们凡事重在内涵，不可徒具虚名。' },
    ]
  },
  { no: 55, name: '丰',   full: '雷火丰',   upper: '震', lower: '离', gong: '震', shi: 5, tuan: '亨，王假之，勿忧，宜日中。', xiang: '雷电皆至，丰；君子以折狱致刑。', read: '丰大盛满，宜盛极思危，光明中正。',
    meaning: '丰卦讲的是盛极之道。卦辞「亨，王假之，勿忧，宜日中」——王者能致丰大之盛，不必忧虑，但要如日中天般光明正大。盛极最易骄盈，故象传以「折狱致刑」警戒：盛时更要明断是非、刑罚得当。这启示我们：处于丰盛之时，要光明中正、居安思危，方能保其盛而不衰。',
    gaoTuan: '丰者，大也。雷电皆至，光明威震并至之象。卦辞曰「王假之，勿忧，宜日中」，盖王者致丰大之治，当如日之方中，光照天下，无所忧也。然盛极必衰，日中则昃，君子观此象，知丰大之时，尤宜守中正，以折狱致刑，明慎而不失。',
    yaos: [
      { text: '遇其配主，虽旬无咎，往有尚。', xiang: '虽旬无咎，过旬灾也。', meaning: '初九居丰之始，遇到与自己相当之主（配主），「虽旬无咎」是说在十日之内平等相待无咎，「往有尚」是前往有所嘉尚。但「过旬灾也」警示超过限度则生灾。这是说：盛时与贤者相得，平等合作则吉，但不可久恋，否则生变。' },
      { text: '丰其蔀，日中见斗，往得疑疾，有孚发若，吉。', xiang: '有孚发若，信以发志也。', meaning: '六二居下卦之中，「丰其蔀」是遮蔽之物太大，「日中见斗」是日当正午却见星斗——光明被遮蔽、暗主在上之象。前往则招疑疾，但「有孚发若」——以诚信感发则吉。这是说：身处昏暗之世，要以诚信守正，终能感通上意而得吉。' },
      { text: '丰其沛，日中见沬，折其右肱，无咎。', xiang: '丰其沛，不可大事也。折其右肱，终不可用也。', meaning: '九三处丰之盛极遮蔽更深，「丰其沛」是幔幕过大，「日中见沬」是日中却见小星。「折其右肱」是如折断右臂，无法施展。但「无咎」因其能自处不躁。这是说：身处黑暗乱世，不可大有作为，宁可折损自身以避祸，明哲保身方无咎。' },
      { text: '丰其蔀，日中见斗，遇其夷主，吉。', xiang: '丰其蔀，位不当也。日中见斗，幽不明也。遇其夷主，吉行也。', meaning: '九四阳居阴位，与六二同象「丰其蔀，日中见斗」——同样身处昏暗。但「遇其夷主」——遇到与自己同德的伙伴，故吉。这是说：身处昏暗之时，找到志同道合之人相辅而行，便能拨云见日，共克时艰。' },
      { text: '来章，有庆誉，吉。', xiang: '六五之吉，有庆也。', meaning: '六五柔中居尊，「来章」是招致天下之贤才美章（光明），故「有庆誉」而吉。这是丰卦最吉之爻：以柔中之君招致贤才，光明汇聚，天下同庆。这启示我们：领导者要礼贤下士、汇聚众才，方能成就丰大之业。' },
      { text: '丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。', xiang: '丰其屋，天际翔也。窥其户，阒其无人，自藏也。', meaning: '上六居丰之极，「丰其屋」是房屋高大，「蔀其家」是家室被遮蔽，「窥其户阒其无人」是窥视门户却寂静无人，「三岁不觌」是三年不见人影——丰大其屋却深自闭藏，与世隔绝。「自藏也」点明其自取孤立。这是说：盛极而骄、自我封闭脱离众人，必致凶险。' },
    ]
  },
  { no: 56, name: '旅',   full: '火山旅',   upper: '离', lower: '艮', gong: '离', shi: 1, tuan: '小亨，旅贞吉。', xiang: '山上有火，旅；君子以明慎用刑，而不留狱。', read: '行旅在外，宜明慎柔顺，不宜久留。',
    meaning: '旅卦讲的是行旅在外、客居他乡之道。卦辞「小亨，旅贞吉」——行旅之事仅得小通，能守正则吉。象传「明慎用刑，而不留狱」指出在外要明察慎断、不滞留事务。这启示我们：身处客地，要柔顺谦下、明察慎行，不可张扬久留，方能平安。',
    gaoTuan: '旅者，羁旅也。山上有火，火行不久，旅人之象也。卦辞曰「小亨，旅贞吉」，盖旅之为道，所居不久，柔顺谦下则吉。君子观此象，知行旅之际，当明慎用刑，而不留狱，凡事以速决为要，不可以久留。',
    yaos: [
      { text: '旅琐琐，斯其所取灾。', xiang: '旅琐琐，志穷灾也。', meaning: '初六柔居最下，旅途中琐碎吝啬、卑躬屈膝，反而招致灾祸。「志穷灾也」是志意穷促而招灾。这是说：身为旅人本就弱小，若再卑琐自轻更易被人欺凌。出门在外要谨守尊严，不可过于卑微。' },
      { text: '旅即次，怀其资，得童仆贞。', xiang: '得童仆贞，终无尤也。', meaning: '六二柔中得正，旅人住进客栈，怀揣资财，又有忠贞的童仆相随。「终无尤也」是终无忧患。这是旅卦最吉之爻：客居有安身之所、有财物、有忠仆，三者俱备方能安稳。这告诉我们：行旅在外，要预先备好根基和助力。' },
      { text: '旅焚其次，丧其童仆，贞厉。', xiang: '旅焚其次，亦以伤矣。以旅与下，其义丧也。', meaning: '九三过刚不中，旅人住的客栈被焚毁，童仆也逃散了。「以旅与下，其义丧也」——以旅人身份而慢待下属，理当丧失人心。这是说：身在客地却骄横待下，必致众叛亲离、灾祸连连。客居更要谦和待下，方能得人心。' },
      { text: '旅于处，得其资斧，我心不快。', xiang: '旅于处，未得位也。得其资斧，心未快也。', meaning: '九四刚居阴位，「旅于处」是暂时栖身，「得其资斧」是有资财工具可用，但「我心不快」——心中并不舒畅。「未得位也」点明其未得正位。这是说：客居虽有资财可用，但终究寄人篱下，心中难安。提醒我们：身非其位，即使物质无忧，心中仍会不宁。' },
      { text: '射雉一矢亡，终以誉命。', xiang: '终以誉命，上逮也。', meaning: '六五柔中居尊，「射雉一矢亡」是射雉虽失一箭，终能射获而得美誉封命。「上逮也」是上达于君、得蒙恩命。这是说：旅人虽略有损耗，但因守正谦和，终能上达获誉。客居在外，要勇于付出小损以换大得。' },
      { text: '鸟焚其巢，旅人先笑后号啕。丧牛于易，凶。', xiang: '以旅在上，其义焚也。丧牛于易，终莫之闻也。', meaning: '上九居旅之极，鸟巢被焚，旅人先欢笑后嚎啕大哭，又丢失了牛，凶。「以旅在上，其义焚也」——以旅人身份高居，理当被焚。「丧牛于易，终莫之闻也」——丢失了顺从之德，终究无人过问。这是说：客居高位却骄横傲慢，必招灾祸，先乐后悲。身处客地，切忌骄傲自大。' },
    ]
  },
  { no: 57, name: '巽',   full: '巽为风',   upper: '巽', lower: '巽', gong: '木', shi: 6, tuan: '小亨，利有攸往，利见大人。', xiang: '随风，巽；君子以申命行事。', read: '顺而能入，宜申命行事，谦顺得进。',
    meaning: '巽卦讲的是顺逊入物之道。巽为风，风无所不入，故象传「申命行事」——反复申明命令、推行政事。卦辞「小亨，利有攸往，利见大人」——逊顺则小通，有所往则利，宜见大人。这启示我们：谦逊柔顺、深入贯彻方能成事；但要有所依凭，不可一味退让。',
    gaoTuan: '巽者，入也，顺也。随风相继，命令申饬之象。卦辞曰「小亨，利有攸往，利见大人」，盖巽之为道，以顺而入，故小亨而有所往；然必见大人，乃得其正。君子观此象，知政令之施，当反复申命，而后行事，则民易从。',
    yaos: [
      { text: '进退，利武人之贞。', xiang: '进退，志疑也。利武人之贞，志治也。', meaning: '初六柔居最下，「进退」是犹豫不决、进退失据。「利武人之贞」是说宜用武人的果决守正来克服犹疑。「志疑也」「志治也」点明其志意疑虑，须以刚决治之。这是说：过于谦逊而致犹豫，要培养果决刚毅之气，方能立事。' },
      { text: '巽在床下，用史巫纷若，吉无咎。', xiang: '纷若之吉，得中也。', meaning: '九二阳居阴位，「巽在床下」是逊顺到过分（俯伏床下）。「用史巫纷若」是借祝史巫觋多次祝祷以通神明。「得中也」点明其中道可取。这是说：逊顺虽过，但能以诚信感通，故仍吉无咎。谦逊要把握分寸，过则需以诚敬补救。' },
      { text: '频巽，吝。', xiang: '频巽之吝，志穷也。', meaning: '九三过刚不中，「频巽」是勉强皱眉逊顺、非出本心。「志穷也」是其志意穷促、勉强应付。这是说：表面逊顺而内心不服，必然吝吝难行。真正的谦逊要发自内心，勉强的顺从终难持久。' },
      { text: '悔亡，田获三品。', xiang: '田获三品，有功也。', meaning: '六四柔正居上位，「悔亡」是悔恨消失，「田获三品」是田猎获三等猎物（用于祭祀、招待、充庖）。「有功也」点明其功业有成。这是说：以柔顺之姿居上位，能广收众功、无所不宜。谦逊得当，便能有所成就。' },
      { text: '贞吉悔亡，无不利。无初有终，先庚三日，后庚三日，吉。', xiang: '九五之吉，位中正也。', meaning: '九五中正居尊，「贞吉悔亡，无不利」——守正则吉、悔亡无不顺。「先庚三日，后庚三日」是申明命令前后各三日郑重其事。「位中正也」点明其以中正之德申命行事。这是说：领导者发布命令要慎重，前后审度，方能令出必行。' },
      { text: '巽在床下，丧其资斧，贞凶。', xiang: '巽在床下，上穷也。丧其资斧，正乎凶也。', meaning: '上九居巽之极，「巽在床下」是逊顺到极点，「丧其资斧」是丧失了资财与决断之器。「上穷也」「正乎凶也」点明其高极而穷、理当凶险。这是说：一味卑屈、丧失刚断，必致凶险。谦逊不可过度，要守住底线和决断。' },
    ]
  },
  { no: 58, name: '兑',   full: '兑为泽',   upper: '兑', lower: '兑', gong: '金', shi: 6, tuan: '亨，利贞。', xiang: '丽泽，兑；君子以朋友讲习。', read: '和悦相通，宜朋友讲习，悦以犯难。',
    meaning: '兑卦讲的是和悦相感之道。兑为泽，两泽相连、相互滋润，故象传「朋友讲习」——朋友相互切磋讲习。卦辞「亨，利贞」——喜悦相通则亨通，但须守正。这启示我们：真正的喜悦来自以正道相交、以学问相砥砺，而非阿谀奉承、纵欲求欢。',
    gaoTuan: '兑者，说也。丽泽并润，朋友讲习之象。卦辞曰「亨，利贞」，盖和悦则亨通，然必以正为本，苟失其正，则悦反为害。君子观此象，知朋友之道，在于以学问相切磋，以正道相浸润，则悦而有益。',
    yaos: [
      { text: '和兑，吉。', xiang: '和兑之吉，行未疑也。', meaning: '初九阳居下位，「和兑」是以和气待人、不求阿谀。「行未疑也」是其行为光明正大、无可疑虑。这是说：以正道和气待人，不谄不阿，自然得吉。与人相处要刚正和气，不卑不亢。' },
      { text: '孚兑，吉，悔亡。', xiang: '孚兑之吉，信志也。', meaning: '九二刚中，「孚兑」是以诚信待人而悦。「信志也」是其心志诚信。这是说：以诚信相待、彼此信任，方能真悦而悔亡。人际交往贵在真诚，唯有信实，喜悦方能长久。' },
      { text: '来兑，凶。', xiang: '来兑之凶，位不当也。', meaning: '六三不中不正，「来兑」是主动前来求悦于人——阿谀奉承、讨好取悦。「位不当也」点明其位不正。这是说：不择手段去取悦他人，必招凶险。真正的喜悦不靠讨好换来，而要靠正道相得。' },
      { text: '商兑未宁，介疾有喜。', xiang: '九四之喜，有庆也。', meaning: '九四阳居阴位，「商兑未宁」是商议未定、心中未安。「介疾有喜」是因有刚介之节，去其疾害而得喜。「有庆也」点明其有喜庆。这是说：面对诱惑犹豫时，能坚守刚介之节，去除不正之悦，终有喜庆。' },
      { text: '孚于剥，有厉。', xiang: '孚于剥，位正当也。', meaning: '九五居尊，「孚于剥」是信任那消剥君子的小人——「剥」指上六之阴。虽位正当，却「有厉」——有危险。这是说：纵然居高位，若信小人而远君子，必有危厉。提醒我们：用人交友要明辨，切莫误信小人。' },
      { text: '引兑。', xiang: '上六引兑，未光也。', meaning: '上六居兑之极，「引兑」是引诱他人来悦己——以声色货利诱惑人。「未光也」是其道不光、阴暗不明。这是说：以引诱取悦于人，其道阴暗，终非正途。真正的喜悦不靠引诱，要光明正大。' },
    ]
  },
  { no: 59, name: '涣',   full: '风水涣',   upper: '巽', lower: '坎', gong: '离', shi: 5, tuan: '亨。王假有庙，利涉大川，利贞。', xiang: '风行水上，涣；先王以享于帝立庙。', read: '涣散待聚，宜萃神聚心，涣释其患。',
    meaning: '涣卦讲的是涣散与聚神之道。风行水上，水波涣散，故象传「享于帝立庙」——以祭祀凝聚人心。卦辞「王假有庙，利涉大川」——王者至庙祭祀以聚民心，可济大险。这启示我们：当事物涣散之时，要找到凝聚的核心（如信仰、目标），方能聚散为整、共克时艰。',
    gaoTuan: '涣者，散也。风行水上，涣然而散之象。然涣非徒散也，乃散其患难而聚其精神。卦辞曰「王假有庙，利涉大川」，盖王者以庙祀聚人心，则涣者复聚，可以济大险矣。君子观此象，知涣散之际，当以诚敬感神，以立庙聚民。',
    yaos: [
      { text: '用拯马壮，吉。', xiang: '初六之吉，顺也。', meaning: '初六居涣之始，「用拯马壮」是借助壮马之力以拯救涣散。「顺也」点明其顺承九二、得救故吉。这是说：涣散初起，要及时借助强大助力（如贤者、组织）来挽救，顺势而行则吉。' },
      { text: '涣奔其机，悔亡。', xiang: '涣奔其机，得愿也。', meaning: '九二阳居阴位，「涣奔其机」是涣散之时奔到几案（安身之所）旁——找到依靠。「得愿也」是得其安身之愿。这是说：危乱之时要迅速找到稳固的依靠和根据地，方能悔亡。危机中要果断选择安身之处。' },
      { text: '涣其躬，无悔。', xiang: '涣其躬，志在外也。', meaning: '六三阴居阳位，「涣其躬」是涣散自身（无私奉献自身）。「志在外也」是其志在济世外之患。这是说：能舍弃自身之私以济涣散之患，便无可悔。危难之时，能舍己为人，方显大义。' },
      { text: '涣其群，元吉。涣有丘，匪夷所思。', xiang: '涣其群元吉，光大也。', meaning: '六四柔正，「涣其群」是涣散小集团之私党——破除党争。「涣有丘」是涣散之后聚成山丘般的大众。「匪夷所思」是超出常人所想。「光大也」点明其道光明广大。这是说：破除小团体私利，凝聚天下大公，乃大吉之道。' },
      { text: '涣汗其大号，涣王居，无咎。', xiang: '王居无咎，正位也。', meaning: '九五居尊，「涣汗其大号」是汗出如水不可复收——号令既出不可收回；「涣王居」是散发王者之居积以济民。「正位也」点明其以正位行正事。这是说：王者发号施令要慎重如出汗不可复返，并散财济民，方能无咎。' },
      { text: '涣其血，去逖出，无咎。', xiang: '涣其血，远害也。', meaning: '上九居涣之极，「涣其血」是涣散其伤害（血=伤害），「去逖出」是远离而出。「远害也」点明其远离祸害。这是说：涣散之极，能远离伤害、全身而退，便无咎。危乱之极，要懂得抽身远害，保全自身。' },
    ]
  },
  { no: 60, name: '节',   full: '水泽节',   upper: '坎', lower: '兑', gong: '坎', shi: 1, tuan: '亨。苦节不可贞。', xiang: '泽上有水，节；君子以制数度，议德行。', read: '节制有度，宜守节中正，过苦则失。',
    meaning: '节卦讲的是节制有度之道。泽上有水，水满则溢，须节制，故象传「制数度，议德行」——制定礼仪度数、评议德行。卦辞「亨，苦节不可贞」——适度节制则亨通，过苦之节不可常守。这启示我们：节制要有度，过紧则苦、过松则纵，唯有中节方能长久亨通。',
    gaoTuan: '节者，止也，制也。泽上有水，水盛则溢，节之象也。卦辞曰「亨，苦节不可贞」，盖节以中为贵，节而得中则亨；过苦之节，不可长守，故不可贞。君子观此象，知凡事之节，当制其数度，议其德行，得中而止。',
    yaos: [
      { text: '不出户庭，无咎。', xiang: '不出户庭，知通塞也。', meaning: '初九阳居最下，「不出户庭」是不迈出内院之门。「知通塞也」是能知通塞之时——此时宜塞不宜通。这是说：节制之初，时机未到，要安居室内、不轻出，知进退之机便无咎。时机未至时，宜静守不出。' },
      { text: '不出门庭，凶。', xiang: '不出门庭凶，失时极也。', meaning: '九二阳居阴位，「不出门庭」是不迈出大门——本该出去却仍闭门不出。「失时极也」是错失时机到了极点。这是说：当时机已至该行动时，却因过度节制而闭门不出，必招凶险。节制要因时而变，不可一味固守。' },
      { text: '不节若，则嗟若，无咎。', xiang: '不节之嗟，又谁咎也。', meaning: '六三不中不正，「不节若」是不知节制，「则嗟若」是事后嗟叹不已。「又谁咎也」是又能怪谁呢——自取其咎。但因其能嗟叹反省，故「无咎」。这是说：不知节制而招致后悔，能自省嗟叹，便有改过之机。' },
      { text: '安节，亨。', xiang: '安节之亨，承上道也。', meaning: '六四柔正，「安节」是安于节制、自然而节。「承上道也」是承顺君上之道。这是说：能安然守节、顺承正道，便亨通。节制成为习惯、自然安行，便是节制之美的境界。' },
      { text: '甘节，吉，往有尚。', xiang: '甘节之吉，居位中也。', meaning: '九五中正居尊，「甘节」是节制得恰到好处，甘美而中节。「往有尚」是前往必受嘉尚。「居位中也」点明其以中道节之。这是说：节制得中、恰到好处，如饮食甘美，故吉而有所往。节制之美，在于中道。' },
      { text: '苦节，贞凶，悔亡。', xiang: '苦节贞凶，其道穷也。', meaning: '上六居节之极，「苦节」是节制过苦、令人不堪。「贞凶」是固守此苦节则凶。「其道穷也」是其道已穷。但「悔亡」——若能悔改则无悔。这是说：节制过苦、令人难以忍受，固守必凶；能及时悔改，方能无悔。' },
    ]
  },
  { no: 61, name: '中孚', full: '风泽中孚', upper: '巽', lower: '兑', gong: '艮', shi: 4, tuan: '豚鱼吉，利涉大川，利贞。', xiang: '泽上有风，中孚；君子以议狱缓死。', read: '诚信在中，宜以诚感人，涉险无虞。',
    meaning: '中孚卦讲的是诚信感通之道。卦形上下两阳、中虚如虚心，内含孚信，故象传「议狱缓死」——以诚信之心审慎刑狱、缓于死刑。卦辞「豚鱼吉，利涉大川」——连豚鱼这般微物也被诚信所感，则可济大险。这启示我们：诚信之至，可感通微物、可济大险，是立身成事的根本。',
    gaoTuan: '中孚者，信发于中也。上下皆实，中虚以受，孚信之象。卦辞曰「豚鱼吉，利涉大川」，盖孚信之至，虽豚鱼无知之物，亦被其感，则险无不可济矣。君子观此象，知诚信之道，可以感神明、通微物，故以之议狱缓死，存其恻怛。',
    yaos: [
      { text: '虞吉，有它不燕。', xiang: '初九虞吉，志未变也。', meaning: '初九阳居最下，「虞吉」是安守诚信则吉，「有它不燕」是若有二心杂念则不得安宁。「志未变也」是心志专一未变。这是说：诚信之初要专一不二，安守初衷则吉；若心存杂念，便不得安。诚信贵在专一。' },
      { text: '鸣鹤在阴，其子和之；我有好爵，吾与尔靡之。', xiang: '其子和之，中心愿也。', meaning: '九二刚中居下，「鸣鹤在阴，其子和之」是鹤在荫中鸣叫，小鹤应和——诚信相感，虽远必应。「我有好爵，吾与尔靡之」是我有美酒佳肴，愿与你共享。「中心愿也」是发自内心之愿。这是说：诚信相感，同类必应；有德有禄，乐与人共享。' },
      { text: '得敌，或鼓或罢，或泣或歌。', xiang: '或鼓或罢，位不当也。', meaning: '六三不中不正，「得敌」是遇到对手——心有所系，神魂颠倒。「或鼓或罢，或泣或歌」是或击鼓或罢休，或哭泣或歌唱——情绪反复无常。「位不当也」点明其位不正。这是说：诚信失中，被外物所牵，情绪反复、喜怒无常。' },
      { text: '月几望，马匹亡，无咎。', xiang: '马匹亡，绝类上也。', meaning: '六四柔正，「月几望」是月近圆满。「马匹亡」是舍弃匹偶（同类之私）而上从九五。「绝类上也」是断绝同类之私以从上。这是说：诚信之极，能舍去私党之私，专心上从正道，便无咎。诚信要舍私从公。' },
      { text: '有孚挛如，无咎。', xiang: '有孚挛如，位正当也。', meaning: '九五中正居尊，「有孚挛如」是以诚信系结天下之心如挛结不散。「位正当也」点明其位正而德当。这是说：居尊位者以诚信感结天下，万众归心，便无咎。领导天下要以诚信为本。' },
      { text: '翰音登于天，贞凶。', xiang: '翰音登于天，何可长也。', meaning: '上九居中孚之极，「翰音登于天」是鸡鸣之声上达于天——声闻过高、名实不符。「何可长也」是不可长久。这是说：诚信失实、徒有虚名，虽一时声闻达天，终不可长久而凶。诚信贵在真实，不可虚张声名。' },
    ]
  },
  { no: 62, name: '小过', full: '雷山小过', upper: '震', lower: '艮', gong: '兑', shi: 4, tuan: '亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。', xiang: '山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。', read: '小者过越，宜谨小慎微，不宜大事。',
    meaning: '小过卦讲的是小有过越之道。卦形中间两阳、上下四阴，如飞鸟舒翼，故卦辞以「飞鸟遗之音」为喻。「可小事，不可大事」「不宜上宜下」——只宜小有所过、宜下不宜上。象传「行过乎恭，丧过乎哀，用过乎俭」——在恭、哀、俭上略有过分是可以的。这启示我们：凡事宁可稍过谦恭节俭，不可张狂僭越；小事可为之，大事须慎重。',
    gaoTuan: '小过者，小者过也。山上有雷，雷过山上，小过之象。卦辞曰「可小事，不可大事，不宜上宜下」，盖谓小有所过则可，大有所僭则凶。君子观此象，知行宜过于恭，丧宜过于哀，用宜过于俭，皆小过之美者也。',
    yaos: [
      { text: '飞鸟以凶。', xiang: '飞鸟以凶，不可如何也。', meaning: '初六柔居最下，「飞鸟以凶」是飞鸟向上高飞则凶——本应居下却妄求高飞。「不可如何也」是无可奈何、必凶。这是说：自身弱小却好高骛远、向上冒进，必招凶险。力小任重、志大才疏，最是危险。' },
      { text: '过其祖，遇其妣；不及其君，遇其臣，无咎。', xiang: '不及其君，臣不可过也。', meaning: '六二柔中，「过其祖，遇其妣」是越过祖父而遇到祖母（阳不得而遇阴）——宜就阴柔。「不及其君，遇其臣」是不及君位而遇臣——宜守臣分。「臣不可过也」点明臣不可越君。这是说：小过之时，宜就柔下、守本分，不可僭越，便无咎。' },
      { text: '弗过防之，从或戕之，凶。', xiang: '从或戕之，凶如何也。', meaning: '九三过刚，「弗过防之」是未能过分防备，「从或戕之」是放纵他人则可能反被其害。「凶如何也」是凶之极。这是说：小过之时却过于刚愎、疏于防备，纵容小人，反受其害，凶不可言。提醒我们：不可因小过而大意，更要防微杜渐。' },
      { text: '无咎，弗过遇之。往厉必戒，勿用永贞。', xiang: '弗过遇之，位不当也。往厉必戒，终不可长也。', meaning: '九四阳居阴位，「弗过遇之」是不过分而恰遇之——宜就下柔。「往厉必戒」是前往有危必当戒备。「勿用永贞」是不可固守一途。「终不可长也」是不可长久。这是说：小过之时，宜柔下守戒、不可固执，方无咎而能应变。' },
      { text: '密云不雨，自我西郊，公弋取彼在穴。', xiang: '密云不雨，已上也。', meaning: '六五柔居尊位，「密云不雨，自我西郊」是阴云密布却不下雨——恩泽未下施。「公弋取彼在穴」是公侯用绳箭射取穴中之物——宜求之于下。「已上也」是阴已上盛。这是说：居高位而恩泽未施，宜谦下求贤于野穴之中。' },
      { text: '弗遇过之，飞鸟离之，凶，是谓灾眚。', xiang: '弗遇过之，已亢也。', meaning: '上六居小过之极，「弗遇过之」是无所遇而一味过越。「飞鸟离之」是飞鸟遭遇罗网（离=罹）。「已亢也」是已亢极。这是说：过越至极、不知止足，必如飞鸟入网，遭灾眚之凶。过而有度，过极必灾。' },
    ]
  },
  { no: 63, name: '既济', full: '水火既济', upper: '坎', lower: '离', gong: '坎', shi: 3, tuan: '亨，小利贞，初吉终乱。', xiang: '水在火上，既济；君子以思患而豫防之。', read: '事已成济，宜思患豫防，守成防变。',
    meaning: '既济卦讲的是事已成济、守成防变之道。水在火上，水火相济为用，事已成就之象。但卦辞「初吉终乱」直言：开始虽吉、终则必乱。象传「思患而豫防之」——要思虑后患而预先防备。这启示我们：成功之后最易懈怠，要居安思危、防微杜渐，方能守成而不败。',
    gaoTuan: '既济者，事之既成也。水在火上，水火相交为用，既济之象。然卦辞曰「初吉终乱」，盖事成之后，人易怠忽，怠则患生，故终必乱。君子观此象，知既济之时，尤当思患豫防，不可以成而忘戒。',
    yaos: [
      { text: '曳其轮，濡其尾，无咎。', xiang: '曳其轮，义无咎也。', meaning: '初九阳居最下，「曳其轮」是向后拖住车轮——节制前进。「濡其尾」是狐渡水湿了尾巴——谨慎不躁进。「义无咎也」是理当无咎。这是说：成功之初要节制前进、谨慎从事，不可因得意而冒进。' },
      { text: '妇丧其茀，勿逐，七日得。', xiang: '七日得，以中道也。', meaning: '六二柔中，「妇丧其茀」是妇人丢失了车蔽（首饰车饰）——有所遗失。「勿逐，七日得」是不必追逐，七日自得。「以中道也」是因其守中道。这是说：守成之时有所失，不必焦虑强求，守正中道，终会复得。' },
      { text: '高宗伐鬼方，三年克之，小人勿用。', xiang: '三年克之，惫也。', meaning: '九三过刚，「高宗伐鬼方，三年克之」是殷高宗讨伐鬼方，三年才胜——大事须久。「小人勿用」是不可用小人。「惫也」是疲惫。这是说：成事之后，平定残余顽敌须持久用力，且不可任用小人，方能竟全功。' },
      { text: '繻有衣袽，终日戒。', xiang: '终日戒，有所疑也。', meaning: '六四柔正，「繻有衣袽」是华服中备有破旧衣——备患之物。「终日戒」是整日戒备。「有所疑也」是心存疑虑警惕。这是说：成功之时要常备不时之需，整日戒备，防患于未然。居安思危，方能守成。' },
      { text: '东邻杀牛，不如西邻之禴祭，实受其福。', xiang: '东邻杀牛，不如西邻之时也。实受其福，吉大来也。', meaning: '九五中正居尊，「东邻杀牛」是殷商（东邻）杀牛大祭却失时，「不如西邻之禴祭」——不如西周（西邻）的简约禴祭合时。「实受其福」是实受其福。「吉大来也」是大吉来临。这是说：祭祀贵在合时与诚敬，而非祭品丰盛；守成贵在适时与诚信。' },
      { text: '濡其首，厉。', xiang: '濡其首厉，何可久也。', meaning: '上六居既济之极，「濡其首」是狐渡水湿了头——过涉没顶之危。「何可久也」是危不可久。这是说：成功之后若不知止、冒进深险，必致没顶之危。提醒我们：守成不可贪得无厌、不知止足。' },
    ]
  },
  { no: 64, name: '未济', full: '火水未济', upper: '离', lower: '坎', gong: '离', shi: 3, tuan: '亨，小狐汔济，濡其尾，无攸利。', xiang: '火在水上，未济；君子以慎辨物居方。', read: '事未竟成，宜慎终如始，蓄力待济。',
    meaning: '未济卦讲的是事未竟成、蓄力待济之道。火在水上，水火不交，事未成就之象。卦辞「小狐汔济，濡其尾，无攸利」——小狐将渡却湿尾，半途而废则无所利。象传「慎辨物居方」——慎辨万物、各安其位。这启示我们：事未成之时，要谨慎审时、量力而行、蓄势待发，方能终济大业。',
    gaoTuan: '未济者，事之未成也。火在水上，水火不交，未济之象。然六爻皆得正位，盖未济之中，含既济之机。卦辞曰「小狐汔济，濡其尾，无攸利」，戒其不能慎终如始也。君子观此象，知未济之时，当慎辨物居方，蓄力以待其济。',
    yaos: [
      { text: '濡其尾，吝。', xiang: '濡其尾，亦不知极也。', meaning: '初六柔居最下，「濡其尾」是小狐渡水湿了尾巴——力弱不能胜任。「亦不知极也」是不知深浅极限。这是说：未济之初，自身力弱却不知深浅冒进，必致吝难。要量力而行，不可贸然涉险。' },
      { text: '曳其轮，贞吉。', xiang: '九二贞吉，中以行正也。', meaning: '九二刚中，「曳其轮」是向后拖住车轮——节制前进。「贞吉」是守正则吉。「中以行正也」是以中道行正。这是说：未济之时要节制前进、守中行正，不躁进，方能得吉。' },
      { text: '未济，征凶，利涉大川。', xiang: '未济征凶，位不当也。', meaning: '六三不中不正，「未济征凶」是未济之时冒进则凶。「利涉大川」是宜借险以济（看似矛盾，实指须借势而行）。「位不当也」点明其位不正。这是说：自身不正而贸然前进必凶，但若能借大势渡险，反可成事。' },
      { text: '贞吉，悔亡，震用伐鬼方，三年有赏于大国。', xiang: '贞吉悔亡，志行也。', meaning: '九四阳居阴位，「贞吉悔亡」是守正则吉悔亡。「震用伐鬼方，三年有赏于大国」是以威震讨伐鬼方，三年功成受大国之赏。「志行也」是其志得行。这是说：未济之时，以刚武守正、持久用力，终能成事而受赏。' },
      { text: '贞吉，无悔，君子之光，有孚，吉。', xiang: '君子之光，其晖吉也。', meaning: '六五柔中居尊，「贞吉无悔」是守正则吉无悔。「君子之光，有孚」是君子之德光辉、孚信于人。「其晖吉也」是其光辉吉。这是说：未济将济之时，以柔中之德、孚信之光感召天下，终能大吉。' },
      { text: '有孚于饮酒，无咎，濡其首，有孚失是。', xiang: '饮酒濡首，亦不知节也。', meaning: '上九居未济之极，「有孚于饮酒，无咎」是诚信于饮酒安养则无咎——事已成可稍享。「濡其首，有孚失是」是若饮酒过度至濡首，则孚信失正。「亦不知节也」是不知节制。这是说：事将成时可稍享安乐，但不可纵乐失节，否则前功尽弃。' },
    ]
  }
];

const GAO_YAO_DATA = {
  '乾': [
    '初九潜龙勿用者，阳德初潜，未可施用也。此爻居最下位，如龙之潜伏深渊，阳气未盛，时机未到。占者宜藏器待时，不可轻举妄动，急则有失，静则无咎。待时而动，方为智者。',
    '九二见龙在田，利见大人者，阳德渐显，已出潜离隐，见于地上。此爻得中得正，德施普于天下，万物皆蒙其泽。占者宜进德修业，广结善缘，易得贵人相助，名利双收。然须持正不阿，方保长久。',
    '九三君子终日乾乾，夕惕若厉，无咎者，居下卦之上，危地也。刚而得正，上不在天，下不在田，故终日勤勉，夕犹惕厉，如临深渊。占者宜兢兢业业，朝乾夕惕，虽处危地，亦可无咎。慎终如始，则无败事。',
    '九四或跃在渊，无咎者，阳德已盛，进退自如也。此爻近九五之尊，欲进未进，欲跃未跃，或跃或在渊，审时度势。占者宜相机而动，可进则进，可止则止，进退有据，方得无咎。切忌冒进，亦勿坐失良机。',
    '九五飞龙在天，利见大人者，阳德极盛，居天位之中正。龙飞九天，云从风随，万物瞻仰。此乃全卦最吉之爻，得位得中得正。占者功名显达，事业鼎盛，贵人扶持，万事如意。然须戒骄戒躁，居安思危，方保长久。',
    '上九亢龙有悔者，阳之极也，物极必反。龙飞过高，超越本分，进而不已，终致悔恨。盈不可久，盛极必衰，此天地之常理也。占者宜知进退存亡，不可贪得无厌，功成身退，方为上策。知止不殆，可以长久。'
  ],
  '坤': [
    '初六履霜，坚冰至者，阴之始凝也。履霜而知寒之将至，见微而知著，防患于未然。此爻居坤之始，阴气方萌，其势虽微，渐长则盛。占者宜慎之于始，防微杜渐，勿以恶小而为之，勿以善小而不为。积善之家，必有余庆。',
    '六二直方大，不习无不利者，坤道之至美也。直则无私，方则有守，大则能容，三者兼备，地道光显。此爻得中得正，柔顺之德，自然而然。占者宜守正不阿，胸怀广阔，不待学习而自无不利。厚德载物，无往不吉。',
    '六三含章可贞，或从王事，无成有终者，内含章美，不形于外也。阴居阳位，才美不外露，含藏不显，守正待时。或从王事，辅君成业，功成不居，终有好报。占者宜谦逊自守，不可炫耀才华，功成弗居，方保终吉。',
    '六四括囊，无咎无誉者，谨慎之至也。居上下之交，处多惧之地，如囊之收口，谨言慎行，不妄言，不妄动。无咎无誉，言既无过恶，亦无令名。占者宜明哲保身，缄默自守，不炫才，不招怨，庶几可以全身远害。',
    '六五黄裳元吉者，坤德之极致也。黄为中色，裳为下饰，居尊位而能谦下，以柔顺之德而居尊。此爻得中，文在其中，不言而信，不怒而威。占者宜谦和下人，以柔克刚，虽居高位而能守礼，大吉大利。',
    '上六龙战于野，其血玄黄者，阴之极也。阴极则与阳争，两败俱伤。玄为天色，黄为地色，天地俱伤，凶可知矣。占者宜知进退，不可刚愎自用，以柔克刚才是正道。若争强好胜，必致灾祸。退一步海阔天空。'
  ],
  '屯': [
    '初九磐桓，利居贞，利建侯者，屯难之初，未可轻进也。磐桓，徘徊不进之貌，阳刚居下，有济世之才，然当屯难之始，未可妄动。利居贞者，宜守正待时；利建侯者，宜建立根基，广结人心。占者宜安守本分，积蓄力量，待机而动。',
    '六二屯如邅如，乘马班如，匪寇婚媾，女子贞不字，十年乃字者，处屯难之中，进退两难也。阴柔居下，为初九所乘，徘徊不前，如骑马盘旋。然其志在五，非为寇而来，实为婚媾。女子守贞不字，十年乃字，言其坚贞久持，终得所愿。占者宜坚守初心，不急不躁。',
    '六三即鹿无虞，惟入于林中，君子几不如舍，往吝者，盲目妄动之戒也。阴柔不中，妄动求进，如逐鹿而无向导，必陷于林中。君子见几而作，不如舍去，往则有吝。占者宜量力而行，不可强求，无向导则勿入险地。知难而退，方为明智。',
    '六四乘马班如，求婚媾，往吉，无不利者，柔而得正，下求于初也。居近君之位，有济屯之志，然才不足以自济，故徘徊思虑，求阳刚之助。求婚媾而往，求贤以自辅，往则吉而无不利。占者宜主动求贤，借力成事，明主求贤臣，相得益彰。',
    '九五屯其膏，小贞吉，大贞凶者，处屯难之中，恩泽难以下广也。阳刚中正，居尊位，然陷于坎险之中，膏泽屯积而不能普施。小贞吉者，小事守正则吉；大贞凶者，大事守正则凶。占者宜量力而行，先从小事做起，不可好大喜功。',
    '上六乘马班如，泣血涟如者，屯难之极，无所依归也。阴柔居上，处屯之终，进无所之，退无所据，骑马徘徊，悲泣至于流血。然物极必反，屯极则通，何可长也。占者虽处困境，不可绝望，坚持到底，终有转机。否极泰来，此之谓也。'
  ],
  '蒙': [
    '初六发蒙，利用刑人，用说桎梏，以往吝者，蒙之始也。蒙昧初开，宜立规矩，用刑人以正法，使人知所忌惮，脱去桎梏之愚。然过刚则损，往而不已则有吝。占者启蒙之初，宜严立规矩，恩威并施，不可一味纵容，亦不可过严。中道而行，方为善教。',
    '九二包蒙吉，纳妇吉，子克家者，包养群蒙也。阳刚得中，能包容蒙昧之人，因材施教，有教无类。纳妇吉者，阴阳相合，刚柔相济；子克家者，弟子能承家业。占者宜以宽容之心待人，不可求全责备，海纳百川，有容乃大。宽严相济，方能有成。',
    '六三勿用取女，见金夫，不有躬，无攸利者，蒙昧失正也。阴柔不中，见利忘义，见金夫而失身，不顾廉耻。勿用取女者，言不可娶此等女子。占者宜守正不阿，不为外物所动，见利思义，不可见异思迁。操守二字，最为紧要。',
    '六四困蒙，吝者，困于蒙昧也。阴柔失正，远于阳刚，独学无友，孤陋寡闻。困于蒙昧之中，不能自进，故吝。占者宜亲近良师益友，虚心求教，不可闭门造车。独学而无友，则孤陋而寡闻。虚心使人进步。',
    '六五童蒙吉者，纯真之蒙也。柔顺居尊，如童子之纯真，虚心求教，不耻下问。童蒙之吉，在于顺以巽也。占者宜保持赤子之心，谦虚好学，不耻下问，虽居高位而能下问。知之为知之，不知为不知，是知也。',
    '上九击蒙，不利为寇，利御寇者，蒙之极也。阳刚居上，以刚猛击蒙，然不可过刚。不利为寇者，不可主动攻击；利御寇者，可以防御外患。占者教育他人，不可过猛，宜宽猛相济。击蒙之道，在于御寇，不在于为寇。过刚则折，宜慎之。'
  ],
  '需': [
    '初九需于郊，利用恒，无咎者，需之始也。远离坎险，需于郊外旷野之地，从容不迫，不犯难行。利用恒者，宜持之以恒，守正不动。占者宜远离是非，保持平常心，不急不躁，持之以恒，自然无咎。凡事留有余地，方是上策。',
    '九二需于沙，小有言，终吉者，渐近于险也。需于沙滩之地，近于水矣，故小有言语之伤。然宽裕得中，不与相争，虽有小言，终得吉庆。占者虽遭非议，宜泰然处之，不与人争口舌之利。清者自清，浊者自浊，时间自会证明一切。',
    '九三需于泥，致寇至者，近于险也。需于泥泞之地，逼近坎险，灾祸将至。自我致寇，敬慎不败也。占者处此境地，宜加倍小心，敬慎戒备，不可大意。越接近成功，越要警惕。小心驶得万年船，敬慎则虽危不败。',
    '六四需于血，出自穴者，入于险也。已在坎险之中，需于流血之地，情势危急。然柔顺得正，能顺以听命，出自穴而得免。占者身陷困境，不可强争，宜顺时应变，柔以克刚。留得青山在，不怕没柴烧。能屈能伸，方为丈夫。',
    '九五需于酒食，贞吉者，需之至也。阳刚中正，居尊位，饮食宴乐，安享太平。需道既成，不劳而获，守正则吉。占者宜安享其成，然不可耽于安乐，仍需居安思危。生于忧患，死于安乐。酒食虽美，不可忘形。',
    '上六入于穴，有不速之客三人来，敬之终吉者，需之极也。退入穴中，静以待之。有不速之客三人来访，出乎意外。然敬而待之，终得吉祥。占者遇事变，宜以礼相待，不可轻慢。敬人者人恒敬之，礼貌周到，终必有福。以敬应变，无往不利。'
  ],
  '讼': [
    '初六不永所事，小有言，终吉者，讼之始也。柔弱居下，不能持久争讼，虽有小言语之伤，然能及早收手，终得吉祥。讼不可长，长则凶。占者遇争执，宜适可而止，不可得理不饶人。得饶人处且饶人，冤家宜解不宜结。',
    '九二不克讼，归而逋，其邑人三百户无眚者，讼而不胜也。阳刚居下，与九五争讼，力不能敌，故败而归窜。然能知难而退，故其邑人三百户皆得无灾。占者遇强争，宜知进退，不可以卵击石。退一步海阔天空，保全自身方为上策。',
    '六三食旧德，贞厉终吉，或从王事无成者，依凭旧德也。阴柔居下，依凭祖上旧德，安分守己。贞厉者，守正防危；终吉者，终得吉祥。或从王事，功成不居，无成有终。占者宜知足常乐，守己安分，不可贪求无厌。承祖德者，宜守成。',
    '九四不克讼，复即命渝，安贞吉者，讼而能改也。阳刚失位，争讼不胜，然能反思改过，复归于正理，改变初衷。安贞吉者，安于守正则吉。占者若争讼失利，宜及时反省，改弦易辙，回归正道。知错能改，善莫大焉。',
    '九五讼，元吉者，讼之主也。阳刚中正，居尊位，听讼明断，秉公执法。讼而得元吉者，以其中正也。占者遇争讼，得贵人明断，自有公道。若为裁决者，宜公正无私，不偏不倚。公生明，廉生威。中正明断，乃讼之吉。',
    '上九或锡之鞶带，终朝三褫之者，讼之极也。以刚居上，争讼得胜，或得赏赐。然以讼受服，亦不足敬，一日之间，三夺三赐，荣宠不终。占者不可靠争讼获利，纵使一时得胜，终难长久。以力服人者，非心服也。讼终凶，宜戒之。'
  ],
  '师': [
    '初六师出以律，否臧凶者，师之始也。兴师动众，必以纪律为先。纪律严明，则胜；纪律废弛，则败。否臧，不善也，纪律不善则凶。占者凡事宜有规矩，有法度，不可散漫无纪。没有规矩不成方圆。纪律是成功的保障。',
    '九二在师中，吉无咎，王三锡命者，师之主也。阳刚得中，为众阴所宗，统帅之象。在师中而吉，以刚中也。王三锡命者，君王多次嘉奖，恩宠有加。占者宜刚柔相济，恩威并施，深得人心，则能成就大业。得人心者得天下。',
    '六三师或舆尸，凶者，用师之失也。阴柔失正，才微任重，指挥不当，士卒死伤惨重，载尸而归。舆尸之凶，大无功也。占者宜慎选人才，不可任人唯亲。用人不当，必败无疑。千军易得，一将难求。',
    '六四师左次，无咎者，知难而退也。阴柔得正，见势不利，退守驻扎，不冒险进攻。左次，退舍也。知难而退，不失其正，故无咎。占者宜审时度势，打得赢就打，打不赢就走。撤退不是失败，保全实力才能再战。',
    '六五田有禽，利执言，长子帅师，弟子舆尸，贞凶者，用将之失也。阴柔居尊，不能专任大将。田有禽者，有敌来犯，利于出师声讨。长子帅师，以中行也；弟子舆尸，使不当也。长子指九二，弟子指六三。任将不一，故凶。占者用人宜专一，不可多门。',
    '上六大君有命，开国承家，小人勿用者，师之终也。战争胜利，论功行赏。大君颁布命令，开国封疆，承家立邑。然小人虽有功，亦不可重用。小人勿用，必乱邦也。占者功成之后，宜亲君子，远小人。打天下可用群雄，治天下必用君子。'
  ],
  '比': [
    '初六有孚比之，无咎。有孚盈缶，终来有他吉者，比之始也。心怀诚信以相亲比，自然无咎。诚信充实，如满盆之水，实实在在，终有意外之吉。占者交友待人，贵乎真心诚意。精诚所至，金石为开。以心换心，方能长久。',
    '六二比之自内，贞吉者，比之得正也。柔顺得中，从内部亲比，不失自我。比之自内，不自失也。占者与人交往，宜自尊自爱，不卑不亢。依附他人，不可丧失原则。不失自我，方能赢得尊重。',
    '六三比之匪人，不亦伤乎者，所比非人也。阴柔不中，所亲比者皆非正道之人，近墨者黑。比之匪人，不亦伤乎。占者宜慎择友，近朱者赤，近墨者黑。与善人居，如入芝兰之室；与恶人居，如入鲍鱼之肆。',
    '六四外比之，贞吉者，外比于贤也。柔顺得正，外比于九五之贤，顺从上位，得其庇护。外比于贤，以从上也。占者宜亲附贤明之上司，择良木而栖。良禽择木而栖，贤臣择主而事。从善如登，从恶如崩。',
    '九五显比，王用三驱，失前禽，邑人不诫，吉者，比之主也。阳刚中正，居尊位，显明亲比之道。王用三驱，舍逆取顺，失前禽而不追，来者不拒，去者不追。显比之吉，位正中也。占者宜以德服人，不可强逼。自愿归附者，方为真心。',
    '上六比之无首，凶者，比之极也。阴柔居上，无所归附，群龙无首，不知所从。比之无首，无所终也。占者宜及早归附正道，不可犹豫不决。人无头不走，鸟无头不飞。找对领头人，跟对方向，方得善终。'
  ],
  '小畜': [
    '初九复自道，何其咎，吉者，畜之始也。阳刚居下，知进退，能返回正道。复自道，其义吉也。占者若发现行差踏错，宜及时回头，改过自新。知错能改，善莫大焉。回到正道，反而是吉。',
    '九二牵复吉者，相携而归也。阳刚得中，与初九相携而复于中道。牵复在中，亦不自失也。占者宜与志同道合者互相勉励，共同进步。一个人走得快，一群人走得远。互相提醒，不容易走偏。',
    '九三舆说辐，夫妻反目者，畜之不固也。阳刚不得位，力量不足，如车轮脱辐，不能行进。夫妻反目，不能正室也。占者宜先巩固根基，不可急于求成。基础不牢，地动山摇。家和万事兴，不和则败。',
    '六四有孚，血去惕出，无咎者，能以诚信化险为夷也。柔顺得正，居近君之位，心怀诚信，忧惧解除。有孚惕出，上合志也。占者处危疑之地，宜以诚待人，消除隔阂。诚信是最好的通行证。精诚所至，金石为开。',
    '九五有孚挛如，富以其邻者，畜之盛也。阳刚中正，居尊位，心怀诚信，与众人紧密相连。富以其邻者，不独富也，与邻里共享富贵。占者宜与人为善，有福同享。独乐乐不如众乐乐。大家好，才是真的好。',
    '上九既雨既处，尚德载，妇贞厉，月几望，君子征凶者，畜之极也。畜道已成，雨已下，物已润，德积满载。然不可过极，如月将圆，再进则亏。君子征凶，有所疑也。占者宜适可而止，不可贪得无厌。月盈则亏，水满则溢。知止不殆。'
  ],
  '履': [
    '初九素履往，无咎者，履之始也。朴素而行，不尚浮华，往而无咎。素履之往，独行愿也。占者宜保持本色，不忘初心，不追求虚荣。踏踏实实做人，认认真真做事。朴素方是真滋味。',
    '九二履道坦坦，幽人贞吉者，履于平易也。阳刚得中，行走在平坦大道上，幽居之人守正则吉。幽人贞吉，中不自乱也。占者宜保持内心平静，不因路好走而得意忘形。顺境中更需清醒，不骄不躁。平常心是道。',
    '六三眇能视，跛能履，履虎尾咥人凶，武人为于大君者，不自量力也。阴柔不中，才不足以任事，强行而为，如瞎子视物、跛子行走，终必败亡。履虎尾而被虎咬，凶可知矣。占者宜有自知之明，不可逞强好胜。量力而行，方为智者。',
    '九四履虎尾，愬愬终吉者，处危能惧也。阳刚失位，履于虎尾之上，处境危险。然恐惧警惕，不敢懈怠，终得吉祥。愬愬终吉，志行也。占者遇险境，宜加倍小心，如履薄冰，如临深渊。心存敬畏，方能化险为夷。',
    '九五夬履，贞厉者，刚决太过也。阳刚中正，居尊位，行事果决，然过于刚猛，易致危险。夬履贞厉，位正当也。占者虽有权势，宜刚柔相济，不可一意孤行。刚愎自用，必遭其祸。水能载舟，亦能覆舟。',
    '上九视履考祥，其旋元吉者，履之终也。回顾走过的路，考察吉凶祸福，返归于正道，大吉大利。元吉在上，大有庆也。占者宜时常反省自己，总结经验教训。吾日三省吾身。善始善终，方为圆满。'
  ],
  '泰': [
    '初九拔茅茹，以其汇，征吉者，泰之始也。拔茅连根，同类相从，阳刚方长，志在外也。占者宜团结一致，共同进取。人心齐，泰山移。众人拾柴火焰高。',
    '九二包荒，用冯河，不遐遗，朋亡，得尚于中行者，泰道之盛也。包容广大，能涉险川，不遗远方，不结党羽，以中道行事。包荒得尚于中行，以光大也。占者宜胸怀宽广，用人不疑。海纳百川，有容乃大。',
    '九三无平不陂，无往不复，艰贞无咎，勿恤其孚，于食有福者，泰将转否也。地平则坡，事极则反，天地之常理也。处泰之中，当思艰难，守正则无咎。勿忧其诚信不立，自享俸禄之福。占者宜居安思危，盛不忘衰。',
    '六四翩翩不富，以其邻，不戒以孚者，泰将极也。阴柔得位，翩翩然下降，不独富而与邻共享，不待戒备而互相信任。翩翩不富，皆失实也。占者宜顺应时势，与人和睦相处。独乐乐不如众乐乐。以诚相待，其乐融融。',
    '六五帝乙归妹，以祉元吉者，泰之美也。帝乙嫁妹，阴阳和合，上下相交，以此得福，大吉大利。以祉元吉，中以行愿也。占者宜阴阳调和，各得其所。家和万事兴。各安其位，各得其所，方为泰道。',
    '上六城复于隍，勿用师，自邑告命，贞吝者，泰极否来也。城墙倒塌，泰道已极，否运将至。勿用师者，不可用兵，用师必败。自邑告命者，从内部传来命令。占者宜接受变化，不可强挽狂澜。物极必反，泰极则否。顺应时势，方为智者。'
  ],
  '否': [
    '初六拔茅茹，以其汇，贞吉亨者，否之始也。拔茅连根，同类相惧，守正则吉，终得亨通。拔茅贞吉，志在君也。占者处否塞之初，宜守正待时，团结同志，静待转机。沉住气，莫乱动。守得云开见月明。',
    '六二包承，小人吉，大人否亨者，否之中也。阴柔得中，包藏承受，小人得志则吉，大人君子则闭塞不亨。大人否亨，不乱群也。占者若为君子，宜洁身自好，不同流合污。穷则独善其身，达则兼济天下。',
    '六三包羞者，否之甚也。阴柔不中，包藏羞耻，依附强者，不择手段。包羞，位不当也。占者宜知廉耻，不可为一己之私而不顾气节。人不可有傲气，但不可无傲骨。宁可站着死，不可跪着生。',
    '九四有命无咎，畴离祉者，否将转泰也。阳刚得位，承上启下，有天命在身，无有过咎。众人皆依附之，同享福泽。有命无咎，志行也。占者处否极之时，宜积极作为，扭转乾坤。天将降大任于斯人也。苦尽甘来，否极泰来。',
    '九五休否，大人吉。其亡其亡，系于苞桑者，否之主也。阳刚中正，居尊位，能休止否运，大人得吉。常存危惧之心，如系于苞桑之上，根深蒂固。休否之吉，位正当也。占者居安思危，常存戒惧之心。生于忧患，死于安乐。',
    '上九倾否，先否后喜者，否之终也。否运至极，终将倾覆，先否后喜，否极泰来。否终则倾，何可长也。占者虽处困境，不可丧失信心。物极必反，困极必通。坚持到底，就是胜利。'
  ],
  '同人': [
    '初九同人于门，无咎者，同人之始也。出门同人，广结善缘，无所偏私，故无咎。出门同人，又谁咎也。占者宜走出小我，广交天下朋友。一个篱笆三个桩，一个好汉三个帮。朋友多了路好走。',
    '六二同人于宗，吝者，同人之狭也。阴柔得中，仅与宗族同党相亲，心胸狭隘。同人于宗，吝道也。占者宜扩大胸襟，不可结党营私。海纳百川，有容乃大。大公无私，方能成大事。',
    '九三伏戎于莽，升其高陵，三岁不兴者，同人之争也。阳刚不得位，暗中伏兵，欲争九五之位。然力有不逮，潜伏三年，不敢妄动。伏戎于莽，敌刚也。占者不可妄动干戈，审时度势。知己知彼，百战不殆。',
    '九四乘其墉，弗克攻，吉者，知难而退也。阳刚失位，攻而不克，知难而退，故吉。乘其墉，义弗克也。其吉，则困而反则也。占者遇强故，宜知进退，攻不下则退。不战而屈人之兵，善之善者也。',
    '九五同人，先号咷而后笑，大师克相遇者，同人之主也。阳刚中正，居尊位，先悲后喜，大军克敌，同人相遇。同人之先，以中直也。大师相遇，言相克也。占者虽遇阻碍，终必成功。好事多磨。先苦后甜，方知珍贵。',
    '上九同人于郊，无悔者，同人之极也。同于郊野，远离人群，虽未大同，亦无悔恨。同人于郊，志未得也。占者若不得志，宜独善其身。达则兼济天下，穷则独善其身。曲高和寡，自古皆然。'
  ],
  '大有': [
    '初九无交害，匪咎，艰则无咎者，大有之始也。富有之始，不与人交恶，故无咎。然处富有之初，宜知艰难，不可骄奢。大有初九，无交害也。占者初得富贵，宜低调谨慎，不可张扬。财不露白，富不骄横。',
    '九二大车以载，有攸往，无咎者，大有之盛也。阳刚得中，有担当，能任重道远，如大车之载物，往而无咎。大车以载，积中不败也。占者宜担当重任，稳步前进。德才配位，方能承载。厚德载物。',
    '九三公用亨于天子，小人弗克者，大有之极也。阳刚得位，诸侯献纳于天子，共享太平。小人不能当此重任。公用亨于天子，小人害也。占者若居高位，宜为公不为私。先天下之忧而忧，后天下之乐而乐。',
    '九四匪其彭，无咎者，大有而能谦也。阳刚失位，处近君之地，虽有其盛，不敢自满。匪其彭，无咎，明辨皙也。占者宜谦逊自处，不可盛气凌人。谦虚使人进步，骄傲使人落后。满招损，谦受益。',
    '六五厥孚交如，威如，吉者，大有之主也。柔居尊位，以诚信待人，威严自显，吉祥如意。厥孚交如，信以发志也。威如之吉，易而无备也。占者宜以诚待人，不怒自威。桃李不言，下自成蹊。信则人任焉。',
    '上九天祐之，吉无不利者，大有之终也。居大有之极，能顺天应人，得天之祐，吉无不利。大有上吉，自天祐也。占者宜顺天而行，不可逆天行事。谋事在人，成事在天。尽人事，听天命。'
  ],
  '谦': [
    '初六谦谦君子，用涉大川，吉者，谦之始也。谦而又谦，君子之德，以此涉险，吉无不利。谦谦君子，卑以自牧也。占者宜谦虚谨慎，不骄不躁。低调做人，高调做事。虚心使人进步。',
    '六二鸣谦，贞吉者，谦之著也。阴柔得中，谦德外显，守正则吉。鸣谦贞吉，中心得也。占者宜内修谦德，自然闻名。酒香不怕巷子深。有实德者，自有令名。',
    '九三劳谦，君子有终吉者，谦之主也。阳刚得位，勤劳而谦虚，君子有始有终，终得吉祥。劳谦君子，万民服也。占者宜勤奋努力，又谦虚下人。劳而不伐，有功而不德。越有本事的人，越谦虚。',
    '六四无不利，撝谦者，谦之广也。阴柔得位，发挥谦德，无所不利。撝谦，不违则也。占者宜将谦虚之心推广开来，待人接物皆以谦。满招损，谦受益。谦虚是一种美德，也是一种智慧。',
    '六五不富以其邻，利用侵伐，无不利者，谦之盛也。柔居尊位，不独自富，与邻共享。以此用兵，无往不利。利用侵伐，征不服也。占者宜以谦德服人，不得已而用兵，亦无不利。仁者无敌。',
    '上六鸣谦，利用行师，征邑国者，谦之极也。谦德至极，闻名远近，可用兵征讨不服之国。鸣谦，志未得也。可用行师，征邑国也。占者虽有谦德，亦不可无威。恩威并施，方为上策。'
  ],
  '豫': [
    '初六鸣豫，凶者，豫之始也。处安乐之初，便洋洋得意，骄纵自满，必致凶险。初六鸣豫，志穷凶也。占者不可耽于享乐，宜居安思危。生于忧患，死于安乐。逸豫可以亡身。',
    '六二介于石，不终日，贞吉者，豫之守正也。阴柔得中，如石之坚，不为安乐所移，不终日而能返于正。不终日贞吉，以中正也。占者宜坚守正道，不随波逐流。众人皆醉我独醒。出淤泥而不染。',
    '六三盱豫悔，迟有悔者，豫之失也。阴柔不中，仰视上之颜色以求乐，迟则生悔。盱豫有悔，位不当也。占者宜独立自主，不可攀附权贵。靠山山倒，靠人人跑。靠人不如靠己。',
    '九四由豫，大有得，勿疑朋盍簪者，豫之主也。阳刚得位，为众阴所依附，由之而得安乐，大有所获。勿疑朋盍簪者，不疑则朋友聚合。由豫大有得，志大行也。占者宜光明磊落，不疑不忌。疑人不用，用人不疑。',
    '六五贞疾，恒不死者，处豫之危也。柔居尊位，沉溺于安乐，如得疾病，然恒久而不死。六五贞疾，乘刚也。恒不死，中未亡也。占者宜警醒，不可沉迷享乐。病从口入，祸从口出。节制享乐，方能长久。',
    '上六冥豫，成有渝，无咎者，豫之极也。昏暗于安乐，执迷不悟。然事成之后能改变，则无咎。冥豫在上，何可长也。占者若已沉溺，宜及时醒悟。苦海无边，回头是岸。放下屠刀，立地成佛。'
  ],
  '随': [
    '初九官有渝，贞吉，出门交有功者，随之始也。随顺之时，有所变化，守正则吉。出门与人交往，必有功绩。官有渝，从正吉也。出门交有功，不失也。占者宜随机应变，出门广结善缘。择其善者而从之。',
    '六二系小子，失丈夫者，随之失也。阴柔得中，系于初之小子，而失九五之丈夫。系小子，弗兼与也。占者宜有所抉择，不可贪小失大。鱼与熊掌，不可兼得。舍小取大，方为上策。',
    '六三系丈夫，失小子，随有求得，利居贞者，随之得也。阴柔不中，系于九四之丈夫，而失初九之小子。随有求而得，利于守正。系丈夫，志舍下也。占者宜追随贤能，从善如流。良禽择木而栖。',
    '九四随有获，贞凶，有孚在道，以明，何咎者，随之危也。阳刚失位，随人而有收获，守正防凶。心怀诚信，行于正道，光明磊落，又有何咎。随有获，其义凶也。有孚在道，明功也。占者宜守正不阿。',
    '九五孚于嘉，吉者，随之主也。阳刚中正，居尊位，以诚信待善人，吉祥如意。孚于嘉吉，位正中也。占者以诚待人，赏善罚恶。得道多助，失道寡助。',
    '上六拘系之，乃从维之，王用亨于西山者，随之极也。随顺至极，如被拘系，又从而维系之。诚之至也，可用于祭祀西山。拘系之，上穷也。占者宜始终如一，不变其志。从一而终，方为至诚。'
  ],
  '蛊': [
    '初六干父之蛊，有子，考无咎，厉终吉者，蛊之始也。整治父辈之弊，有子如此，父可无咎。虽危厉，终得吉祥。干父之蛊，意承考也。占者宜承先启后，革除旧弊。青出于蓝而胜于蓝。',
    '九二干母之蛊，不可贞者，治蛊之难也。阳刚得中，整治母辈之弊，不可过于刚直，宜委曲成全。干母之蛊，得中道也。占者宜刚柔相济，不可太刚。治家贵和，不贵刚。',
    '九三干父之蛊，小有悔，无大咎者，治蛊之过也。阳刚过刚，整治父弊，稍有过甚，故小有悔。然无大过咎。干父之蛊，终无咎也。占者宜把握分寸，不可太过。过犹不及。',
    '六四裕父之蛊，往见吝者，治蛊之缓也。阴柔得位，宽容姑息，不急于整治，往则有吝。裕父之蛊，往未得也。占者宜当断则断，不可姑息养奸。当断不断，反受其乱。',
    '六五干父之蛊，用誉者，治蛊之善也。柔居尊位，以柔克刚，整治父弊而得美誉。干父之蛊，承以德也。占者以德服人，不怒而威。以德报怨，方为大德。',
    '上九不事王侯，高尚其事者，蛊之极也。治蛊已毕，功成身退，不事王侯，高尚其志。不事王侯，志可则也。占者宜功成身退，不可贪恋权位。急流勇退，方为智者。'
  ],
  '临': [
    '初九咸临，贞吉者，临之始也。阳刚初长，感应于下，守正则吉。咸临贞吉，志行正也。占者宜以正感人，以德服人。其身正，不令而行。',
    '九二咸临，吉无不利者，临之盛也。阳刚得中，感应于下，吉祥而无所不利。咸临吉无不利，未顺命也。占者宜广施恩泽，深得人心。得民心者得天下。',
    '六三甘临，无攸利，既忧之，无咎者，临之失也。阴柔不中，以甜言蜜语临人，无所利处。然能忧惧改过，则无咎。甘临，位不当也。既忧之，咎不长也。占者宜真诚待人，不可口蜜腹剑。',
    '六四至临，无咎者，临之得也。阴柔得位，亲近于下，至诚相临，故无咎。至临无咎，位当也。占者宜深入群众，了解下情。知己知彼，百战不殆。',
    '六五大君之宜，吉者，临之主也。柔居尊位，行帝王之道，吉祥如意。大君之宜，行中之谓也。占者宜行中道，不偏不倚。治国以正，用兵以奇。',
    '上六敦临，吉无咎者，临之终也。敦厚以临下，吉祥无咎。敦临之吉，志在内也。占者宜厚道待人，不可刻薄。厚德载物，宽则得众。'
  ],
  '观': [
    '初六童观，小人无咎，君子吝者，观之始也。如童子之观，所见浅近。小人则无咎，君子则有憾。初六童观，小人道也。占者宜高瞻远瞩，不可目光短浅。井底之蛙，所见者小。',
    '六二窥观，利女贞者，观之狭也。如女子从门缝中窥视，所见不广。利女贞者，妇人之见也。窥观女贞，亦可丑也。占者宜开阔眼界，不可坐井观天。站得高，看得远。',
    '六三观我生，进退者，观之深也。观察自我之行止，审时度势，可进可退。观我生进退，未失道也。占者宜反躬自省，谨慎抉择。吾日三省吾身。',
    '六四观国之光，利用宾于王者，观之盛也。观国家之光华，宜于辅佐帝王。观国之光，尚宾也。占者宜出仕为官，辅佐明君。学成文武艺，货与帝王家。',
    '九五观我生，君子无咎者，观之主也。阳刚中正，居尊位，观察自我之德行，君子则无咎。观我生，观民也。占者宜以民为镜，察己得失。以人为镜，可以明得失。',
    '上九观其生，君子无咎者，观之极也。观察他人之行止，以己度人，君子则无咎。观其生，志未平也。占者宜见贤思齐，见不贤而内自省。三人行，必有我师焉。'
  ],
  '噬嗑': [
    '初九屦校灭趾，无咎者，噬嗑之始也。刑罚之始，加刑于足，灭其脚趾，小惩大诫，故无咎。屦校灭趾，不行也。占者宜知错就改，小过即改，不至大恶。千里之堤，溃于蚁穴。',
    '六二噬肤灭鼻，无咎者，噬嗑之易也。阴柔得中，执法宽松，如噬嫩肉，没其鼻子，轻易而举，无有过咎。噬肤灭鼻，乘刚也。占者宜刚柔相济，不可过严。治大国如烹小鲜。',
    '六三噬腊肉，遇毒，小吝无咎者，噬嗑之难也。阴柔不中，治狱遇阻，如噬干肉，遇有毒味，稍有艰难，终无大咎。遇毒，位不当也。占者宜有耐心，不可急于求成。欲速则不达。',
    '九四噬干胏，得金矢，利艰贞吉者，噬嗑之难也。阳刚得位，治狱艰难，如噬带骨干肉。得金矢者，刚直之象。利艰难守正，则吉。利艰贞吉，未光也。占者宜刚直不阿，不畏艰难。秉公执法，虽难必济。',
    '六五噬干肉，得黄金，贞厉无咎者，噬嗑之主也。柔居尊位，治狱得法，如噬干肉，得黄金之刚。守正防危，则无咎。贞厉无咎，得当也。占者宜明察秋毫，公正无私。明断是非，赏罚分明。',
    '上九何校灭耳，凶者，噬嗑之极也。刑之极者，加刑于首，灭其耳朵，执迷不悟，故凶。何校灭耳，聪不明也。占者宜听忠言，不可闭目塞听。良药苦口利于病，忠言逆耳利于行。'
  ],
  '贲': [
    '初九贲其趾，舍车而徒者，贲之始也。文饰其足，舍车而步行，不尚虚荣，安步当车。舍车而徒，义弗乘也。占者宜质朴自守，不慕虚荣。不义而富且贵，于我如浮云。',
    '六二贲其须者，贲之著也。文饰其须，依附于上，不能自主。贲其须，与上兴也。占者宜依附贤能，借助外力。红花还需绿叶扶。',
    '九三贲如濡如，永贞吉者，贲之盛也。文饰华美，又有润泽，永守正则吉。永贞之吉，终莫之陵也。占者宜内外兼修，文质彬彬。文质彬彬，然后君子。',
    '六四贲如皤如，白马翰如，匪寇婚媾者，贲之反也。文饰至极，反归于素，如白马来往。非为寇盗，实为婚媾。六四当位，疑也。匪寇婚媾，终无尤也。占者宜去华存实，返璞归真。',
    '六五贲于丘园，束帛戋戋，吝，终吉者，贲之主也。柔居尊位，文饰于丘园之间，礼物微薄，似有吝惜，然终得吉祥。六五之吉，有喜也。占者宜节俭朴素，不可铺张浪费。俭，德之共也；侈，恶之大也。',
    '上九白贲，无咎者，贲之极也。文饰至极，反于素白，无色之文，乃为至文。白贲无咎，上得志也。占者宜返璞归真，以素为美。绚烂之极，归于平淡。清水出芙蓉，天然去雕饰。'
  ],
  '剥': [
    '初六剥床以足，蔑贞凶者，剥之始也。剥落从足开始，渐次而上，正道被灭，故凶。剥床以足，以灭下也。占者宜防微杜渐，不可大意。千里之堤，溃于蚁穴。',
    '六二剥床以辨，蔑贞凶者，剥之渐也。剥至床辨，剥势渐盛，正道尽灭，故凶。剥床以辨，未有与也。占者宜及早防备，不可坐以待毙。当断不断，反受其乱。',
    '六三剥之，无咎者，剥之得也。虽处剥中，然与上九相应，虽剥而无咎。剥之无咎，失上下也。占者虽处困境，尚可自救。天无绝人之路。',
    '六四剥床以肤，凶者，剥之甚也。剥至床之肌肤，切近于身，凶可知矣。剥床以肤，切近灾也。占者危在旦夕，宜速谋出路。危急存亡之秋，不可大意。',
    '六五贯鱼，以宫人宠，无不利者，剥之主也。柔居尊位，如鱼贯而进，率领后宫群阴承宠于上，无所不利。以宫人宠，终无尤也。占者宜顺势而为，率众归附。识时务者为俊杰。',
    '上九硕果不食，君子得舆，小人剥庐者，剥之终也。剥之至极，一阳独存，如硕大之果，未被吞食。君子得车乘，小人则剥落屋宇。君子得舆，民所载也。小人剥庐，终不可用也。占者若为君子，终有出头之日。否极泰来。'
  ],
  '复': [
    '初九不远复，无祗悔，元吉者，复之始也。走了不远便返回，无有大悔，大吉大利。不远之复，以修身也。占者宜知错即改，不可拖延。过而能改，善莫大焉。浪子回头金不换。',
    '六二休复，吉者，复之美也。阴柔得中，欣然返回，吉祥如意。休复之吉，以下仁也。占者宜亲近仁者，从善如流。见贤思齐焉。',
    '六三频复，厉无咎者，复之难也。屡失屡复，频频往复，虽危厉而无大咎。频复之厉，义无咎也。占者宜屡败屡战，不可气馁。失败是成功之母。',
    '六四中行独复者，复之道也。阴柔得位，行于中道，独自返回。中行独复，以从道也。占者宜坚持正道，不随波逐流。道之所在，虽千万人吾往矣。',
    '六五敦复，无悔者，复之主也。柔居尊位，敦厚返回，无有悔恨。敦复无悔，中以自考也。占者宜忠厚老实，矢志不渝。不忘初心，方得始终。',
    '上六迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征者，复之极也。迷失道路而不知返，凶莫大焉。有灾祸，用兵必大败，累及其君，十年之久不能恢复。迷复之凶，反君道也。占者宜及早回头，不可执迷不悟。苦海无边，回头是岸。'
  ],
  '无妄': [
    '初九无妄，往吉者，无妄之始也。不妄为，往则吉祥。无妄之往，得志也。占者宜守正而行，不胡作非为。正道直行，无往不利。',
    '六二不耕获，不菑畲，则利有攸往者，无妄之盛也。不耕而获，不开荒而得良田，自然而成，利有所往。不耕获，未富也。占者宜顺其自然，不可强求。命里有时终须有，命里无时莫强求。',
    '六三无妄之灾，或系之牛，行人之得，邑人之灾者，无妄之灾也。无故而得祸，如有人系牛于此，过路人牵走，邑人反受嫌疑。无妄之灾，或系之牛，行人得之，邑人灾也。占者宜谨慎行事，谨防意外之灾。人在家中坐，祸从天上来。',
    '九四可贞，无咎者，无妄之守也。阳刚得位，守正不动，故无咎。可贞无咎，固有之也。占者宜坚守正道，不妄动。守正不阿，方得保全。',
    '九五无妄之疾，勿药有喜者，无妄之主也。阳刚中正，居尊位，不妄为而得小病，不须服药，自会痊愈。无妄之药，不可试也。占者宜顺其自然，不可乱投医。既来之，则安之。',
    '上九无妄，行有眚，无攸利者，无妄之极也。不妄为而动，亦有灾祸，无所利处。无妄之行，穷之灾也。占者宜静不宜动，守正待时。识时务者为俊杰。'
  ],
  '大畜': [
    '初九有厉，利已者，大畜之始也。阳刚初进，有危险，宜停止不进。有厉利已，不犯灾也。占者宜知难而退，不可冒进。留得青山在，不怕没柴烧。',
    '九二舆说輹者，大畜之中也。车脱其輹，不能行进，停下来休养。舆说輹，中无尤也。占者宜审时度势，该停则停。欲速则不达。',
    '九三良马逐，利艰贞，曰闲舆卫，利有攸往者，大畜之盛也。良马奔驰，利于艰难守正。练习车马防卫，则利有所往。利有攸往，上合志也。占者宜苦练本领，以备不时之需。养兵千日，用兵一时。',
    '六四童牛之牿，元吉者，大畜之善也。阴柔得位，防患于未然，如小牛未角先加横木，大吉大利。六四元吉，有喜也。占者宜及早防备，防患未然。预防胜于治疗。',
    '六五豮豕之牙，吉者，大畜之主也。柔居尊位，去其势而不用其牙，如阉割之猪，虽有牙而不伤人，吉祥如意。六五之吉，有庆也。占者宜治本不治标。扬汤止沸，不如釜底抽薪。',
    '上九何天之衢，亨者，大畜之极也。畜道已成，四通八达，如天之大道，亨通无阻。何天之衢，道大行也。占者前程似锦，大展宏图。海阔凭鱼跃，天高任鸟飞。'
  ],
  '颐': [
    '初九舍尔灵龟，观我朵颐，凶者，颐之始也。舍己之灵龟，观我之朵颐，羡慕他人，失己之正，故凶。观我朵颐，亦不足贵也。占者宜自食其力，不可垂涎他人。临渊羡鱼，不如退而结网。',
    '六二颠颐，拂经，于丘颐，征凶者，颐之失也。颠倒以求养，违背常道，求养于高处，往则凶。六二征凶，行失类也。占者宜自食其力，不可仰人鼻息。求人不如求己。',
    '六三拂颐，贞凶，十年勿用，无攸利者，颐之甚也。违背养正之道，守正防凶，十年不可用事，无所利处。十年勿用，道大悖也。占者宜改过自新，不可一意孤行。浪子回头金不换。',
    '六四颠颐，吉，虎视眈眈，其欲逐逐，无咎者，颐之得也。颠倒求养，然得正而吉。如虎之视，专注而求，其欲相继，无有过咎。颠颐之吉，上施光也。占者宜主动求养，志在必得。有志者事竟成。',
    '六五拂经，居贞吉，不可涉大川者，颐之主也。柔居尊位，虽有违常理，然守正得吉，不可涉险。居贞之吉，顺以从上也。占者宜安守本分，不可冒险。知足常乐。',
    '上九由颐，厉吉，利涉大川者，颐之极也。由之而得养，虽危而吉，利于涉险。由颐厉吉，大有庆也。占者得人供养，宜知恩图报。受人滴水之恩，当以涌泉相报。'
  ],
  '大过': [
    '初六藉用白茅，无咎者，大过之始也。以白茅垫于下，慎重之至，故无咎。藉用白茅，柔在下也。占者宜小心谨慎，敬慎从事。慎终如始，则无败事。',
    '九二枯杨生稊，老夫得其女妻，无不利者，大过之得也。枯杨生新芽，老夫得少妻，无所不利。老夫女妻，过以相与也。占者虽处困境，终有生机。枯木逢春。',
    '九三栋桡，凶者，大过之危也。阳刚过甚，栋梁弯曲，凶险。栋桡之凶，不可以有辅也。占者宜减轻负担，不可逞强。独木难支大厦倾。',
    '九四栋隆，吉，有它吝者，大过之善也。栋梁隆起，不挠不折，吉祥。然有他虑，稍有憾惜。栋隆之吉，不桡乎下也。占者宜担当重任，力挽狂澜。中流砥柱，力挽狂澜。',
    '九五枯杨生华，老妇得其士夫，无咎无誉者，大过之主也。枯杨开花，老妇得少夫，无咎无誉。枯杨生华，何可久也。老妇士夫，亦可丑也。占者宜适可而止，不可过极。',
    '上六过涉灭顶，凶，无咎者，大过之极也。涉水过深，淹没头顶，凶险。然杀身成仁，亦无咎。过涉之凶，不可咎也。占者宜知进退，不可轻生。留得青山在，不怕没柴烧。'
  ],
  '坎': [
    '初六习坎，入于坎窞，凶者，坎之始也。重险之中，又入深处，凶险。习坎入坎，失道凶也。占者宜谨慎小心，不可再入险境。一步错，步步错。',
    '九二坎有险，求小得者，坎之中也。阳刚得中，处坎险之中，虽有险，求小有所得。求小得，未出中也。占者宜从小事做起，不可贪大求全。知足常乐。',
    '六三来之坎坎，险且枕，入于坎窞，勿用者，坎之甚也。前后皆险，进退维谷，陷入深处，不可妄动。来之坎坎，终无功也。占者宜静不宜动，守正待时。动则得咎。',
    '六四樽酒簋贰，用缶，纳约自牖，终无咎者，坎之得也。阴柔得位，一樽酒，二簋饭，用瓦器，简约诚信，从窗户送入，终无咎。樽酒簋贰，刚柔际也。占者宜以诚待人，不拘小节。精诚所至，金石为开。',
    '九五坎不盈，祗既平，无咎者，坎之主也。阳刚中正，居尊位，水未满而平，无咎。坎不盈，中未大也。占者宜中庸行事，不可过极。满招损，谦受益。',
    '上六系用徽纆，寘于丛棘，三岁不得，凶者，坎之极也。被绳索捆绑，置于荆棘丛中，三年不得出，凶险。上六失道，凶三岁也。占者宜及早回头，不可执迷不悟。苦海无边，回头是岸。'
  ],
  '离': [
    '初九履错然，敬之，无咎者，离之始也。阳刚初明，行事错乱，然能敬慎，故无咎。履错之敬，以辟咎也。占者宜小心谨慎，敬以行事。小心驶得万年船。',
    '六二黄离，元吉者，离之美也。阴柔得中，黄色中色，附丽而得中道，大吉大利。黄离元吉，得中道也。占者宜守中道，不偏不倚。中庸之道，至矣尽矣。',
    '九三日昃之离，不鼓缶而歌，则大耋之嗟，凶者，离之衰也。太阳西斜，日暮途穷，不及时行乐，则老大徒伤悲，凶。日昃之离，何可久也。占者宜珍惜时光，把握当下。少壮不努力，老大徒伤悲。',
    '九四突如其来如，焚如，死如，弃如者，离之变也。突然而至，如火之焚，死而被弃，凶。突如其来如，无所容也。占者宜防患未然，不可大意。天有不测风云，人有旦夕祸福。',
    '六五出涕沱若，戚嗟若，吉者，离之主也。柔居尊位，涕泣滂沱，忧戚叹息，然得吉。六五之吉，离王公也。居安思危，方得长久。生于忧患，死于安乐。',
    '上九王用出征，有嘉折首，获匪其丑，无咎者，离之极也。明之极，王者用师出征，嘉美而斩其首，俘获其众，无咎。王用出征，以正邦也。占者宜明察秋毫，除恶务尽。斩草除根，以绝后患。'
  ],
  '咸': [
    '初六咸其拇者，咸之始也。感应在足大指，其感甚微，未动于外。拇，足大指也，在下而动之始。占者宜守正待时，不可妄动。感之始也，当慎之于初，不可轻动。动于冥冥，当审其几。',
    '六二咸其腓，凶，居吉者，感应在小腿也。腓，小腿肚也，动则躁进。阴柔得中，然急于应上，故凶。安居不动，守正则吉。占者宜静不宜动，宜守不宜攻。无欲速，无见小利，欲速则不达。',
    '九三咸其股，执其随，往吝者，感应在大腿也。股，大腿也，随足而动。阳刚得位，然执迷于随人而动，不能自主，往则有吝。占者宜独立自主，不可随波逐流。人各有志，不可强同。',
    '九四贞吉悔亡，憧憧往来，朋从尔思者，咸之主也。阳刚失位，守正则吉，悔恨消亡。心意不定，往来不绝，朋友顺从你的思虑。占者宜守正不阿，以诚意感人。精诚所至，金石为开。',
    '九五咸其脢，无悔者，感应在背脊肉也。脢，背脊肉也，在心之上，感之深者。阳刚中正，居尊位，感应深切，故无悔。占者宜以诚待人，感人心者莫先乎情。真诚所至，自能动人。',
    '上六咸其辅颊舌者，咸之极也。感应在口舌之间，徒有言语，无有实意。辅颊舌，皆言语之具也。阴柔居上，徒以言辞感人，而无诚意。占者宜言行一致，不可口惠而实不至。听其言，观其行，方为知人。'
  ],
  '恒': [
    '初六浚恒，贞凶，无攸利者，恒之始也。深求于恒，守正防凶，无所利处。浚，深也，初六阴柔居下，急于求深，而不达时变。占者宜循序渐进，不可操之过急。欲速则不达，欲深则反浅。',
    '九二悔亡者，恒之中也。阳刚得中，能久于中道，故悔恨消亡。以中为常，不偏不倚，不失其正。恒久于中，则无过无不及。占者宜守中道，持之以恒，则无不利。中庸之为德也，其至矣乎，民鲜能久矣。',
    '九三不恒其德，或承之羞，贞吝者，恒之失也。阳刚过甚，躁动不定，不能恒守其德，或蒙受羞辱。无常之人，人皆贱之，故守正防吝。占者宜始终如一，不可朝三暮四，见异思迁。人而无恒，不可以作巫医，况大事乎。',
    '九四田无禽者，恒之失位也。阳刚失位，久处不当之地，徒劳无功，田猎而无所得。恒不当位，何可得也。非其地而居之，非其事而为之，徒费心力。占者宜量才而用，不可久居非位。不在其位，不谋其政，明哲保身。',
    '六五恒其德，贞，妇人吉，夫子凶者，恒之主也。柔居尊位，恒守其德，守正。妇人守贞则吉，丈夫刚决则凶。占者宜因时制宜，不可一概而论。女子以顺为正，丈夫以义为裁。',
    '上六振恒，凶者，恒之极也。动摇于恒，朝三暮四，不能持久，故凶。振恒在上，大无功也。居上位而无常心，下莫之从，故大无功。占者宜持之以恒，不可虎头蛇尾，有始无终。靡不有初，鲜克有终。善始善终，方为可贵。'
  ],
  '遯': [
    '初六遯尾，厉，勿用有攸往者，遯之始也。退避在尾，处境危险，不可有所前往。遯尾之厉，不往何灾也。占者宜静不宜动，守正待时。识时务者为俊杰，退一步海阔天空。',
    '六二执之用黄牛之革，莫之胜说者，遯之中也。用黄牛皮绳束缚，无人能解脱。黄，中色；牛，顺物；革，坚也。固守不退，坚不可拔。占者宜坚守志向，不为外物所动。富贵不能淫，贫贱不能移。',
    '九三系遯，有疾厉，畜臣妾吉者，遯之系累也。心有所系，欲退不能，如染疾病，危厉。畜养臣仆侍妾则吉。占者宜当断则断，不可优柔寡断。当断不断，反受其乱。',
    '九四好遯，君子吉，小人否者，遯之得也。喜好退避，君子能之则吉，小人不能则否。君子好遯，小人否也。占者宜知进退存亡，不可贪恋权位。功成身退，天之道也。',
    '九五嘉遯，贞吉者，遯之主也。嘉美退避，守正则吉。阳刚中正，居尊位而能退，最为难得。占者宜功成身退，见好就收。急流勇退，方为智者。',
    '上九肥遯，无不利者，遯之极也。宽裕自得，超然物外，无所不利。肥遯无不利，无所疑也。占者宜超然物外，不为世俗所累。不汲汲于富贵，不戚戚于贫贱。'
  ],
  '大壮': [
    '初九壮于趾，征凶，有孚者，大壮之始也。强盛在足趾，前进则凶，宜有诚信。壮于趾，其孚穷也。占者不可恃强妄动，宜以诚信为本。强中更有强中手，莫向人前逞英豪。',
    '九二贞吉者，大壮之中也。阳刚得中，壮而不过，守正则吉。以中为大，不刚不柔，不失其正。大壮而得中，不逞强，不恃勇，故吉。占者宜守中道，不刚不柔，无过无不及。中庸之为德也，其至矣乎。',
    '九三小人用壮，君子用罔，贞厉，羝羊触藩，羸其角者，大壮之过也。小人用强力，君子则不然，守正防危。如公羊触篱笆，角被缠住，进退两难。占者不可逞强好胜，宜知进退。',
    '九四贞吉悔亡，藩决不羸，壮于大舆之輹者，大壮之盛也。守正则吉，悔恨消亡。篱笆冲开而角不被缠住，如大车轮轴之坚固。占者宜勇往直前，势如破竹。长风破浪会有时，直挂云帆济沧海。',
    '六五丧羊于易，无悔者，大壮之主也。在田畔丧失了羊，然无悔恨。柔居尊位，不刚不猛，虽丧羊而无悔。占者宜以柔克刚，不可用强。塞翁失马，焉知非福。',
    '上六羝羊触藩，不能退，不能遂，无攸利，艰则吉者，大壮之极也。公羊触篱笆，不能退，不能进，无所利处。然艰难守正则吉。穷上反下，故艰则吉。占者宜知进退，不可钻牛角尖。山重水复疑无路，柳暗花明又一村。'
  ],
  '晋': [
    '初六晋如摧如，贞吉，罔孚，裕无咎者，晋之始也。前进则受挫，守正则吉。未获信任，宽裕待时则无咎。晋如摧如，独行正也。占者宜坚守正道，不因挫折而气馁。不患人之不己知，患其不能也。',
    '六二晋如愁如，贞吉，受兹介福，于其王母者，晋之中也。前进而忧愁，守正则吉。从祖母那里承受大的福泽。以中正也，受福于王母。占者宜守正待时，终得贵人相助。吉人自有天相。',
    '六三众允，悔亡者，晋之渐也。众人信任，众望所归，故悔恨消亡。信而后进，上下一心，故能成事。占者宜取信于人，得道多助，失道寡助。得人心者得天下，失人心者失天下。',
    '九四晋如鼫鼠，贞厉者，晋之失也。前进如硕鼠，贪而畏人，守正防危。鼫鼠五技而穷，位不当也。占者不可贪得无厌，宜知足常乐。贪多嚼不烂，欲速则不达。',
    '六五悔亡，失得勿恤，往吉，无不利者，晋之主也。悔恨消亡，得失不必忧虑，前往吉祥，无所不利。柔居尊位，明而能断，故往吉无不利。占者宜明断果决，不必患得患失。当断不断，反受其乱。',
    '上九晋其角，维用伐邑，厉吉无咎，贞吝者，晋之极也。进至极处，如角之尖锐。用以讨伐属邑，虽危而吉无咎，然守正防吝。晋其角，道未光也。占者宜适可而止，不可穷兵黩武。止戈为武，不战而屈人之兵。'
  ],
  '明夷': [
    '初九明夷于飞，垂其翼，君子于行，三日不食，有攸往，主人有言者，明夷之始也。光明受伤，如鸟飞翔，垂下翅膀。君子出行，三日不食，有所前往，主人有责言。君子于行，义不食也。占者宜守道不阿，虽穷不改其志。不食嗟来之食，君子固穷。',
    '六二明夷，夷于左股，用拯马壮，吉者，明夷之中也。光明受伤，伤了左腿。用以拯救的马强壮，吉祥。六二之吉，顺以则也。占者宜顺势而为，借助外力以自拯。留得青山在，不怕没柴烧。',
    '九三明夷于南狩，得其大首，不可疾贞者，明夷之盛也。光明受伤之时，向南巡狩，得其元凶。不可急于求成，宜徐缓守正。南狩之志，乃大得也。占者宜循序渐进，不可操之过急。欲速则不达，慢工出细活。',
    '六四入于左腹，获明夷之心，于出门庭者，明夷之深也。进入左腹，探知光明受伤的内情，于是出门而去。入于左腹，获心意也。占者宜洞察内情，知几而退。明哲保身，见机而作。',
    '六五箕子之明夷，利贞者，明夷之主也。箕子在光明受伤之时，佯狂避祸，利于守正。箕子之贞，明不可息也。占者宜内明外柔，藏器待时。达则兼济天下，穷则独善其身。',
    '上六不明晦，初登于天，后入于地者，明夷之极也。不光明而昏暗，起初登上天空，后来坠入地下。初登于天，照四国也；后入于地，失则也。占者宜知进退，不可恃才傲物。木秀于林，风必摧之。'
  ],
  '家人': [
    '初九闲有家，悔亡者，家人之始也。家中有防备，悔恨消亡。闲，防也，治家之道，始于防闲。占者宜治家有法，防患于未然。修身齐家治国平天下，家齐而后国治。',
    '六二无攸遂，在中馈，贞吉者，家人之中也。无所专断，主管家中饮食之事，守正则吉。六二之吉，顺以巽也。占者宜各安本分，各司其职。家和万事兴，和气生财。',
    '九三家人嗃嗃，悔厉吉，妇子嘻嘻，终吝者，家人之严也。家中严肃，虽有危厉而吉；妇人孩子嬉笑无度，终有憾惜。家人嗃嗃，未失也；妇子嘻嘻，失家节也。占者治家宜严不宜宽。严家无悍虏，慈母有败子。',
    '六四富家，大吉者，家人之盛也。家中富足，大吉大利。六四当位，顺以从上，故能富家。占者宜勤俭持家，量入为出。成由勤俭败由奢。',
    '九五王假有家，勿恤吉者，家人之主也。君王至于家，不必忧虑，吉祥。王假有家，交相爱也。占者宜以诚待人，和睦相处。家和万事兴，和气致祥。',
    '上九有孚威如，终吉者，家人之极也。有诚信又有威严，终得吉祥。威如之吉，反身之谓也。占者宜以身作则，恩威并施。其身正，不令而行；其身不正，虽令不从。'
  ],
  '睽': [
    '初九悔亡，丧马勿逐自复，见恶人无咎者，睽之始也。悔恨消亡，丢失的马不必追逐，自己会回来。见到恶人，无有过咎。见恶人，以辟咎也。占者宜顺其自然，不可强求。命里有时终须有，命里无时莫强求。',
    '九二遇主于巷，无咎者，睽之中也。在小巷中遇到主人，无有过咎。遇主于巷，未失道也。占者宜随缘而遇，不可刻意追求。有缘千里来相会，无缘对面不相逢。',
    '六三见舆曳，其牛掣，其人天且劓，无初有终者，睽之乖也。看见车子被拉，牛被牵制，那人额上刺字又割鼻，起初不利，终有好结果。无初有终，遇刚也。占者宜坚持到底，不可半途而废。不经一番寒彻骨，怎得梅花扑鼻香。',
    '九四睽孤，遇元夫，交孚，厉无咎者，睽之孤也。乖离孤立，遇到大丈夫，以诚信相交，虽危而无咎。交孚无咎，志行也。占者宜以诚待人，广结善缘。四海之内皆兄弟也。',
    '六五悔亡，厥宗噬肤，往何咎者，睽之主也。悔恨消亡，同宗之人如噬嫩肉般易合，前往有何过咎。往有庆也。占者宜与人和睦，团结同志。众人拾柴火焰高。',
    '上九睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉者，睽之极也。乖离至极，见猪背上涂泥，载着一车鬼怪，先张弓欲射，后放下弓。不是强盗，是来求婚的。前往遇雨则吉。遇雨之吉，群疑亡也。占者宜消除疑虑，以诚待人。疑心生暗鬼，心正则百邪不侵。'
  ],
  '蹇': [
    '初六往蹇来誉者，蹇之始也。前往艰难，回来则得赞誉。宜退不宜进，识时务者为俊杰。往蹇来誉，宜待也。占者宜知难而退，不可冒进。留得青山在，不怕没柴烧。',
    '六二王臣蹇蹇，匪躬之故者，蹇之中也。君王的臣子艰难重重，不是为了自身。以身殉国，公而忘私。王臣蹇蹇，终无尤也。占者宜公而忘私，国而忘家。鞠躬尽瘁，死而后已。',
    '九三往蹇来反者，蹇之甚也。前往艰难，返回休息。知难而退，以图再举。往蹇来反，内喜之也。占者宜审时度势，可进则进，可退则退。识时务者为俊杰。',
    '六四往蹇来连者，蹇之连也。前往艰难，回来则与人相连。团结一致，共渡难关。往蹇来连，当位实也。占者宜团结同志，众志成城。人心齐，泰山移。',
    '九五大蹇朋来者，蹇之主也。大难临头，朋友前来相助。大蹇朋来，以中节也。占者宜广结善缘，得道多助。一方有难，八方支援。',
    '上六往蹇来硕，吉，利见大人者，蹇之极也。前往艰难，回来则大有收获，吉祥，利于见大人。往蹇来硕，志在内也；利见大人，以从贵也。占者宜归附贤明，终得吉祥。良禽择木而栖，贤臣择主而事。'
  ],
  '解': [
    '初六无咎者，解之始也。解除患难之初，无所过咎。刚柔相济，初动而免。解之初，义当无咎也。占者宜及时解脱，不可久困。苦海无边，回头是岸。',
    '九二田获三狐，得黄矢，贞吉者，解之中也。田猎获得三只狐狸，得到黄色的箭，守正则吉。九二贞吉，得中道也。占者宜刚柔相济，正中靶心。射人先射马，擒贼先擒王。',
    '六三负且乘，致寇至，贞吝者，解之失也。背负东西又乘车，招致强盗到来，守正防吝。负且乘，亦可丑也。占者宜藏富不露，不可炫耀。财不露白，富不骄横。',
    '九四解而拇，朋至斯孚者，解之去也。解除你足拇指的束缚，朋友到来，于是诚信。解而拇，未当位也。占者宜摆脱束缚，广结善缘。海阔凭鱼跃，天高任鸟飞。',
    '六五君子维有解，吉，有孚于小人者，解之主也。君子能够解脱，吉祥，以诚信感化小人。君子有解，小人退也。占者宜以德服人，使人心悦诚服。不战而屈人之兵，善之善者也。',
    '上六公用射隼于高墉之上，获之，无不利者，解之极也。王公在高墙上射隼，一举射中，无所不利。公用射隼，以解悖也。占者宜当机立断，除恶务尽。斩草不除根，春风吹又生。'
  ],
  '损': [
    '初九已事遄往，无咎，酌损之者，损之始也。事已完成，迅速前往，无有过咎，酌情减损。已事遄往，尚合志也。占者宜量力而行，适可而止。有所失必有所得，有所得必有所失。',
    '九二利贞，征凶，弗损益之者，损之中也。利于守正，前进则凶。不减损也不增益。九二利贞，中以为志也。占者宜守中道，不偏不倚。过犹不及，恰到好处。',
    '六三三人行则损一人，一人行则得其友者，损之渐也。三人同行则减损一人，一人独行则得到朋友。一人行，三则疑也。占者宜专一不杂，心无旁骛。志不可分，心不可二。',
    '六四损其疾，使遄有喜，无咎者，损之善也。减损其疾病，使之很快痊愈，无有过咎。损其疾，亦可喜也。占者宜改过自新，有过则改。过而能改，善莫大焉。',
    '六五或益之十朋之龟，弗克违，元吉者，损之主也。有人进献价值十朋的宝龟，无法推辞，大吉大利。六五元吉，自上祐也。占者宜顺其自然，不拒善缘。吉人自有天相，福从天降。',
    '上九弗损益之，无咎，贞吉，利有攸往，得臣无家者，损之极也。不减损反增益，无有过咎，守正则吉，利于有所前往，得到能臣而不计较其家。弗损益之，大得志也。占者宜施惠于人，终得厚报。桃李不言，下自成蹊。'
  ],
  '益': [
    '初九利用为大作，元吉无咎者，益之始也。利于大有作为，大吉大利无过咎。元吉无咎，下不厚事也。占者宜乘时而动，大有作为。机不可失，时不再来。',
    '六二或益之十朋之龟，弗克违，永贞吉，王用享于帝，吉者，益之中也。有人进献价值十朋的宝龟，无法推辞，永守正则吉。君王祭祀上帝，吉祥。或益之，自外来也。占者宜感恩图报，祭天祀祖。饮水思源，不忘根本。',
    '六三益之用凶事，无咎，有孚中行，告公用圭者，益之凶也。增益用于救凶之事，无有过咎。心怀诚信，行于中道，用玉圭告知王公。益用凶事，固有之也。占者宜扶危济困，积德行善。救人一命，胜造七级浮屠。',
    '六四中行告公从，利用为依迁国者，益之得也。行中道以告王公，王公信从。利于依凭大国迁都。告公从，以益志也。占者宜择善而从，从善如流。良禽择木而栖，贤臣择主而事。',
    '九五有孚惠心，勿问元吉，有孚惠我德者，益之主也。心怀诚信，施惠于心，不必问，大吉大利。对方也以诚信感戴我的恩德。有孚惠心，大得志也。占者宜以德服人，施惠于人。以德报德，以直报怨。',
    '上九莫益之，或击之，立心勿恒，凶者，益之极也。无人增益，反而有人攻击，立志不坚定，凶险。莫益之，偏辞也；或击之，自外来也。占者宜知足常乐，不可贪得无厌。人心不足蛇吞象，世事到头螳捕蝉。'
  ],
  '夬': [
    '初九壮于前趾，往不胜为咎者，夬之始也。强盛在前足，前往不能取胜则为过咎。不胜而往，咎也。占者不可轻敌冒进，宜量力而行。知彼知己，百战不殆。',
    '九二惕号，莫夜有戎，勿恤者，夬之中也。警惕呼号，夜晚有战事，不必忧虑。有戎勿恤，得中道也。占者宜有备无患，居安思危。生于忧患，死于安乐。',
    '九三壮于頄，有凶，君子夬夬独行，遇雨若濡，有愠无咎者，夬之决也。强盛在面颊，有凶险。君子决然独行，遇雨淋湿，虽有愠怒而无咎。君子夬夬，终无咎也。占者宜刚正不阿，不随波逐流。虽千万人吾往矣。',
    '九四臀无肤，其行次且，牵羊悔亡，闻言不信者，夬之失也。臀部没有皮肤，行走困难。牵着羊走，悔恨消亡，听了话却不相信。其行次且，位不当也。占者宜信受善言，不可固执己见。良药苦口利于病，忠言逆耳利于行。',
    '九五苋陆夬夬，中行无咎者，夬之主也。如苋菜陆草般脆断，行中道则无咎。中行无咎，中未光也。占者宜刚柔相济，不可过刚。太刚则折，太柔则废。',
    '上六无号，终有凶者，夬之极也。无须呼号，终有凶险。无号之凶，终不可长也。占者宜知进退，不可顽抗到底。识时务者为俊杰，顺天者昌，逆天者亡。'
  ],
  '姤': [
    '初六系于金柅，贞吉，有攸往，见凶，羸豕孚蹢躅者，姤之始也。系在铜制的刹车上，守正则吉。有所前往则见凶险，瘦弱的猪在烦躁不安。系于金柅，柔道牵也。占者宜守正不阿，不可妄动。静则吉，动则凶。',
    '九二包有鱼，无咎，不利宾者，姤之中也。厨房里有鱼，无有过咎，不利于招待宾客。包有鱼，义不及宾也。占者宜独善其身，不可张扬。财不露白，富不骄横。',
    '九三臀无肤，其行次且，厉无大咎者，姤之失也。臀部没有皮肤，行走困难，虽危厉而无大过咎。其行次且，行未牵也。占者宜谨慎行事，不可冒进。小心驶得万年船。',
    '九四包无鱼，起凶者，姤之远也。厨房里没有鱼，招致凶险。无鱼之凶，远民也。占者宜亲近众人，不可脱离群众。得人心者得天下，失人心者失天下。',
    '九五以杞包瓜，含章，有陨自天者，姤之主也。用杞柳叶包瓜，内含章美，有吉庆从天而降。九五含章，中正也；有陨自天，志不舍命也。占者宜守正待时，终得天佑。吉人自有天相。',
    '上九姤其角，吝，无咎者，姤之极也。遇到角，有憾惜，然无过咎。姤其角，上穷吝也。占者宜知进退，不可钻牛角尖。退一步海阔天空，让三分心平气和。'
  ],
  '萃': [
    '初六有孚不终，乃乱乃萃，若号一握为笑，勿恤往无咎者，萃之始也。诚信不能至终，纷乱聚集。若号呼则握手言欢，不必忧虑，前往无咎。乃乱乃萃，其志乱也。占者宜以诚待人，终归于好。冤家宜解不宜结。',
    '六二引吉无咎，孚乃利用禴者，萃之中也。引导吉祥，无有过咎。有诚信，利于简约的祭祀。引吉无咎，中未变也。占者宜以诚感人，心诚则灵。精诚所至，金石为开。',
    '六三萃如嗟如，无攸利，往无咎，小吝者，萃之叹也。聚集而嗟叹，无所利处。前往无咎，小有憾惜。往无咎，上巽也。占者宜随遇而安，不可强求。知足常乐，随遇而安。',
    '九四大吉无咎者，萃之盛也。大吉大利，无有过咎。大吉无咎，位不当也。虽不当位，然众望所归，故大吉。占者宜广结善缘，众人归附，海纳百川。海纳百川，有容乃大，君子容众。',
    '九五萃有位，无咎匪孚，元永贞悔亡者，萃之主也。聚集而有地位，无有过咎，尚未取信于人。大而永恒守正，悔恨消亡。萃有位，志未光也。有德有位，而未光大，然守正则悔亡。占者宜以德服人，取信于民，为政以德。得人心者得天下，以德服人者王。',
    '上六赍咨涕洟，无咎者，萃之极也。叹息流泪，无有过咎。赍咨涕洟，未安上也。处聚之极，忧盛危明，故无咎。占者宜居安思危，不可得意忘形，常存敬畏。生于忧患，死于安乐，君子戒惧。'
  ],
  '升': [
    '初六允升大吉者，升之始也。信从上升，大吉大利。允升大吉，上合志也。上下同心，顺势而升。占者宜顺势而为，与时俱进，乘势而上。好风凭借力，送我上青云，君子乘时。',
    '九二孚乃利用禴，无咎者，升之中也。有诚信，利于简约的祭祀，无有过咎。九二之孚，有喜也。以诚感天，虽薄亦享。占者宜以诚待人，心诚则灵，积善成德。积善之家，必有余庆，君子贵诚。',
    '九三升虚邑者，升之进也。上升进入空虚的城邑，畅通无阻。升虚邑，无所疑也。势如破竹，所向披靡。占者宜勇往直前，势如破竹，乘胜追击。长风破浪会有时，直挂云帆济沧海。',
    '六四王用亨于岐山，吉无咎者，升之盛也。君王在岐山祭祀，吉祥无过咎。王用亨于岐山，顺事也。顺天应人，祭告天地。占者宜顺天应人，得道多助，天人合一。顺天者昌，逆天者亡，君子顺命。',
    '六五贞吉，升阶者，升之主也。守正则吉，步步登高。贞吉升阶，大得志也。循序渐进，步步高升。占者宜循序渐进，步步高升，稳扎稳打。欲速则不达，功到自然成，君子务实。',
    '上六冥升，利于不息之贞者，升之极也。昏暗地上升，利于不停息地守正。冥升在上，消不富也。升极则降，当守正不息。占者宜知进退，不可贪得无厌，当知止不殆。月盈则亏，水满则溢，君子知止。'
  ],
  '困': [
    '初六臀困于株木，入于幽谷，三岁不觌者，困之始也。臀部被困在树干上，进入幽深的山谷，三年不见天日。入于幽谷，幽不明也。占者宜安于困境，待时而动。艰难困苦，玉汝于成。',
    '九二困于酒食，朱绂方来，利用享祀，征凶无咎者，困之中也。被困在酒食中，荣华富贵即将到来。利于祭祀，前进则凶，然无咎。困于酒食，中有庆也。占者宜居安思危，不可耽于享乐。生于忧患，死于安乐。',
    '六三困于石，据于蒺藜，入于其宫，不见其妻，凶者，困之甚也。被困在石头中，依托在蒺藜上，回到家中，不见妻子，凶险。据于蒺藜，乘刚也；入于其宫，不详也。占者宜择地而处，不可陷入困境。君子不立危墙之下。',
    '九四来徐徐，困于金车，吝有终者，困之缓也。缓缓而来，被困在金车中，有憾惜，然终有结果。来徐徐，志在下也；虽不当位，有与也。占者宜耐心等待，终有出头之日。好事多磨。',
    '九五劓刖，困于赤绂，乃徐有说，利用祭祀者，困之主也。割鼻断足，被困在荣华富贵中，于是慢慢解脱，利于祭祀。劓刖，志未得也；乃徐有说，以中直也。占者宜坚守正道，终得解脱。守得云开见月明。',
    '上六困于葛藟，于臲卼，曰动悔有悔，征吉者，困之极也。被困在葛藤中，动摇不安，动则有悔，然前进则吉。困于葛藟，未当也；动悔有悔，吉行也。占者宜当机立断，从困境中走出。穷则变，变则通，通则久。'
  ],
  '井': [
    '初六井泥不食，旧井无禽者，井之始也。井底有泥不能饮用，旧井无人来。井泥不食，下也；旧井无禽，时舍也。占者宜修身立德，不可自暴自弃。天生我材必有用。',
    '九二井谷射鲋，瓮敝漏者，井之中也。井底射小鱼，瓦罐破漏。井谷射鲋，无与也。占者宜量才而用，不可大材小用。英雄无用武之地，时也命也。',
    '九三井渫不食，为我心恻，可用汲，王明并受其福者，井之治也。井已淘净却不饮用，使我心中悲伤。可以汲水，君王英明则共享福祉。井渫不食，行恻也；求王明，受福也。占者宜待机而出，得遇明君则大展宏图。学成文武艺，货与帝王家。',
    '六四井甃，无咎者，井之修也。井壁修好，无有过咎。井甃无咎，修井也。占者宜修身养性，完善自我。玉不琢不成器，人不学不知道。',
    '九五井冽，寒泉食者，井之主也。井水清澈，寒凉的泉水可以饮用。寒泉之食，中正也。占者宜清正廉明，为民造福。为官一任，造福一方。',
    '上六井收勿幕，有孚元吉者，井之成也。井成不必覆盖，心怀诚信，大吉大利。元吉在上，大成也。占者宜功成不居，大公无私。大道之行也，天下为公。'
  ],
  '革': [
    '初九巩用黄牛之革者，革之始也。用黄牛皮束缚牢固，不可妄动。巩用黄牛，不可以有为也。占者宜守正待时，不可轻举妄动。静如处子，动如脱兔。',
    '六二己日乃革之，征吉无咎者，革之中也。到了己日才变革，前进吉祥无过咎。己日革之，行有嘉也。占者宜待时而动，时机成熟则改革。顺天应人，革故鼎新。',
    '九三征凶贞厉，革言三就，有孚者，革之过也。前进则凶，守正防危。变革的言论多次商定，有诚信。革言三就，又何之矣。占者宜三思而行，不可草率从事。三思而后行。',
    '九四悔亡，有孚改命，吉者，革之决也。悔恨消亡，有诚信，改变天命，吉祥。改命之吉，信志也。占者宜顺应时势，勇于变革。穷则变，变则通。',
    '九五大人虎变，未占有孚者，革之主也。大人如虎般变革，不必占卜就有诚信。大人虎变，其文炳也。占者宜雷厉风行，光明正大。言必信，行必果。',
    '上六君子豹变，小人革面，征凶，居贞吉者，革之成也。君子如豹般变革，小人改变面目，前进则凶，居守则吉。君子豹变，其文蔚也；小人革面，顺以从君也。占者宜适可而止，不可变革太过。过犹不及。'
  ],
  '鼎': [
    '初六鼎颠趾，利出否，得妾以其子，无咎者，鼎之始也。鼎足颠倒，利于倒出废物。得到妾及其子，无有过咎。鼎颠趾，未悖也。占者宜破旧立新，推陈出新。旧的不去，新的不来。',
    '九二鼎有实，我仇有疾，不我能即，吉者，鼎之中也。鼎中有实，我的对头有病，不能接近我，吉祥。鼎有实，慎所之也。占者宜守正不阿，远避小人。亲君子，远小人。',
    '九三鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉者，鼎之变也。鼎耳脱落，移动受阻，美味的野鸡肉不能吃。刚遇雨则亏损悔恨，终得吉祥。鼎耳革，失其义也。占者宜耐心等待，终得吉祥。好事多磨。',
    '九四鼎折足，覆公餗，其形渥，凶者，鼎之败也。鼎足折断，打翻了王公的佳肴，形状狼狈，凶险。覆公餗，信如何也。占者宜量才而用，不可任人唯亲。用人不当，必败无疑。',
    '六五鼎黄耳金铉，利贞者，鼎之主也。鼎有黄色的耳，铜制的杠，利于守正。鼎黄耳，中以为实也。占者宜刚柔相济，相得益彰。相得益彰，珠联璧合。',
    '上九鼎玉铉，大吉无不利者，鼎之成也。鼎有玉制的杠，大吉大利无所不利。玉铉在上，刚柔节也。占者宜善始善终，功德圆满。靡不有初，鲜克有终。'
  ],
  '震': [
    '初九震来虩虩，后笑言哑哑，吉者，震之始也。雷声响起，起初恐惧，后来谈笑风生，吉祥。震来虩虩，恐致福也；笑言哑哑，后有则也。占者宜居安思危，有备无患。生于忧患，死于安乐。',
    '六二震来厉，亿丧贝，跻于九陵，勿逐七日得者，震之中也。雷声到来有危险，丧失了钱财，登上高陵，不必追逐，七日可得。震来厉，乘刚也。占者宜临危不惧，终有所得。塞翁失马，焉知非福。',
    '六三震苏苏，震行无眚者，震之渐也。雷声震动，惶恐不安，雷震之行而无灾祸。震苏苏，位不当也。占者宜反躬自省，有则改之，无则加勉。吾日三省吾身。',
    '九四震遂泥者，震之陷也。雷震而陷入泥中，不能自拔。震遂泥，未光也。占者宜自强不息，不可自暴自弃。天行健，君子以自强不息。',
    '六五震往来厉，亿无丧有事者，震之主也。雷震往来有危险，没有大的损失，尚有祭祀之事。震往来厉，危行也；其事在中，大无丧也。占者宜守正不阿，虽危无咎。天塌下来有高个子顶着。',
    '上六震索索，视矍矍，征凶，震不于其躬于其邻，无咎，婚媾有言者，震之极也。雷震而畏惧退缩，目光惊恐，前进则凶。雷震未及自身而及于邻居，无咎。婚姻有言语。震索索，中未得也。占者宜见微知著，防患未然。亡羊补牢，未为晚也。'
  ],
  '艮': [
    '初六艮其趾，无咎，利永贞者，艮之始也。止住足趾，无有过咎，利于永守正道。艮其趾，未失正也。止于至善，不妄动则无咎。占者宜慎之于始，非礼不动，不可妄动。三思而后行，君子慎动。',
    '六二艮其腓，不拯其随，其心不快者，艮之中也。止住小腿，不能拯救他的随从，心中不快。不拯其随，未退听也。力有不逮，故不快。占者宜独善其身，量力而行，不可强为。穷则独善其身，达则兼济天下。',
    '九三艮其限，列其夤，厉薰心者，艮之甚也。止住腰部，撕裂了脊背肉，危厉如火烧心。艮其限，危薰心也。上下不交，中道断绝，故危。占者宜适可而止，不可太过，过犹不及。过犹不及，中庸为难。',
    '六四艮其身，无咎者，艮之安也。止住身体，无有过咎。艮其身，止诸躬也。反躬自省，守正不动。占者宜反躬自省，修身养性，独善其身。吾日三省吾身，君子修身。',
    '六五艮其辅，言有序，悔亡者，艮之主也。止住面颊，说话有条理，悔恨消亡。艮其辅，以中正也。慎言守中，言寡尤，行寡悔。占者宜谨言慎行，言多必失，行多必辱。病从口入，祸从口出，君子慎言。',
    '上九敦艮，吉者，艮之极也。敦厚于止，吉祥。敦艮之吉，以厚终也。止于至善，厚德载物，终吉。占者宜善始善终，厚道待人，以仁为本。厚德载物，仁厚则吉，君子贵仁。'
  ],
  '渐': [
    '初六鸿渐于干，小子厉有言，无咎者，渐之始也。大雁渐进到水涯，小子有危险，有言语，无咎。小子之厉，义无咎也。占者宜循序渐进，不可急于求成。欲速则不达。',
    '六二鸿渐于磐，饮食衎衎，吉者，渐之中也。大雁渐进到磐石上，饮食和乐，吉祥。饮食衎衎，不素饱也。占者宜安享其成，知足常乐。知足常乐，随遇而安。',
    '九三鸿渐于陆，夫征不复，妇孕不育，凶，利御寇者，渐之过也。大雁渐进到高平地，丈夫出征不回，妇人怀孕不育，凶险，利于抵御盗寇。夫征不复，离群丑也。占者宜坚守正道，御外侮则可。家和万事兴。',
    '六四鸿渐于木，或得其桷，无咎者，渐之得也。大雁渐进到树上，或许找到横枝栖息，无咎。或得其桷，顺以巽也。占者宜随遇而安，择木而栖。良禽择木而栖。',
    '九五鸿渐于陵，妇三岁不孕，终莫之胜，吉者，渐之主也。大雁渐进到山陵上，妇人三年不孕，终究不能取胜，吉祥。终莫之胜吉，得所愿也。占者宜坚守正道，终得所愿。有情人终成眷属。',
    '上九鸿渐于陆，其羽可用为仪，吉者，渐之成也。大雁渐进到高处，其羽毛可用为仪饰，吉祥。其羽可用为仪吉，不可乱也。占者宜洁身自好，为人表率。其身正，不令而行。'
  ],
  '归妹': [
    '初九归妹以娣，跛能履，征吉者，归妹之始也。嫁妹以侄娣陪嫁，跛足而能行走，前进吉祥。归妹以娣，以恒也；跛能履吉，相承也。占者宜安于本分，知足常乐。命里有时终须有。',
    '九二眇能视，利幽人之贞者，归妹之中也。眼盲而能看见，利于隐士守正。利幽人之贞，未变常也。占者宜安贫乐道，不改其志。穷且益坚，不坠青云之志。',
    '六三归妹以须，反归以娣者，归妹之失也。嫁妹以待时机，反以侄娣身份嫁过去。归妹以须，未当也。占者宜把握时机，不可错过缘分。机不可失，时不再来。',
    '九四归妹愆期，迟归有时者，归妹之缓也。嫁妹延误日期，晚嫁有其时。愆期之志，有待而行也。占者宜耐心等待，缘分会来。好事多磨。',
    '六五帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉者，归妹之主也。帝乙嫁妹，正妻的衣袖不如陪嫁的好。月亮将近圆满，吉祥。帝乙归妹，不如其娣之袂良也。占者宜重质不重貌。金玉其外，败絮其中。',
    '上六女承筐无实，士刲羊无血，无攸利者，归妹之极也。女子捧筐没有实货，男子宰羊没有血，无所利处。上六无实，承虚筐也。占者宜实事求是，不可虚有其表。华而不实，无益也。'
  ],
  '丰': [
    '初九遇其配主，虽旬无咎，往有尚者，丰之始也。遇到匹配的主人，虽然十日也无咎，前往有嘉赏。虽旬无咎，过旬灾也。占者宜与时俱进，不可错过时机。机不可失，时不再来。',
    '六二丰其蔀，日中见斗，往得疑疾，有孚发若，吉者，丰之中也。增大其遮蔽，正午见到北斗星。前往得疑病，有诚信则启发，吉祥。有孚发若，信以发志也。占者宜以诚待人，消除疑虑。精诚所至，金石为开。',
    '九三丰其沛，日中见沫，折其右肱，无咎者，丰之过也。增大其幔幕，正午见到小星星，折断了右臂，无咎。丰其沛，不可大事也；折其右肱，终不可用也。占者宜量力而行，不可勉强。留得青山在，不怕没柴烧。',
    '九四丰其蔀，日中见斗，遇其夷主，吉者，丰之遇也。增大其遮蔽，正午见到北斗星，遇到了夷主，吉祥。遇其夷主，吉行也。占者宜随缘而遇，终得贵人相助。吉人自有天相。',
    '六五来章，有庆誉，吉者，丰之主也。带来文采，有福庆美誉，吉祥。六五之吉，有庆也。占者宜以德服人，声名远扬。桃李不言，下自成蹊。',
    '上六丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶者，丰之极也。增大其房屋，遮蔽其家，从门缝看，寂静无人，三年不见，凶险。丰其屋，天际翔也；窥其户，阒其无人，自藏也。占者宜戒骄戒奢，不可盛气凌人。月盈则亏，水满则溢。'
  ],
  '旅': [
    '初六旅琐琐，斯其所取灾者，旅之始也。旅居猥琐卑贱，这是自取灾祸。旅琐琐，志穷灾也。占者宜自重自爱，不可自轻自贱。人必自侮，然后人侮之。',
    '六二旅即次，怀其资，得童仆贞者，旅之中也。旅居到客舍，怀带着钱财，得到童仆的忠心。得童仆贞，终无尤也。占者宜善自为谋，善待下人。得人心者得天下。',
    '九三旅焚其次，丧其童仆，贞厉者，旅之失也。旅居的客舍被烧，丧失了童仆，守正防危。旅焚其次，亦以伤矣。占者宜谨慎小心，防火防盗。小心驶得万年船。',
    '九四旅于处，得其资斧，我心不快者，旅之暂也。旅居在暂处之地，得到了钱财和斧具，我心中不快。旅于处，未得位也。占者宜随遇而安，不可挑剔。既来之，则安之。',
    '六五射雉，一矢亡，终以誉命者，旅之主也。射野鸡，一支箭射出去，终得美誉和爵命。终以誉命，上逮也。占者宜坚持不懈，终得成功。有志者事竟成。',
    '上九鸟焚其巢，旅人先笑后号咷，丧牛于易，凶者，旅之极也。鸟的巢被烧，旅人先笑后哭，在田畔丧失了牛，凶险。以旅在上，其义焚也；丧牛于易，终莫之闻也。占者宜知进退，不可乐极生悲。乐极生悲，否极泰来。'
  ],
  '巽': [
    '初六进退，利武人之贞者，巽之始也。进退不定，利于武人守正。进退，志疑也；利武人之贞，志治也。占者宜果断行事，不可优柔寡断。当断不断，反受其乱。',
    '九二巽在床下，用史巫纷若，吉无咎者，巽之中也。卑顺在床下，用史巫祈福，纷然不绝，吉祥无咎。纷若之吉，得中也。占者宜以诚感人，心诚则灵。精诚所至，金石为开。',
    '九三频巽，吝者，巽之过也。频繁地卑顺，屈己过度，有憾惜。频巽之吝，志穷也。过于柔顺，反失其道，故吝。占者宜有骨气，不可卑躬屈膝，丧失人格。大丈夫能屈能伸，不可一味卑顺。',
    '六四悔亡，田获三品者，巽之得也。悔恨消亡，田猎获得三种猎物。田获三品，有功也。顺势而为，大有所获。占者宜顺势而为，大有所获，乘风而上。好风凭借力，送我上青云，君子乘势。',
    '九五贞吉悔亡，无不利，无初有终，先庚三日，后庚三日，吉者，巽之主也。守正则吉，悔恨消亡，无所不利。无始有终，庚前三天，庚后三天，吉祥。九五之吉，位正中也。占者宜审时度势，后发制人。后来者居上。',
    '上九巽在床下，丧其资斧，贞凶者，巽之极也。卑顺在床下，丧失了钱财和斧具，守正防凶。巽在床下，上穷也；丧其资斧，正乎凶也。占者宜知进退，不可过于柔顺。太柔则废，太刚则折。'
  ],
  '兑': [
    '初九和兑，吉者，兑之始也。和悦待人，吉祥如意。和兑之吉，行未疑也。以和为贵，人皆亲之。占者宜和蔼可亲，与人为善，广结善缘。和气生财，家和万事兴，天地之气，莫大于和。',
    '九二孚兑，吉，悔亡者，兑之中也。诚信和悦，吉祥如意，悔恨消亡。孚兑之吉，信志也。以诚待人，人亦以诚应之。占者宜以诚待人，言而有信，行而有果。言必信，行必果，君子之德也。',
    '六三来兑，凶者，兑之失也。前来求悦，谄媚逢迎，凶险。来兑之凶，位不当也。不以正道求合，而以谗媚取悦，人皆贱之。占者宜自尊自爱，不可谄媚逢迎，丧失人格。君子之交淡如水，小人之交甘若醴。',
    '九四商兑未宁，介疾有喜者，兑之商也。商议和悦，未能安宁，隔绝疾病则有喜庆。九四之喜，有庆也。明辨是非，择善而从，故有喜。占者宜明辨是非，择善而从，远离邪恶。近朱者赤，近墨者黑，君子慎所居。',
    '九五孚于剥，有厉者，兑之主也。诚信被剥蚀，阴邪浸染，有危险。孚于剥，位正当也。居尊位而信谗言，正道将消。占者宜防微杜渐，亲君子远小人，不可掉以轻心。千里之堤，溃于蚁穴，君子慎微。',
    '上六引兑者，兑之极也。引诱和悦，引人入迷，未可知也。上六处兑之极，诱民于逸乐，而不知节。占者宜警惕引诱，不可沉迷不悟，当知所节制。玩物丧志，玩人丧德，君子慎之。'
  ],
  '涣': [
    '初六用拯马壮，吉者，涣之始也。用以拯救的马强壮，吉祥。初六之吉，顺也。顺势而为，借力成事。占者宜顺势而为，借助外力，以济其难。好风凭借力，送我上青云，君子乘时。',
    '九二涣奔其机，悔亡者，涣之中也。涣散之时，奔往几案，悔恨消亡。涣奔其机，得愿也。及时安定，转危为安。占者宜及时安定，转危为安，化险为夷。化险为夷，转危为安，君子知几。',
    '六三涣其躬，无悔者，涣之进也。涣散其自身，无有悔恨。涣其躬，志在外也。公而忘私，国而忘家。占者宜大公无私，先国后家，以天下为己任。公而忘私，国而忘家，君子贵公。',
    '六四涣其群，元吉，涣有丘，匪夷所思者，涣之盛也。涣散其党羽，大吉大利。涣散了小团体而聚成山丘，不是常人所能想到的。涣其群元吉，光大也。大公无私，众志成城。占者宜大公无私，众志成城，团结一心。众人拾柴火焰高，君子合群。',
    '九五涣汗其大号，涣王居，无咎者，涣之主也。如出汗般发布重大号令，涣散王者的居积，无咎。王居无咎，正位也。推恩于民，藏富于民。占者宜推恩于民，藏富于民，与民同乐。民为邦本，本固邦宁，王者以民为本。',
    '上九涣其血，去逖出，无咎者，涣之极也。涣散其忧患，远离而去，无咎。涣其血，远害也。远离祸患，明哲保身。占者宜远离祸患，明哲保身，见几而作。君子不立危墙之下，明哲保身。'
  ],
  '节': [
    '初九不出户庭，无咎者，节之始也。不出门户庭院，无有过咎。不出户庭，知通塞也。知止而后有定，静则无咎。占者宜谨言慎行，守正待时，不可轻举妄动。慎终如始，则无败事，君子慎独。',
    '九二不出门庭，凶者，节之中也。不出门庭，凶险。不出门庭凶，失时极也。当进而不进，坐失良机，故凶。占者宜把握时机，顺势而为，不可错失良机。机不可失，时不再来，君子见几而作。',
    '六三不节若，则嗟若，无咎者，节之失也。不能节制，于是嗟叹，无咎。不节之嗟，又谁咎也。不知节者，自取其咎，然能知悔，亦可无咎。占者宜自我反省，有过则改，亡羊补牢。过而能改，善莫大焉。',
    '六四安节，亨者，节之得也。安于节制，亨通。安节之亨，承上道也。安贫乐道，知足常乐，故亨。占者宜知足常乐，安贫乐道，不贪不求。知足常乐，随遇而安，君子安命。',
    '九五甘节，吉，往有尚者，节之主也。甘于节制，吉祥，前往有嘉赏。甘节之吉，居位中也。以节为甘，乐而为之，故吉。占者宜乐于节制，以俭为德，清苦自甘。俭，德之共也；侈，恶之大也。',
    '上六苦节，贞凶，悔亡者，节之极也。苦于节制，守正防凶，悔恨消亡。苦节贞凶，其道穷也。节之太过，反以为苦，物极必反。占者宜适可而止，不可太过，过犹不及。过犹不及，中庸为难。'
  ],
  '中孚': [
    '初九虞吉，有它不燕者，中孚之始也。安守则吉，另有他求则不安。初九虞吉，志未变也。安于本份，守正不变。占者宜安分守己，不可三心二意，见异思迁。知足常乐，随遇而安，君子安命。',
    '九二鸣鹤在阴，其子和之，我有好爵，吾与尔靡之者，中孚之中也。鹤在树荫下鸣叫，它的小鹤应和它。我有美酒，与你共享。其子和之，中心愿也。以诚感人，人亦诚应。占者宜以诚待人，有福同享，有难同当。独乐乐不如众乐乐，君子贵诚。',
    '六三得敌，或鼓或罢，或泣或歌者，中孚之变也。遇到敌人，或击鼓或罢兵，或哭泣或歌唱。或鼓或罢，位不当也。中无定守，故进退无恒。占者宜处变不惊，临危不乱，坚守本心。泰山崩于前而色不变，君子有守。',
    '六四月几望，马匹亡，无咎者，中孚之盛也。月亮将近圆满，马匹丢失，无咎。马匹亡，绝类上也。虚心应上，虽亡而实得。占者宜宽宏大量，不必计较，失小得大。塞翁失马，焉知非福，君子达观。',
    '九五有孚挛如，无咎者，中孚之主也。诚信相连，无有过咎。有孚挛如，位正当也。居中正之位，诚信与天下相连。占者宜以诚待人，众志成城，上下一心。人心齐，泰山移，王者以诚感人。',
    '上九翰音登于天，贞凶者，中孚之极也。鸡鸣之声上达于天，守正防凶。翰音登于天，何可长也。名过其实，声闻于天，而实不副，何可久也。占者宜脚踏实地，不可好高骛远，名不副实。名不副实，难以为继，君子务实。'
  ],
  '小过': [
    '初六飞鸟以凶者，小过之始也。飞鸟向上，欲速不达，有凶险。飞鸟以凶，不可如何也。位卑而欲高，力小而任重，故凶。占者宜安分守己，不可好高骛远，量力而行。爬得高，摔得重，君子务实。',
    '六二过其祖，遇其妣，不及其君，遇其臣，无咎者，小过之中也。超过祖父，遇到祖母，不及君王，遇到臣子，无咎。不及其君，臣不可过也。过而不过，得其中道。占者宜审时度势，不可太过，亦不可不及。过犹不及，中庸为难。',
    '九三弗过防之，从或戕之，凶者，小过之失也。不加以防备，跟从或许会被害，凶险。从或戕之，凶如何也。无备而从，必受其害。占者宜防微杜渐，有备无患，不可轻信他人。害人之心不可有，防人之心不可无。',
    '九四无咎，弗过遇之，往厉必戒，勿用永贞者，小过之得也。无咎，不过分而相遇，前往危险必戒备，不可永久守正。弗过遇之，位不当也。过而不过，随时应变。占者宜随机应变，不可固执，识时务者为俊杰。识时务者为俊杰，君子通权达变。',
    '六五密云不雨，自我西郊，公弋取彼在穴者，小过之主也。乌云密布不下雨，从我西郊而来。王公射取穴中之物。密云不雨，已上也。阴盛于上，而未及下。占者宜藏器待时，不鸣则已，一鸣惊人。藏器待时，君子居易以俟命。',
    '上六弗遇过之，飞鸟离之，凶，是谓灾眚者，小过之极也。没有相遇却超过了，飞鸟被网罗，凶险，这叫做灾祸。弗遇过之，已亢也。过之已甚，故灾及之。占者宜知进退，不可过极，当知止不殆。月盈则亏，水满则溢，君子知止。'
  ],
  '既济': [
    '初九曳其轮，濡其尾，无咎者，既济之始也。向后拉车轮，沾湿了尾巴，无咎。曳其轮，义无咎也。既济之初，慎而不进，故无咎。占者宜慎始敬终，不可大意，小心驶得万年船。小心驶得万年船，君子慎始。',
    '六二妇丧其茀，勿逐，七日得者，既济之中也。妇人丢失了车饰，不必追逐，七日可得。七日得，以中道也。守中待时，不求自得。占者宜耐心等待，失而复得，不必强求。命里有时终须有，君子安命。',
    '九三高宗伐鬼方，三年克之，小人勿用者，既济之盛也。高宗讨伐鬼方，三年才战胜，小人不可重用。三年克之，惫也。功成之后，小人虽有功，终不可用。占者宜用人得当，不可任人唯亲，亲君子远小人。亲君子，远小人，王者用人之道。',
    '六四繻有衣袽，终日戒者，既济之防也。华美的衣服变成破衣，终日戒备。终日戒，有所疑也。安而不忘危，存而不忘亡。占者宜居安思危，有备无患，常存戒惧之心。生于忧患，死于安乐，君子戒惧。',
    '九五东邻杀牛，不如西邻之禴祭，实受其福者，既济之主也。东边邻国杀牛厚祭，不如西边邻国的薄祭，实在受到福佑。不如西邻之时也；实受其福，吉大来也。心诚则灵，不在厚薄。占者宜诚心实意，不尚浮华，心诚则灵。心诚则灵，君子贵诚。',
    '上六濡其首，厉者，既济之极也。沾湿了头，危险。濡其首厉，何可久也。既济之极，乐极生悲，何可长久。占者宜知进退，不可乐极生悲，当知止不殆。物极必反，盛极必衰，君子知几。'
  ],
  '未济': [
    '初六濡其尾，吝者，未济之始也。沾湿了尾巴，有憾惜。濡其尾，亦不知极也。未济之初，力有不逮，故吝。占者宜量力而行，不可冒进，欲速则不达。欲速则不达，君子量力而行。',
    '九二曳其轮，贞吉者，未济之中也。向后拉车轮，守正则吉。九二贞吉，中以行正也。居中守正，不进不退。占者宜守正待时，稳中求进，不急于求成。稳扎稳打，步步为营，君子务实。',
    '六三未济征凶，利涉大川者，未济之难也。尚未成功，前进则凶，利于渡过大河。未济征凶，位不当也。险中求胜，非常之事。占者宜知难而进，险中求胜，不入虎穴焉得虎子。不入虎穴，焉得虎子，勇者敢为。',
    '九四贞吉悔亡，震用伐鬼方，三年有赏于大国者，未济之得也。守正则吉，悔恨消亡。以雷霆之势讨伐鬼方，三年后受赏于大国。贞吉悔亡，志行也。立志而行，终得成功。占者宜坚持不懈，终有所成，有志者事竟成。有志者事竟成，君子励志。',
    '六五贞吉无悔，君子之光，有孚吉者，未济之主也。守正则吉，无有悔恨。君子的光辉，有诚信则吉祥。君子之光，其晖吉也。君子之光，普照天下。占者宜以德服人，光明正大，其身正不令而行。其身正，不令而行，君子正己。',
    '上九有孚于饮酒，无咎，濡其首，有孚失是者，未济之极也。有诚信而饮酒，无咎。沾湿了头，有诚信也失去了正道。饮酒濡首，亦不知节也。乐而忘节，虽信亦失。占者宜适可而止，不可沉迷不悟，当知所节制。乐极生悲，物极必反，君子知节。'
  ]
};

