// 将问占数据注入 HEXAGRAMS
(function injectFortuneData() {
  for (const name in FORTUNE_DATA) {
    const hex = HEXAGRAMS.find(h => h.name === name);
    if (hex && FORTUNE_DATA[name].fortune) {
      hex.fortune = FORTUNE_DATA[name].fortune;
    }
  }
})();

/* =========================================================
   工具函数
   ========================================================= */
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => [...document.querySelectorAll(sel)];
const findHex = (u, l) => HEXAGRAMS.find(h => h.upper === u && h.lower === l);

function getSymbol(upper, lower) {
  const lb = TRIGRAMS[lower].bits, ub = TRIGRAMS[upper].bits;
  const sym = [];
  for (let i = 0; i < 6; i++) {
    sym.push(i < 3 ? (lb >> (2 - i)) & 1 : (ub >> (5 - i)) & 1);
  }
  return sym;
}
function symToTrigram(sym) {
  const lb = (sym[2]) | (sym[1] << 1) | (sym[0] << 2);
  const ub = (sym[5]) | (sym[4] << 1) | (sym[3] << 2);
  const byBits = n => TRIGRAMS[n].bits;
  const lower = Object.keys(TRIGRAMS).find(n => byBits(n) === lb);
  const upper = Object.keys(TRIGRAMS).find(n => byBits(n) === ub);
  return { upper, lower };
}
function shenStartIndex() {
  const dayGan = GAN[(new Date().getDate() - 1) % 10];
  return SHEN_START[dayGan];
}
function sixin(gongWu, dz) {
  const w0 = gongWu, wd = DZ_WU[dz];
  if (w0 === wd) return '兄弟';
  const sheng = { 木: '火', 火: '土', 土: '金', 金: '水', 水: '木' };
  const ke   = { 木: '土', 土: '水', 水: '火', 火: '金', 金: '木' };
  if (sheng[w0] === wd) return '子孙';
  if (ke[w0] === wd)   return '妻财';
  if (sheng[wd] === w0) return '父母';
  if (ke[wd] === w0)   return '官鬼';
  return '兄弟';
}

/* 卦象线 HTML */
function yaoLineHTML(val, changing = false, mark = '') {
  const cls = val ? '' : ' brk';
  const chgCls = changing ? ' chg' : '';
  const mHTML = mark ? `<span class="hx-mark"></span>` : '';
  return `<div class="hx-l${chgCls}">
    <span class="hidx">${mark || ''}</span>
    <div class="hl${cls}"></div>${mHTML}
  </div>`;
}

