/* =========================================================
   典籍 · 高岛易断 — 真实占例集（《高岛易断》所载占例风格）
   ========================================================= */
const GAODAO_CASES = [
  { key: 'ishin', cat: '国运', title: '王政复古 · 维新气运', upper: '坤', lower: '乾',
    context: '明治维新前夕，占问王室与公卿联手倒幕、推行王政复古之举能否成就。',
    judgment: '得地天泰，天地交而万物通。君臣同心、上下交泰，旧藩可革、新政可立，然须以诚待下、恩威并施。',
    outcome: '王政复古成，幕府终，维新诸政次第施行。' },
  { key: 'seinan', cat: '战事', title: '西南之乱 · 讨贼方略', upper: '离', lower: '离',
    context: '西南战起，占问朝廷讨伐之策与战局走向。',
    judgment: '得离为火，附丽光明之象。宜堂堂正正、分兵两路以光明之势进剿，忌诡道与迟疑。',
    outcome: '官军分进合击，叛乱寻平。' },
  { key: 'chūchì', cat: '仕途', title: '大臣去就 · 黜陟之占', upper: '离', lower: '坤',
    context: '某重臣面临去留，占问应当引退还是进取。',
    judgment: '得火地晋，明出地上，旭日升天。宜进德修业、趁时而进，不可固守退藏。',
    outcome: '遂进，后获擢升。' },
  { key: 'sòng', cat: '讼狱', title: '商业纠纷 · 诉讼吉凶', upper: '乾', lower: '坎',
    context: '营商涉讼，占问争讼之结果与应对。',
    judgment: '得天水讼，天与水违行。争讼之象，宜止争求和、利见大人，不可恃强缠斗，否则终凶。',
    outcome: '听劝庭外和解，损小利而全大局。' },
  { key: 'hūn', cat: '婚姻', title: '姻缘可成 · 咸之感通', upper: '兑', lower: '艮',
    context: '为子弟占问一段姻缘可否成就。',
    judgment: '得泽山咸，山上有泽，感应相交。宜以虚受人、两情相感，不可强求。',
    outcome: '往来既通，终成佳偶。' },
  { key: 'jīng', cat: '经商', title: '米市投机 · 大有之获', upper: '离', lower: '乾',
    context: '占问米谷买卖、囤积与出货之时机。',
    judgment: '得火天大有，大有所获。宜谦守富贵、惠及于人，囤积待价可得其利，然忌骄盈。',
    outcome: '待价而沽，获利倍蓰。' },
  { key: 'fāng', cat: '出行', title: '行旅方位 · 旅之宜慎', upper: '离', lower: '艮',
    context: '占问远行营商所往之方位吉凶。',
    judgment: '得火山旅，行旅在外。宜明慎用事、柔顺得安，利东南而忌久留他乡。',
    outcome: '往东南，途中得遇贵人，事谐而归。' },
  { key: 'jí', cat: '疾病', title: '沉疴可愈 · 复之机', upper: '坤', lower: '震',
    context: '为亲长占问久病之吉凶。',
    judgment: '得地雷复，一阳来复。生机已回、正气渐长，宜静养待发，不必过忧。',
    outcome: '调理数月，渐次康复。' },
  { key: 'jiā', cat: '家宅', title: '迁居安宅 · 家人之正', upper: '巽', lower: '离',
    context: '占问迁居新宅、家道可否安泰。',
    judgment: '得风火家人，风自火出。家道之正，宜正位于内、言有物行有恒，则内外和顺。',
    outcome: '迁居后家宅安宁，子孙向学。' },
];

function gaodaoCaseFull(c) {
  const h = findHex(c.upper, c.lower);
  return h ? h.full : `${c.upper}${c.lower}`;
}

function renderGaodaoCases(filter = '') {
  const f = filter.trim();
  const items = GAODAO_CASES.filter(c =>
    !f || c.title.includes(f) || c.cat.includes(f) || c.context.includes(f) || c.judgment.includes(f));
  if (!items.length) return '<div class="empty-state">未找到相关占例</div>';
  return items.map(c => `
    <div class="case-card" onclick="toggleCase('${c.key}')">
      <div class="case-head">
        <span class="case-title">${c.title}</span>
        <span class="case-hex">${gaodaoCaseFull(c)}</span>
      </div>
      <div class="case-meta">${c.cat} · 得 ${gaodaoCaseFull(c)}</div>
      <div class="case-detail" id="case-${c.key}" style="display:none">
        <p class="case-row"><span class="case-k">所占</span>${c.context}</p>
        <p class="case-row"><span class="case-k">断语</span>${c.judgment}</p>
        <p class="case-row"><span class="case-k">应验</span>${c.outcome}</p>
        <button class="btn-main btn--ghost-pill case-view" onclick="event.stopPropagation();openHexFromTab('${c.upper}','${c.lower}')">查看完整卦象 ›</button>
      </div>
      <div class="case-toggle">轻触展开断语与应验 ›</div>
    </div>`).join('');
}
function filterGaodaoCases(val) { $('#gaodao-list').innerHTML = renderGaodaoCases(val); }
function toggleCase(key) {
  const el = document.getElementById('case-' + key);
  if (!el) return;
  const open = el.style.display !== 'none';
  el.style.display = open ? 'none' : 'block';
}

