async function handleLogin() {
  const email = document.getElementById('login-email')?.value.trim();
  const password = document.getElementById('login-password')?.value;

  if (!email || !password) {
    toast('请填写邮箱和密码');
    return;
  }

  toast('当前为本地模式，云端登录未启用');
}

async function handleSignup() {
  const email = document.getElementById('login-email')?.value.trim();
  const password = document.getElementById('login-password')?.value;

  if (!email || !password) {
    toast('请填写邮箱和密码');
    return;
  }

  if (password.length < 6) {
    toast('密码至少6位');
    return;
  }

  toast('当前为本地模式，云端注册未启用');
}

async function doLogout() {
  toast('已清除本地资料');
  try { localStorage.removeItem(USER_KEY); } catch (e) {}
  showMineView();
}
function changeAvatar() {
  showAvatarPicker();
}

function showAvatarPicker() {
  const overlay = document.createElement('div');
  overlay.className = 'avatar-overlay';
  overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };

  overlay.innerHTML = `
    <div class="avatar-sheet">
      <div class="avatar-sheet-title">更换头像</div>
      <div class="avatar-options">
        <div class="avatar-opt" onclick="pickAvatarFromCamera()">
          <div class="avatar-opt-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
              <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/>
              <circle cx="12" cy="13" r="4"/>
            </svg>
          </div>
          <span>拍照</span>
        </div>
        <div class="avatar-opt" onclick="pickAvatarFromAlbum()">
          <div class="avatar-opt-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
              <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
              <circle cx="8.5" cy="8.5" r="1.5"/>
              <polyline points="21 15 16 10 5 21"/>
            </svg>
          </div>
          <span>从相册选择</span>
        </div>
        <div class="avatar-opt" onclick="resetAvatarToTaiji()">
          <div class="avatar-opt-icon">
            <svg viewBox="0 0 80 80" fill="none">
              <circle cx="40" cy="40" r="36" fill="none" stroke="currentColor" stroke-width="2"/>
              <path d="M40 4a36 36 0 0 1 0 72 18 18 0 0 1 0-36 18 18 0 0 0 0-36z" fill="currentColor"/>
              <circle cx="40" cy="22" r="5" fill="var(--bg-2)"/>
              <circle cx="40" cy="58" r="5" fill="currentColor"/>
            </svg>
          </div>
          <span>默认头像</span>
        </div>
      </div>
      <button class="avatar-cancel" onclick="this.closest('.avatar-overlay').remove()">取消</button>
    </div>
  `;

  document.body.appendChild(overlay);
  setTimeout(() => overlay.classList.add('show'), 10);

  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = 'image/*';
  fileInput.id = 'avatar-file-input';
  fileInput.style.display = 'none';
  fileInput.onchange = handleAvatarFile;
  document.body.appendChild(fileInput);

  const cameraInput = document.createElement('input');
  cameraInput.type = 'file';
  cameraInput.accept = 'image/*';
  cameraInput.capture = 'camera';
  cameraInput.id = 'camera-file-input';
  cameraInput.style.display = 'none';
  cameraInput.onchange = handleAvatarFile;
  document.body.appendChild(cameraInput);
}

function pickAvatarFromCamera() {
  const input = document.getElementById('camera-file-input');
  if (input) input.click();
  closeAvatarPicker();
}

function pickAvatarFromAlbum() {
  const input = document.getElementById('avatar-file-input');
  if (input) input.click();
  closeAvatarPicker();
}

function closeAvatarPicker() {
  const overlay = document.querySelector('.avatar-overlay');
  if (overlay) overlay.remove();
}

function handleAvatarFile(e) {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(event) {
    const user = getUserInfo() || {};
    user.avatar = event.target.result;
    try { localStorage.setItem(USER_KEY, JSON.stringify(user)); } catch(err) {}
    toast('头像已更新');
    showMineView();
  };
  reader.readAsDataURL(file);
  e.target.value = '';
}

function resetAvatarToTaiji() {
  const user = getUserInfo() || {};
  delete user.avatar;
  try { localStorage.setItem(USER_KEY, JSON.stringify(user)); } catch(e) {}
  toast('已恢复默认头像');
  showMineView();
  closeAvatarPicker();
}

async function changeNickname() {
  const currentName = getUserInfo()?.name || '';
  const name = await showPrompt('修改昵称：', currentName, '修改昵称');
  if (name === null || name === undefined) return;
  const trimmed = name.trim();
  if (!trimmed) { toast('昵称不能为空'); return; }
  if (trimmed.length < 2) { toast('昵称最少2个字符'); return; }
  if (trimmed.length > 20) { toast('昵称最多20个字符'); return; }
  const user = getUserInfo() || {};
  user.name = trimmed;
  try { localStorage.setItem(USER_KEY, JSON.stringify(user)); } catch(e) {}
  toast('昵称已更新');
  showMineView();
}
